import * as motion from 'motion/react-client';

/**
 * PriceBreakdown — shows original price, discount, coupon discount, and final total
 * Maps to payment_transactions.amount logic
 */
export default function PriceBreakdown({ plan, coupon = null }) {
    const originalPrice = plan.price;
    const planDiscount = plan.discountPercent ? originalPrice * (plan.discountPercent / 100) : 0;
    const afterPlanDiscount = originalPrice - planDiscount;

    let couponDiscount = 0;
    if (coupon) {
        if (coupon.discount_type === 'percentage') {
            couponDiscount = afterPlanDiscount * (coupon.discount_value / 100);
            if (coupon.max_discount_amount) {
                couponDiscount = Math.min(couponDiscount, coupon.max_discount_amount);
            }
        } else {
            couponDiscount = coupon.discount_value;
        }
    }

    const totalDiscount = planDiscount + couponDiscount;
    const finalPrice = Math.max(0, originalPrice - totalDiscount);

    const formatVND = (amount) => {
        if (amount === 0) return 'Miễn phí';
        return new Intl.NumberFormat('vi-VN').format(Math.round(amount)) + '₫';
    };

    const rows = [
        { label: 'Giá gốc', value: formatVND(originalPrice), type: 'normal' },
    ];

    if (planDiscount > 0) {
        rows.push({
            label: `Giảm giá gói (${plan.discountPercent}%)`,
            value: `- ${formatVND(planDiscount)}`,
            type: 'discount',
        });
    }

    if (couponDiscount > 0) {
        rows.push({
            label: `Mã giảm giá (${coupon.code})`,
            value: `- ${formatVND(couponDiscount)}`,
            type: 'discount',
        });
    }

    return (
        <div className="space-y-3">
            {rows.map((row, i) => (
                <motion.div
                    key={i}
                    initial={{ opacity: 0, x: -10 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: i * 0.1 }}
                    className="flex items-center justify-between text-sm"
                >
                    <span className="text-base-content/60 font-medium">{row.label}</span>
                    <span className={`font-bold ${row.type === 'discount' ? 'text-emerald-600' : 'text-base-content'
                        }`}>
                        {row.value}
                    </span>
                </motion.div>
            ))}

            {/* Divider */}
            <div className="border-t border-base-200 my-2" />

            {/* Total */}
            <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.3 }}
                className="flex items-center justify-between"
            >
                <span className="text-base font-black text-base-content">Tổng thanh toán</span>
                <div className="text-right">
                    <span className="text-2xl font-black bg-gradient-to-r from-violet-600 to-blue-600 bg-clip-text text-transparent">
                        {formatVND(finalPrice)}
                    </span>
                    {totalDiscount > 0 && (
                        <p className="text-xs text-emerald-600 font-bold">
                            Tiết kiệm {formatVND(totalDiscount)}
                        </p>
                    )}
                </div>
            </motion.div>
        </div>
    );
}

import * as motion from 'motion/react-client';

/**
 * ProgressBar - Animated progress bar component
 * 
 * @param {number} progress - Progress value (0-100)
 * @param {string} color - Gradient color class or solid color
 * @param {string} height - Height class (h-1, h-2, h-3, etc.)
 * @param {boolean} showLabel - Show progress percentage
 * @param {string} label - Custom label text
 * @param {boolean} animate - Enable animation
 * @param {number} delay - Animation delay
 */
export default function ProgressBar({
    progress = 0,
    color = 'bg-gradient-to-r from-blue-500 to-blue-600',
    height = 'h-2',
    showLabel = false,
    label,
    labelLeft,
    animate = true,
    delay = 0,
    className = ''
}) {
    const clampedProgress = Math.min(100, Math.max(0, progress));

    return (
        <div className={className}>
            {(showLabel || label || labelLeft) && (
                <div className="flex justify-between text-xs mb-1">
                    <span className="text-base-content/60">{labelLeft || label}</span>
                    {showLabel && (
                        <span className="font-bold text-base-content">
                            {Math.round(clampedProgress)}%
                        </span>
                    )}
                </div>
            )}
            <div className={`w-full bg-base-300 rounded-full ${height}`}>
                {animate ? (
                    <motion.div
                        initial={{ width: 0 }}
                        whileInView={{ width: `${clampedProgress}%` }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.8, delay }}
                        className={`${color} ${height} rounded-full`}
                    />
                ) : (
                    <div
                        className={`${color} ${height} rounded-full`}
                        style={{ width: `${clampedProgress}%` }}
                    />
                )}
            </div>
        </div>
    );
}

// Circular progress indicator
export function CircularProgress({
    progress = 0,
    size = 'md', // 'sm', 'md', 'lg'
    strokeWidth = 4,
    color = 'stroke-primary',
    bgColor = 'stroke-base-300',
    showValue = true,
    className = ''
}) {
    const sizes = {
        sm: 40,
        md: 60,
        lg: 80
    };

    const sizeValue = sizes[size] || sizes.md;
    const radius = (sizeValue - strokeWidth) / 2;
    const circumference = radius * 2 * Math.PI;
    const offset = circumference - (progress / 100) * circumference;

    return (
        <div className={`relative inline-flex items-center justify-center ${className}`}>
            <svg width={sizeValue} height={sizeValue} className="-rotate-90">
                {/* Background circle */}
                <circle
                    cx={sizeValue / 2}
                    cy={sizeValue / 2}
                    r={radius}
                    strokeWidth={strokeWidth}
                    fill="none"
                    className={bgColor}
                />
                {/* Progress circle */}
                <motion.circle
                    cx={sizeValue / 2}
                    cy={sizeValue / 2}
                    r={radius}
                    strokeWidth={strokeWidth}
                    fill="none"
                    className={color}
                    strokeLinecap="round"
                    initial={{ strokeDashoffset: circumference }}
                    animate={{ strokeDashoffset: offset }}
                    style={{
                        strokeDasharray: circumference
                    }}
                    transition={{ duration: 1, ease: 'easeOut' }}
                />
            </svg>
            {showValue && (
                <span className="absolute text-sm font-bold">
                    {Math.round(progress)}%
                </span>
            )}
        </div>
    );
}

