function formatPrice(amount) {
    if (amount === 0 || !amount) return 'Miễn phí';
    if (amount >= 1_000_000) {
        return (amount / 1_000_000).toFixed(1).replace('.0', '') + 'M';
    }
    return amount.toLocaleString('vi-VN') + '₫';
}

