                        <span className="w-1 h-1 rounded-full bg-base-300" />
                        <span className="flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider">
                            <Lock className="w-3 h-3" /> Thanh toán an toàn
                        </span>
                    </div>
