            <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => onNext('correct')}
                className="btn btn-lg bg-green-500 hover:bg-green-600 text-white border-none rounded-2xl px-8 gap-2"
            >
