            {/* Next Button */}
            <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={onSkip}
                disabled={!canGoNext}
                className="btn btn-circle btn-lg btn-ghost disabled:opacity-30"
