                    </motion.button>
                    <div>
                        <h2 className="text-xl font-black text-base-content">{deckName}</h2>
                        <p className="text-sm text-base-content/60">
                            Thẻ {currentIndex + 1} / {totalCards}
                        </p>
                    </div>
                </div>

                {/* Progress and Stats */}
                <div className="flex items-center gap-6">
                    <div className="flex items-center gap-4 text-sm">
                        <span className="flex items-center gap-1 text-green-500 font-bold">
                            <Icon name="CheckCircle2" size="sm" />
                            {stats.correct}
                        </span>
                        <span className="flex items-center gap-1 text-red-500 font-bold">
                            <Icon name="XCircle" size="sm" />
                            {stats.incorrect}
                        </span>
                    </div>
                    <div className="w-48 bg-base-300 rounded-full h-2">
                        <motion.div
                            initial={{ width: 0 }}
                            animate={{ width: `${progress}%` }}
                            className="bg-gradient-to-r from-blue-600 to-violet-600 h-2 rounded-full"
                        />
                    </div>
                </div>
            </div>
        </motion.header>
    );
}

