    BarChart3,
    Zap,
} from 'lucide-react';

/**
 * LearnProgressView - Full analytics dashboard for course progress.
 * Displayed in main content area when "Tiến độ" tab is selected.
 *
 * @param {Array}    chapters         - Chapters with lessons data
 * @param {object}   completedLessons - Map of completed lessons
 * @param {string}   courseGradient   - Course gradient class
 * @param {string}   courseTitle      - Course title
 * @param {string}   courseIcon       - Course emoji
 * @param {string}   expertName       - Expert name
 * @param {string}   expertAvatar     - Expert avatar URL
 */
export default function LearnProgressView({
    chapters = [],
    completedLessons = {},
    courseGradient = 'from-blue-500 to-violet-500',
    courseTitle = '',
    courseIcon = '📚',
    expertName = '',
    expertAvatar = '',
}) {
    const containerVariants = {
        hidden: { opacity: 0 },
        visible: { opacity: 1, transition: { staggerChildren: 0.06, delayChildren: 0.1 } },
    };
    const itemVariants = {
        hidden: { opacity: 0, y: 16 },
        visible: { opacity: 1, y: 0, transition: { duration: 0.45, ease: [0.25, 0.46, 0.45, 0.94] } },
    };

    // ─── Computed Stats ──────────────────────────────────
    const totalLessons = chapters.reduce((a, ch) => a + ch.lessons.length, 0);
    const totalCompleted = Object.keys(completedLessons).length;
    const overallPercent = totalLessons > 0 ? Math.round((totalCompleted / totalLessons) * 100) : 0;

    const typeStats = useMemo(() => {
        const s = { video: { done: 0, total: 0, mins: 0 }, document: { done: 0, total: 0, mins: 0 }, flashcard: { done: 0, total: 0, mins: 0 }, quiz: { done: 0, total: 0, mins: 0 } };
        chapters.forEach((ch, ci) => {
            ch.lessons.forEach((l, li) => {
                const t = l.type || 'video';
                if (s[t]) {
                    s[t].total++;
                    s[t].mins += l.durationMinutes || 0;
                    if (completedLessons[`${ci}-${li}`]) s[t].done++;
                }
            });
        });
        return s;
    }, [chapters, completedLessons]);

    const totalMinutes = chapters.reduce((a, ch) => a + ch.lessons.reduce((b, l) => b + (l.durationMinutes || 0), 0), 0);
    const completedMinutes = useMemo(() => {
        let m = 0;
        chapters.forEach((ch, ci) => ch.lessons.forEach((l, li) => {
            if (completedLessons[`${ci}-${li}`]) m += l.durationMinutes || 0;
        }));
        return m;
    }, [chapters, completedLessons]);
    const remainingMinutes = totalMinutes - completedMinutes;

    const chapterProgress = useMemo(() => {
        return chapters.map((ch, ci) => {
            const done = ch.lessons.filter((_, li) => completedLessons[`${ci}-${li}`]).length;
            return {
                title: ch.title,
                done,
                total: ch.lessons.length,
                percent: ch.lessons.length > 0 ? Math.round((done / ch.lessons.length) * 100) : 0,
                lessons: ch.lessons.map((l, li) => ({
                    ...l,
                    completed: !!completedLessons[`${ci}-${li}`],
                })),
            };
        });
    }, [chapters, completedLessons]);

    // Mock data for richer analytics
    const weeklyStudyData = [
        { day: 'T2', minutes: 45 }, { day: 'T3', minutes: 30 }, { day: 'T4', minutes: 65 },
        { day: 'T5', minutes: 20 }, { day: 'T6', minutes: 50 }, { day: 'T7', minutes: 80 },
        { day: 'CN', minutes: 35 },
    ];
    const maxWeekly = Math.max(...weeklyStudyData.map(d => d.minutes));

    const mockScores = [
        { label: 'Bài tập 1', score: 75, type: 'quiz' },
        { label: 'KT Chương 1', score: 82, type: 'test' },
        { label: 'Bài tập 2', score: 68, type: 'quiz' },
        { label: 'KT Chương 2', score: 90, type: 'test' },
        { label: 'Bài tập 3', score: 85, type: 'quiz' },
        { label: 'KT Chương 3', score: 95, type: 'test' },
    ];
    const avgScore = Math.round(mockScores.reduce((a, s) => a + s.score, 0) / mockScores.length);

    const circumference = 2 * Math.PI * 52;

    return (
        <motion.div
            className="max-w-5xl mx-auto px-6 py-6 space-y-6"
            variants={containerVariants}
            initial="hidden"
            animate="visible"
        >
            {/* ─── Hero Section ───────────────────────────────── */}
            <motion.div variants={itemVariants} className="bg-base-100 rounded-3xl border border-base-300 shadow-sm overflow-hidden">
                <div className={`h-2 bg-gradient-to-r ${courseGradient}`} />
                <div className="p-6 flex flex-col md:flex-row items-center gap-6">
                    {/* Circular progress */}
                    <div className="relative w-32 h-32 flex-shrink-0">
                        <svg className="w-full h-full transform -rotate-90">
                            <circle cx="64" cy="64" r="52" stroke="currentColor" strokeWidth="7" fill="none" className="text-base-200" />
                            <motion.circle
                                cx="64" cy="64" r="52" stroke="url(#heroGrad)" strokeWidth="7"
                                fill="none" strokeDasharray={circumference} strokeLinecap="round"
                                initial={{ strokeDashoffset: circumference }}
                                animate={{ strokeDashoffset: circumference * (1 - overallPercent / 100) }}
                                transition={{ duration: 1.5, ease: 'easeInOut', delay: 0.3 }}
                            />
                            <defs>
                                <linearGradient id="heroGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                                    <stop offset="0%" stopColor="#3b82f6" />
                                    <stop offset="100%" stopColor="#8b5cf6" />
                                </linearGradient>
                            </defs>
                        </svg>
                        <div className="absolute inset-0 flex flex-col items-center justify-center">
                            <span className="text-3xl font-black text-base-content">{overallPercent}%</span>
                            <span className="text-[10px] text-base-content/40 font-bold">Hoàn thành</span>
                        </div>
                    </div>

                    {/* Course info */}
                    <div className="flex-1 text-center md:text-left min-w-0">
                        <div className="flex items-center justify-center md:justify-start gap-2 mb-1">
                            <span className="text-2xl">{courseIcon}</span>
                            <h2 className="text-xl font-black text-base-content">{courseTitle}</h2>
                        </div>
                        <div className="flex items-center justify-center md:justify-start gap-2 mb-3">
                            <img src={expertAvatar || 'https://i.pravatar.cc/150?img=12'} alt="" className="w-5 h-5 rounded-full" />
                            <span className="text-sm text-base-content/50 font-medium">{expertName}</span>
                        </div>
                        <div className="flex flex-wrap items-center justify-center md:justify-start gap-4 text-sm">
                            <HeroStat icon={BookOpen} value={`${totalCompleted}/${totalLessons}`} label="bài học" />
                            <HeroStat icon={Clock} value={`${Math.floor(completedMinutes / 60)}h ${completedMinutes % 60}p`} label="đã học" />
                            <HeroStat icon={Target} value={`${avgScore}%`} label="điểm TB" />
                            <HeroStat icon={Flame} value={`~${Math.floor(remainingMinutes / 60)}h ${remainingMinutes % 60}p`} label="còn lại" />
                        </div>
                    </div>
                </div>
            </motion.div>

            {/* ─── Stats Cards Row ────────────────────────────── */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard variants={itemVariants} icon={Play} label="Video" done={typeStats.video.done} total={typeStats.video.total} color="blue" gradient={courseGradient} />
                <StatCard variants={itemVariants} icon={FileText} label="Tài liệu" done={typeStats.document.done} total={typeStats.document.total} color="emerald" gradient={courseGradient} />
                <StatCard variants={itemVariants} icon={Sparkles} label="Flashcards" done={typeStats.flashcard.done} total={typeStats.flashcard.total} color="amber" gradient={courseGradient} />
                <StatCard variants={itemVariants} icon={CheckCircle2} label="Bài kiểm tra" done={typeStats.quiz.done} total={typeStats.quiz.total} color="violet" gradient={courseGradient} />
            </div>

            {/* ─── Two Column Layout ─────────────────────────── */}
            <div className="grid grid-cols-1 xl:grid-cols-5 gap-6">
                {/* Left: Charts */}
                <div className="xl:col-span-3 space-y-6">
                    {/* Weekly study time */}
                    <motion.div variants={itemVariants} className="bg-base-100 rounded-2xl border border-base-300 p-5 shadow-sm">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="text-sm font-black text-base-content">Thời gian học tuần này</h3>
                            <span className="text-[11px] font-bold text-base-content/40">
                                Tổng: {weeklyStudyData.reduce((a, d) => a + d.minutes, 0)} phút
                            </span>
                        </div>
                        <div className="flex items-end gap-2" style={{ height: 144 }}>
                            {weeklyStudyData.map((d, i) => {
                                const barH = Math.max(6, Math.round((d.minutes / maxWeekly) * 128));
                                return (
                                    <div key={i} className="flex-1 flex flex-col items-center justify-end h-full gap-1">
                                        <span className="text-[9px] font-bold text-base-content/50">{d.minutes}p</span>
                                        <motion.div
                                            initial={{ height: 0 }}
                                            animate={{ height: barH }}
                                            transition={{ duration: 0.6, delay: 0.2 + i * 0.06 }}
                                            className={`w-full rounded-lg bg-gradient-to-t ${courseGradient} opacity-80 hover:opacity-100 transition-opacity cursor-pointer`}
                                            title={`${d.day}: ${d.minutes} phút`}
                                        />
                                        <span className="text-[9px] font-bold text-base-content/40">{d.day}</span>
                                    </div>
                                );
                            })}
                        </div>
                    </motion.div>

                    {/* Score history */}
                    <motion.div variants={itemVariants} className="bg-base-100 rounded-2xl border border-base-300 p-5 shadow-sm">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="text-sm font-black text-base-content">Lịch sử điểm số</h3>
                            <div className="flex items-center gap-2">
                                <span className="px-2 py-0.5 rounded-md bg-blue-500/10 text-[10px] font-bold text-blue-600">TB: {avgScore}%</span>
                                <span className="px-2 py-0.5 rounded-md bg-green-500/10 text-[10px] font-bold text-green-600">
                                    Cao nhất: {Math.max(...mockScores.map(s => s.score))}%
                                </span>
                            </div>
                        </div>
                        <div className="flex items-end gap-3" style={{ height: 160 }}>
                            {mockScores.map((s, i) => {
                                const isTest = s.type === 'test';
                                const barH = Math.max(6, Math.round((s.score / 100) * 130));
                                return (
                                    <div key={i} className="flex-1 flex flex-col items-center justify-end h-full gap-1 group relative">
                                        {/* Tooltip */}
                                        <div className="absolute -top-2 opacity-0 group-hover:opacity-100 transition-opacity bg-base-content text-base-100 px-2 py-1 rounded-lg text-[10px] font-bold whitespace-nowrap z-10">
                                            {s.label}: {s.score}%
                                        </div>
                                        <span className="text-[9px] font-bold text-base-content/50">{s.score}%</span>
                                        <motion.div
                                            initial={{ height: 0 }}
                                            animate={{ height: barH }}
                                            transition={{ duration: 0.5, delay: 0.3 + i * 0.08 }}
                                            className={`w-full rounded-lg ${isTest ? `bg-gradient-to-t ${courseGradient}` : 'bg-base-content/15'} hover:opacity-100 opacity-85 transition-opacity cursor-pointer`}
                                        />
                                        <span className="text-[8px] font-bold text-base-content/30 truncate max-w-full">{s.label}</span>
                                    </div>
                                );
                            })}
                        </div>
                        <div className="flex items-center justify-center gap-5 mt-3 pt-3 border-t border-base-200">
                            <div className="flex items-center gap-1.5">
                                <div className={`w-3 h-3 rounded bg-gradient-to-r ${courseGradient}`} />
                                <span className="text-[10px] text-base-content/50 font-bold">Bài kiểm tra</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 rounded bg-base-content/12" />
                                <span className="text-[10px] text-base-content/50 font-bold">Bài tập</span>
                            </div>
                        </div>
                    </motion.div>

                    {/* Chapter breakdown */}
                    <motion.div variants={itemVariants} className="bg-base-100 rounded-2xl border border-base-300 p-5 shadow-sm">
                        <h3 className="text-sm font-black text-base-content mb-4">Tiến độ theo chương</h3>
                        <div className="space-y-2">
                            {chapterProgress.map((ch, i) => (
                                <ChapterRow key={i} chapter={ch} index={i} gradient={courseGradient} />
                            ))}
                        </div>
                    </motion.div>
                </div>

                {/* Right: Sidebar insights */}
                <div className="xl:col-span-2 space-y-6">
                    {/* AI insights */}
                    <motion.div variants={itemVariants} className="bg-base-100 rounded-2xl border border-base-300 p-5 shadow-sm">
                        <div className="flex items-center gap-2 mb-4">
                            <Brain className="w-4 h-4 text-violet-500" />
                            <h3 className="text-sm font-black text-base-content">Phân tích AI</h3>
                            <span className="ml-auto badge badge-xs badge-warning font-bold">Premium</span>
                        </div>
                        <div className="space-y-3">
                            <InsightItem emoji="💪" title="Điểm mạnh" text="Bạn nắm chắc các chương đầu, tỉ lệ chính xác cao ở bài kiểm tra." color="green" />
                            <InsightItem emoji="⚠️" title="Cần cải thiện" text="Các bài Flashcard chưa được ôn tập. Nên ôn lại để nhớ lâu hơn." color="red" />
                            <InsightItem emoji="💡" title="Gợi ý" text={`Với tốc độ hiện tại, bạn sẽ hoàn thành môn này trong khoảng ${Math.ceil(remainingMinutes / 45)} buổi học nữa.`} color="blue" />
                            <InsightItem emoji="🎯" title="Mục tiêu" text={`Điểm TB hiện tại: ${avgScore}%. Cố gắng đạt 85%+ để đạt loại Giỏi.`} color="violet" />
                        </div>
                    </motion.div>

                    {/* Achievements / milestones */}
                    <motion.div variants={itemVariants} className="bg-base-100 rounded-2xl border border-base-300 p-5 shadow-sm">
                        <div className="flex items-center gap-2 mb-4">
                            <Award className="w-4 h-4 text-amber-500" />
                            <h3 className="text-sm font-black text-base-content">Thành tựu</h3>
                        </div>
                        <div className="space-y-2.5">
                            <AchievementItem icon="🔥" label="Streak 5 ngày" unlocked />
                            <AchievementItem icon="📖" label="Hoàn thành chương đầu tiên" unlocked />
                            <AchievementItem icon="🎯" label={`Đạt ${avgScore >= 80 ? '80%' : '70%'}+ điểm TB`} unlocked={avgScore >= 70} />
                            <AchievementItem icon="⚡" label="Học liên tục 7 ngày" unlocked={false} />
                            <AchievementItem icon="🏆" label="Hoàn thành toàn bộ môn học" unlocked={overallPercent === 100} />
                        </div>
                    </motion.div>

                    {/* Study time by type */}
                    <motion.div variants={itemVariants} className="bg-base-100 rounded-2xl border border-base-300 p-5 shadow-sm">
                        <div className="flex items-center gap-2 mb-4">
                            <BarChart3 className="w-4 h-4 text-blue-500" />
                            <h3 className="text-sm font-black text-base-content">Thời gian theo loại</h3>
                        </div>
                        <div className="space-y-3">
                            {[
                                { label: 'Video bài giảng', mins: typeStats.video.mins, color: 'blue', icon: Play },
                                { label: 'Tài liệu', mins: typeStats.document.mins, color: 'emerald', icon: FileText },
                                { label: 'Flashcards', mins: typeStats.flashcard.mins, color: 'amber', icon: Sparkles },
                                { label: 'Bài kiểm tra', mins: typeStats.quiz.mins, color: 'violet', icon: CheckCircle2 },
                            ].map((item, i) => {
                                const maxMins = Math.max(typeStats.video.mins, typeStats.document.mins, typeStats.flashcard.mins, typeStats.quiz.mins, 1);
                                const barPercent = (item.mins / maxMins) * 100;
                                const ItemIcon = item.icon;
                                return (
                                    <div key={i}>
                                        <div className="flex items-center justify-between text-[11px] mb-1">
                                            <span className="flex items-center gap-1.5 text-base-content/60 font-medium">
                                                <ItemIcon className={`w-3 h-3 text-${item.color}-500`} />
                                                {item.label}
                                            </span>
                                            <span className="font-bold text-base-content">{item.mins}p</span>
                                        </div>
                                        <div className="w-full h-1.5 rounded-full bg-base-200 overflow-hidden">
                                            <motion.div
                                                initial={{ width: 0 }}
                                                animate={{ width: `${barPercent}%` }}
                                                transition={{ duration: 0.6, delay: 0.3 + i * 0.1 }}
                                                className={`h-full rounded-full bg-${item.color}-500`}
                                            />
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </motion.div>

                    {/* Motivation card */}
                    <motion.div variants={itemVariants}>
                        <div className={`p-5 rounded-2xl bg-gradient-to-br ${courseGradient} text-white shadow-md`}>
                            <div className="flex items-center gap-2 mb-2">
                                <Zap className="w-4 h-4" />
                                <span className="text-sm font-black">
                                    {overallPercent >= 80 ? 'Sắp hoàn thành!' : overallPercent >= 50 ? 'Nửa chặng đường!' : 'Tiếp tục nào!'}
                                </span>
                            </div>
                            <p className="text-[12px] opacity-85 leading-relaxed">
                                {overallPercent >= 80
                                    ? `Chỉ còn ${totalLessons - totalCompleted} bài nữa thôi. Bạn sắp chinh phục xong môn này rồi! 🎉`
                                    : overallPercent >= 50
                                        ? `Đã hoàn thành ${totalCompleted} bài. Cố gắng thêm một chút nữa để vượt qua mốc 80%! 💪`
                                        : `Mỗi ngày tiến bộ một chút, bạn sẽ sớm nắm vững kiến thức. Bạn đang làm rất tốt! 🌱`}
                            </p>
                        </div>
                    </motion.div>
                </div>
            </div>
        </motion.div>
    );
}

// ─── Sub-components ──────────────────────────────────────

function HeroStat({ icon: Icon, value, label }) {
    return (
        <div className="flex items-center gap-1.5">
            <Icon className="w-4 h-4 text-base-content/30" />
            <span className="text-sm font-black text-base-content">{value}</span>
            <span className="text-xs text-base-content/40 font-medium">{label}</span>
        </div>
    );
}

function StatCard({ variants, icon: Icon, label, done, total, color, gradient }) {
    const percent = total > 0 ? Math.round((done / total) * 100) : 0;
    return (
        <motion.div variants={variants} className="bg-base-100 rounded-2xl border border-base-300 p-4 shadow-sm">
            <div className="flex items-center gap-2 mb-2">
                <div className={`w-7 h-7 rounded-lg bg-${color}-500/10 flex items-center justify-center`}>
                    <Icon className={`w-3.5 h-3.5 text-${color}-500`} />
                </div>
                <span className="text-[11px] font-bold text-base-content/50">{label}</span>
            </div>
            <p className="text-xl font-black text-base-content mb-1">{done}/{total}</p>
            <div className="w-full h-1.5 rounded-full bg-base-200 overflow-hidden">
                <motion.div
                    initial={{ width: 0 }}
                    animate={{ width: `${percent}%` }}
                    transition={{ duration: 0.6, delay: 0.3 }}
                    className={`h-full rounded-full bg-gradient-to-r ${gradient}`}
                />
            </div>
        </motion.div>
    );
}

function ChapterRow({ chapter, index, gradient }) {
    const [expanded, setExpanded] = useState(false);
    const isComplete = chapter.percent === 100;

    return (
        <div className="bg-base-200/30 rounded-xl overflow-hidden">
            <button
                onClick={() => setExpanded(!expanded)}
                className="w-full flex items-center gap-3 p-3 hover:bg-base-200/50 transition-colors text-left"
            >
                <div className={`w-7 h-7 rounded-lg flex items-center justify-center text-[10px] font-black flex-shrink-0
                    ${isComplete ? 'bg-green-500/10 text-green-600' : `bg-gradient-to-br ${gradient} text-white shadow-sm`}`}>
                    {isComplete ? <CircleCheck className="w-3.5 h-3.5" /> : index + 1}
                </div>
                <div className="flex-1 min-w-0">
                    <p className="text-xs font-bold text-base-content truncate">{chapter.title}</p>
                    <p className="text-[10px] text-base-content/40 font-medium">{chapter.done}/{chapter.total} bài</p>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0">
                    <div className="w-14 h-1.5 rounded-full bg-base-200 overflow-hidden hidden sm:block">
                        <motion.div
                            initial={{ width: 0 }}
                            animate={{ width: `${chapter.percent}%` }}
                            transition={{ duration: 0.5, delay: index * 0.05 }}
                            className={`h-full rounded-full bg-gradient-to-r ${gradient}`}
                        />
                    </div>
                    <span className="text-[10px] font-bold text-base-content/50 w-7 text-right">{chapter.percent}%</span>
                    <ChevronDown className={`w-3.5 h-3.5 text-base-content/30 transition-transform ${expanded ? 'rotate-180' : ''}`} />
                </div>
            </button>

            <motion.div
                initial={false}
                animate={{ height: expanded ? 'auto' : 0, opacity: expanded ? 1 : 0 }}
                transition={{ duration: 0.3 }}
                className="overflow-hidden"
            >
                <div className="px-3 pb-3 space-y-1">
                    {chapter.lessons.map((l, li) => {
                        const typeIcons = { video: Play, document: FileText, flashcard: Sparkles, quiz: CheckCircle2 };
                        const TIcon = typeIcons[l.type] || Play;
                        return (
                            <div key={li} className="flex items-center gap-2 px-2 py-1.5 rounded-lg">
                                {l.completed
                                    ? <CheckCircle2 className="w-3.5 h-3.5 text-green-500 flex-shrink-0" />
                                    : <Circle className="w-3.5 h-3.5 text-base-content/20 flex-shrink-0" />
                                }
                                <TIcon className={`w-3 h-3 ${l.completed ? 'text-base-content/30' : 'text-base-content/40'} flex-shrink-0`} />
                                <span className={`text-[11px] truncate ${l.completed ? 'text-base-content/40 line-through' : 'text-base-content/70 font-medium'}`}>
                                    {l.title}
                                </span>
                                {l.durationMinutes && (
                                    <span className="ml-auto text-[9px] text-base-content/30 font-medium flex-shrink-0">{l.durationMinutes}p</span>
                                )}
                            </div>
                        );
                    })}
                </div>
            </motion.div>
        </div>
    );
}

function InsightItem({ emoji, title, text, color }) {
    return (
        <div className={`p-3 rounded-xl bg-${color}-500/5 border border-${color}-500/10`}>
            <p className={`text-[11px] font-bold text-${color}-600 mb-0.5`}>{emoji} {title}</p>
            <p className="text-[11px] text-base-content/60 leading-relaxed">{text}</p>
        </div>
    );
}

function AchievementItem({ icon, label, unlocked }) {
    return (
        <div className={`flex items-center gap-3 p-2.5 rounded-xl transition-colors ${unlocked ? 'bg-amber-500/5' : 'bg-base-200/30 opacity-50'}`}>
            <span className={`text-lg ${unlocked ? '' : 'grayscale'}`}>{icon}</span>
            <span className={`text-xs font-semibold flex-1 ${unlocked ? 'text-base-content' : 'text-base-content/40'}`}>{label}</span>
            {unlocked && <CheckCircle2 className="w-3.5 h-3.5 text-amber-500 flex-shrink-0" />}
        </div>
    );
}

import { useState, useEffect } from 'react';
import * as motion from 'motion/react-client';
import {
    ChevronDown,
    Play,
    FileText,
    Sparkles,
    CheckCircle2,
    Clock,
    CircleCheck,
    BookOpen,
    TrendingUp,
    PanelLeftClose,
    PanelLeftOpen,
} from 'lucide-react';

const LEARN_SIDEBAR_KEY = 'skr-learn-sidebar-collapsed';

/**
 * LearnSidebar - Collapsible sidebar with Curriculum & Progress tabs.
 * Apple-style clean design with PanelLeftClose/PanelLeftOpen toggle.
 */
export default function LearnSidebar({
    chapters = [],
    activeChapter = 0,
    activeLesson = 0,
    completedLessons = {},
    onLessonSelect,
    courseGradient = 'from-blue-500 to-violet-500',
    courseIcon = '📚',
    courseTitle = '',
    viewMode = 'learn',
    onViewModeChange,
}) {
    const [collapsed, setCollapsed] = useState(() => {
        try { return localStorage.getItem(LEARN_SIDEBAR_KEY) === 'true'; } catch { return false; }
    });

    useEffect(() => {
        try { localStorage.setItem(LEARN_SIDEBAR_KEY, collapsed); } catch { }
    }, [collapsed]);

    const totalLessons = chapters.reduce((a, ch) => a + ch.lessons.length, 0);
    const totalCompleted = Object.keys(completedLessons).length;
    const overallProgress = totalLessons > 0
        ? Math.round((totalCompleted / totalLessons) * 100)
        : 0;

    const handleTabClick = (mode) => {
        onViewModeChange?.(mode);
    };

    // ─── Collapsed View ──────────────────────────────────
    if (collapsed) {
        return (
            <motion.aside
                initial={{ x: -80, opacity: 0 }}
                animate={{ x: 0, opacity: 1, width: 64 }}
                transition={{ duration: 0.3, ease: [0.25, 0.46, 0.45, 0.94] }}
                className="bg-base-100 border-r border-base-300 flex flex-col h-full flex-shrink-0 overflow-hidden"
            >
                {/* Course icon */}
                <div className="p-3 border-b border-base-300 flex flex-col items-center gap-2 flex-shrink-0">
                    <div className={`w-10 h-10 rounded-xl bg-gradient-to-br ${courseGradient} flex items-center justify-center text-lg shadow-md`}>
                        {courseIcon}
                    </div>
                </div>

                {/* Toggle button */}
                <div className="flex justify-center pt-3">
                    <button
                        onClick={() => setCollapsed(false)}
                        className="w-8 h-8 rounded-lg flex items-center justify-center text-base-content/40 hover:text-base-content hover:bg-base-200 transition-all"
                        title="Mở rộng sidebar"
                    >
                        <PanelLeftOpen className="w-4 h-4" />
                    </button>
                </div>

                {/* Tab icons */}
                <div className="flex flex-col items-center gap-1 p-2 border-b border-base-300 mt-1">
                    <button
                        onClick={() => handleTabClick('learn')}
                        className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all group relative
                            ${viewMode === 'learn' ? 'bg-base-200 text-base-content' : 'text-base-content/40 hover:text-base-content hover:bg-base-200/50'}`}
                    >
                        <BookOpen className="w-4 h-4" />
                        <div className="absolute left-full ml-3 px-3 py-1.5 rounded-xl bg-base-content text-base-100 text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-[60] shadow-xl">
                            Chương trình
                            <div className="absolute top-1/2 -left-1 -translate-y-1/2 w-2 h-2 rotate-45 bg-base-content" />
                        </div>
                    </button>
                    <button
                        onClick={() => handleTabClick('progress')}
                        className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all group relative
                            ${viewMode === 'progress' ? 'bg-base-200 text-base-content' : 'text-base-content/40 hover:text-base-content hover:bg-base-200/50'}`}
                    >
                        <TrendingUp className="w-4 h-4" />
                        <div className="absolute left-full ml-3 px-3 py-1.5 rounded-xl bg-base-content text-base-100 text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-[60] shadow-xl">
                            Tiến độ
                            <div className="absolute top-1/2 -left-1 -translate-y-1/2 w-2 h-2 rotate-45 bg-base-content" />
                        </div>
                    </button>
                </div>

                {/* Chapter numbers */}
                <div className="flex-1 overflow-y-auto py-2 flex flex-col items-center gap-1 px-2">
                    {chapters.map((chapter, chIdx) => {
                        const chCompleted = chapter.lessons.every(
                            (_, lIdx) => completedLessons[`${chIdx}-${lIdx}`]
                        );
                        const isChActive = chIdx === activeChapter;

                        return (
                            <button
                                key={chIdx}
                                onClick={() => {
                                    if (viewMode !== 'learn') handleTabClick('learn');
                                    onLessonSelect?.(chIdx, 0);
                                }}
                                className={`w-10 h-10 rounded-xl flex items-center justify-center text-[11px] font-black transition-all group relative
                                    ${chCompleted
                                        ? 'bg-green-500/10 text-green-600'
                                        : isChActive
                                            ? `bg-gradient-to-br ${courseGradient} text-white shadow-sm`
                                            : 'bg-base-200/50 text-base-content/40 hover:bg-base-200 hover:text-base-content'
                                    }`}
                            >
                                {chCompleted ? <CircleCheck className="w-4 h-4" /> : chIdx + 1}
                                <div className="absolute left-full ml-3 px-3 py-1.5 rounded-xl bg-base-content text-base-100 text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-[60] shadow-xl max-w-[200px] truncate">
                                    {chapter.title}
                                    <div className="absolute top-1/2 -left-1 -translate-y-1/2 w-2 h-2 rotate-45 bg-base-content" />
                                </div>
                            </button>
                        );
                    })}
                </div>

                {/* Mini progress */}
                <div className="p-2 border-t border-base-300 flex flex-col items-center">
                    <div className="relative w-10 h-10">
                        <svg className="w-full h-full transform -rotate-90">
                            <circle cx="20" cy="20" r="16" stroke="currentColor" strokeWidth="3" fill="none" className="text-base-200" />
                            <circle
                                cx="20" cy="20" r="16" stroke="url(#miniGrad)" strokeWidth="3"
                                fill="none" strokeDasharray={2 * Math.PI * 16} strokeLinecap="round"
                                strokeDashoffset={2 * Math.PI * 16 * (1 - overallProgress / 100)}
                            />
                            <defs>
                                <linearGradient id="miniGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                                    <stop offset="0%" stopColor="#3b82f6" />
                                    <stop offset="100%" stopColor="#8b5cf6" />
                                </linearGradient>
                            </defs>
                        </svg>
                        <span className="absolute inset-0 flex items-center justify-center text-[8px] font-black text-base-content">
                            {overallProgress}%
                        </span>
                    </div>
                </div>
            </motion.aside>
        );
    }

    // ─── Expanded View ───────────────────────────────────
    return (
        <motion.aside
            initial={{ x: -340, opacity: 0 }}
            animate={{ x: 0, opacity: 1, width: 340 }}
            transition={{ duration: 0.3, ease: [0.25, 0.46, 0.45, 0.94] }}
            className="bg-base-100 border-r border-base-300 flex flex-col h-full flex-shrink-0 overflow-hidden"
        >
            {/* Course info header */}
            <div className="p-5 border-b border-base-300 flex-shrink-0">
                <div className="flex items-center gap-3 mb-3">
                    <div className={`w-10 h-10 rounded-xl bg-gradient-to-br ${courseGradient} flex items-center justify-center text-lg shadow-md flex-shrink-0`}>
                        {courseIcon}
                    </div>
                    <div className="flex-1 min-w-0">
                        <h3 className="text-sm font-black text-base-content truncate">
                            {courseTitle}
                        </h3>
                        <p className="text-[11px] text-base-content/50 font-medium">
                            {totalCompleted}/{totalLessons} bài hoàn thành
                        </p>
                    </div>
                    <button
                        onClick={() => setCollapsed(true)}
                        className="w-8 h-8 rounded-lg flex items-center justify-center text-base-content/40 hover:text-base-content hover:bg-base-200 transition-all flex-shrink-0"
                        title="Thu gọn sidebar"
                    >
                        <PanelLeftClose className="w-4 h-4" />
                    </button>
                </div>

                {/* Progress bar */}
                <div className="flex items-center gap-2.5 mb-3">
                    <div className="flex-1 h-1.5 rounded-full bg-base-200 overflow-hidden">
                        <motion.div
                            initial={{ width: 0 }}
                            animate={{ width: `${overallProgress}%` }}
                            transition={{ duration: 0.8, delay: 0.3 }}
                            className={`h-full rounded-full bg-gradient-to-r ${courseGradient}`}
                        />
                    </div>
                    <span className="text-[11px] font-bold text-base-content/50">
                        {overallProgress}%
                    </span>
                </div>

                {/* Tabs */}
                <div className="flex bg-base-200 rounded-xl p-0.5">
                    <TabButton
                        icon={BookOpen}
                        label="Chương trình"
                        active={viewMode === 'learn'}
                        onClick={() => handleTabClick('learn')}
                    />
                    <TabButton
                        icon={TrendingUp}
                        label="Tiến độ"
                        active={viewMode === 'progress'}
                        onClick={() => handleTabClick('progress')}
                    />
                </div>
            </div>

            {/* Curriculum */}
            <div className="flex-1 overflow-y-auto">
                <CurriculumPanel
                    chapters={chapters}
                    activeChapter={activeChapter}
                    activeLesson={activeLesson}
                    completedLessons={completedLessons}
                    onLessonSelect={(chIdx, lIdx) => {
                        if (viewMode !== 'learn') handleTabClick('learn');
                        onLessonSelect?.(chIdx, lIdx);
                    }}
                    courseGradient={courseGradient}
                />
            </div>
        </motion.aside>
    );
}

// ─── Tab Button ──────────────────────────────────────────

function TabButton({ icon: Icon, label, active, onClick }) {
    return (
        <button
            onClick={onClick}
            className={`flex-1 flex items-center justify-center gap-1.5 py-2 px-3 rounded-lg text-[11px] font-bold transition-all
                ${active
                    ? 'bg-base-100 text-base-content shadow-sm'
                    : 'text-base-content/40 hover:text-base-content/60'
                }`}
        >
            <Icon className="w-3.5 h-3.5" />
            {label}
        </button>
    );
}

// ═══════════════════════════════════════════════════════════
// CURRICULUM PANEL
// ═══════════════════════════════════════════════════════════

function CurriculumPanel({
    chapters,
    activeChapter,
    activeLesson,
    completedLessons,
    onLessonSelect,
    courseGradient,
}) {
    const [expandedChapters, setExpandedChapters] = useState(
        () => new Set([activeChapter])
    );

    const toggleChapter = (idx) => {
        setExpandedChapters(prev => {
            const next = new Set(prev);
            if (next.has(idx)) next.delete(idx);
            else next.add(idx);
            return next;
        });
    };

    return (
        <div className="py-2">
            {chapters.map((chapter, chIdx) => {
                const isExpanded = expandedChapters.has(chIdx);
                const chapterCompleted = chapter.lessons.every(
                    (_, lIdx) => completedLessons[`${chIdx}-${lIdx}`]
                );
                const chapterLessonsCompleted = chapter.lessons.filter(
                    (_, lIdx) => completedLessons[`${chIdx}-${lIdx}`]
                ).length;

                return (
                    <div key={chIdx} className="px-2">
                        <button
                            onClick={() => toggleChapter(chIdx)}
                            className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-left transition-colors
                                ${isExpanded ? 'bg-base-200/60' : 'hover:bg-base-200/40'}`}
                        >
                            <div className={`w-7 h-7 rounded-lg flex items-center justify-center text-[11px] font-black flex-shrink-0
                                ${chapterCompleted
                                    ? 'bg-green-500/10 text-green-600'
                                    : `bg-gradient-to-br ${courseGradient} text-white shadow-sm`
                                }`}
                            >
                                {chapterCompleted ? <CircleCheck className="w-4 h-4" /> : chIdx + 1}
                            </div>
                            <div className="flex-1 min-w-0">
                                <h4 className="text-[13px] font-bold text-base-content truncate">
                                    {chapter.title}
                                </h4>
                                <p className="text-[10px] text-base-content/40 font-medium">
                                    {chapterLessonsCompleted}/{chapter.lessons.length} bài
                                </p>
                            </div>
                            <ChevronDown
                                className={`w-3.5 h-3.5 text-base-content/30 transition-transform duration-300 flex-shrink-0
                                    ${isExpanded ? 'rotate-180' : ''}`}
                            />
                        </button>

                        <motion.div
                            initial={false}
                            animate={{
                                height: isExpanded ? 'auto' : 0,
                                opacity: isExpanded ? 1 : 0,
                            }}
                            transition={{ duration: 0.3, ease: [0.25, 0.46, 0.45, 0.94] }}
                            className="overflow-hidden"
                        >
                            <div className="pl-4 pr-2 pb-1 space-y-0.5">
                                {chapter.lessons.map((lesson, lIdx) => {
                                    const isActive = chIdx === activeChapter && lIdx === activeLesson;
                                    const isCompleted = completedLessons[`${chIdx}-${lIdx}`];
                                    return (
                                        <LessonItem
                                            key={lIdx}
                                            lesson={lesson}
                                            isActive={isActive}
                                            isCompleted={isCompleted}
                                            courseGradient={courseGradient}
                                            onClick={() => onLessonSelect?.(chIdx, lIdx)}
                                        />
                                    );
                                })}
                            </div>
                        </motion.div>
                    </div>
                );
            })}
        </div>
    );
}

// ─── Lesson Item ─────────────────────────────────────────

function LessonItem({ lesson, isActive, isCompleted, courseGradient, onClick }) {
    const typeIcons = { video: Play, document: FileText, flashcard: Sparkles, quiz: CheckCircle2 };
    const TypeIcon = typeIcons[lesson.type] || Play;
    const typeLabels = { video: 'Video', document: 'Tài liệu', flashcard: 'Flashcard', quiz: 'Bài kiểm tra' };

    return (
        <button
            onClick={onClick}
            className={`w-full flex items-center gap-2.5 px-3 py-2.5 rounded-xl text-left transition-all group
                ${isActive
                    ? 'bg-gradient-to-r from-blue-500/10 to-violet-500/10 border border-blue-500/20'
                    : 'hover:bg-base-200/50 border border-transparent'
                }`}
        >
            <div className={`w-6 h-6 rounded-lg flex items-center justify-center flex-shrink-0 transition-colors
                ${isCompleted ? 'bg-green-500/10'
                    : isActive ? `bg-gradient-to-br ${courseGradient} shadow-sm`
                        : 'bg-base-200'
                }`}
            >
                {isCompleted ? (
                    <CheckCircle2 className="w-3.5 h-3.5 text-green-500" />
                ) : isActive ? (
                    <TypeIcon className="w-3 h-3 text-white" />
                ) : (
                    <TypeIcon className="w-3 h-3 text-base-content/30" />
                )}
            </div>
            <div className="flex-1 min-w-0">
                <p className={`text-[12px] font-semibold truncate ${isActive ? 'text-blue-600' : 'text-base-content/80'}`}>
                    {lesson.title}
                </p>
                <div className="flex items-center gap-1.5 text-[10px] text-base-content/40">
                    {lesson.durationMinutes && (
                        <span className="flex items-center gap-0.5">
                            <Clock className="w-2.5 h-2.5" />
                            {lesson.durationMinutes}p
                        </span>
                    )}
                    <span>·</span>
                    <span>{typeLabels[lesson.type] || 'Bài học'}</span>
                </div>
            </div>
            {isActive && (
                <motion.div
                    layoutId="active-lesson"
                    className="w-1.5 h-6 rounded-full bg-gradient-to-b from-blue-500 to-violet-500 flex-shrink-0"
                />
            )}
        </button>
    );
}

import { useState, useRef } from 'react';
import * as motion from 'motion/react-client';
import {
    Play,
    Pause,
    Maximize,
    Volume2,
    VolumeX,
    SkipForward,
    SkipBack,
    Settings,
    Monitor
} from 'lucide-react';

/**
 * LearnVideoPlayer - Video player with Apple-style controls
 * Renders a simulated premium video player with overlay controls.
 *
 * @param {object}  lesson     - Current lesson object
 * @param {string}  gradient   - Course gradient class
 * @param {boolean} isPlaying  - Whether the video is playing
 * @param {Function} onTogglePlay - Callback to toggle play/pause
 */
export default function LearnVideoPlayer({
    lesson,
    gradient = 'from-blue-500 to-violet-500',
    isPlaying = false,
    onTogglePlay,
}) {
    const [showControls, setShowControls] = useState(true);
    const [isMuted, setIsMuted] = useState(false);
    const [currentTime, setCurrentTime] = useState(0);
    const duration = (lesson?.durationMinutes || 25) * 60; // seconds
    const progress = duration > 0 ? (currentTime / duration) * 100 : 0;

    const formatTime = (seconds) => {
        const m = Math.floor(seconds / 60);
        const s = Math.floor(seconds % 60);
        return `${m}:${s.toString().padStart(2, '0')}`;
    };

    return (
        <motion.div
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.5 }}
            className="relative aspect-video bg-gray-950 rounded-2xl overflow-hidden group shadow-2xl"
            onMouseEnter={() => setShowControls(true)}
            onMouseLeave={() => !isPlaying && setShowControls(true)}
        >
            {/* Video placeholder / thumbnail */}
            <div className="absolute inset-0 flex items-center justify-center">
                {/* Gradient background simulating video */}
                <div className={`absolute inset-0 bg-gradient-to-br ${gradient} opacity-5`} />

                {/* Grid pattern overlay */}
                <div
                    className="absolute inset-0 opacity-[0.03]"
                    style={{
                        backgroundImage: 'radial-gradient(circle, white 1px, transparent 1px)',
                        backgroundSize: '30px 30px',
                    }}
                />

                {/* Centered play button */}
                {!isPlaying && (
                    <motion.button
                        initial={{ scale: 0 }}
                        animate={{ scale: 1 }}
                        transition={{ type: 'spring', stiffness: 300, damping: 20 }}
                        onClick={onTogglePlay}
                        className={`z-10 w-20 h-20 rounded-full bg-gradient-to-br ${gradient} flex items-center justify-center shadow-2xl hover:scale-105 transition-transform`}
                    >
                        <Play className="w-8 h-8 text-white ml-1" fill="white" />
                    </motion.button>
                )}

                {/* Video content area — shows lesson title when not playing */}
                {!isPlaying && (
                    <div className="absolute bottom-20 left-0 right-0 text-center">
                        <p className="text-white/40 text-sm font-medium">
                            {lesson?.title}
                        </p>
                    </div>
                )}
            </div>

            {/* Bottom controls overlay */}
            <motion.div
                initial={false}
                animate={{ opacity: showControls || !isPlaying ? 1 : 0 }}
                transition={{ duration: 0.2 }}
                className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent pt-16 pb-4 px-5"
            >
                {/* Progress bar */}
                <div className="mb-3 group/progress cursor-pointer">
                    <div className="relative h-1 group-hover/progress:h-1.5 transition-all rounded-full bg-white/20 overflow-hidden">
                        {/* Buffered */}
                        <div
                            className="absolute inset-y-0 left-0 bg-white/20 rounded-full"
                            style={{ width: `${Math.min(progress + 15, 100)}%` }}
                        />
                        {/* Played */}
                        <motion.div
                            className={`absolute inset-y-0 left-0 rounded-full bg-gradient-to-r ${gradient}`}
                            style={{ width: `${progress}%` }}
                        />
                        {/* Scrubber dot */}
                        <div
                            className="absolute top-1/2 -translate-y-1/2 w-3 h-3 rounded-full bg-white shadow-lg opacity-0 group-hover/progress:opacity-100 transition-opacity"
                            style={{ left: `${progress}%`, transform: `translateX(-50%) translateY(-50%)` }}
                        />
                    </div>
                </div>

                {/* Control buttons */}
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        {/* Play/Pause */}
                        <button
                            onClick={onTogglePlay}
                            className="text-white/90 hover:text-white transition-colors"
                        >
                            {isPlaying
                                ? <Pause className="w-5 h-5" />
                                : <Play className="w-5 h-5" fill="white" />
                            }
                        </button>

                        {/* Skip */}
                        <button className="text-white/60 hover:text-white transition-colors">
                            <SkipBack className="w-4 h-4" />
                        </button>
                        <button className="text-white/60 hover:text-white transition-colors">
                            <SkipForward className="w-4 h-4" />
                        </button>

                        {/* Volume */}
                        <button
                            onClick={() => setIsMuted(!isMuted)}
                            className="text-white/60 hover:text-white transition-colors"
                        >
                            {isMuted
                                ? <VolumeX className="w-4 h-4" />
                                : <Volume2 className="w-4 h-4" />
                            }
                        </button>

                        {/* Time */}
                        <span className="text-white/60 text-xs font-medium ml-1">
                            {formatTime(currentTime)} / {formatTime(duration)}
                        </span>
                    </div>

                    <div className="flex items-center gap-3">
                        {/* Speed */}
                        <button className="text-white/60 hover:text-white transition-colors text-xs font-bold px-1.5 py-0.5 rounded border border-white/20 hover:border-white/40">
                            1x
                        </button>
                        {/* Settings */}
                        <button className="text-white/60 hover:text-white transition-colors">
                            <Settings className="w-4 h-4" />
                        </button>
                        {/* Fullscreen */}
                        <button className="text-white/60 hover:text-white transition-colors">
                            <Maximize className="w-4 h-4" />
                        </button>
                    </div>
                </div>
            </motion.div>
        </motion.div>
    );
}

import { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import * as motion from 'motion/react-client';
import {
    BarChart3,
    BookOpen,
    CreditCard,
    FileText,
    Brain,
    MessageSquare,
    Calendar,
    Trophy,
    ShoppingBag,
    User,
    Settings,
    LogOut,
    Zap,
    GraduationCap,
    PanelLeftClose,
    PanelLeftOpen,
} from 'lucide-react';

const SIDEBAR_KEY = 'skr-dashboard-sidebar-collapsed';

export default function DashboardSidebar() {
    const location = useLocation();
    const navigate = useNavigate();
    const [collapsed, setCollapsed] = useState(() => {
        try { return localStorage.getItem(SIDEBAR_KEY) === 'true'; } catch { return false; }
    });

    const handleLogout = () => {
        localStorage.removeItem('accessToken');
        localStorage.removeItem('user');
        navigate('/login');
    };

    useEffect(() => {
        try { localStorage.setItem(SIDEBAR_KEY, collapsed); } catch { }
    }, [collapsed]);

    const menuItems = [
        { icon: BarChart3, label: 'Tổng quan', path: '/dashboard' },
        { icon: BookOpen, label: 'Môn học', path: '/courses' },
        { icon: CreditCard, label: 'Flashcards', path: '/flashcards' },
        { icon: FileText, label: 'Thi thử', path: '/tests' },
        { icon: ShoppingBag, label: 'Đơn hàng', path: '/orders' },
        { icon: Brain, label: 'AI Assistant', path: '/ai-assistant', badge: 'Premium' },
        { icon: MessageSquare, label: 'Cộng đồng', path: '/community' },
        { icon: Calendar, label: 'Lịch học', path: '/schedule' },
        { icon: Trophy, label: 'Thành tích', path: '/achievements' }
    ];

    const isActive = (path) => {
        if (path === '/dashboard') return location.pathname === '/dashboard';
        return location.pathname === path || location.pathname.startsWith(path + '/');
    };

    return (
        <motion.aside
            initial={{ x: -300 }}
            animate={{ x: 0, width: collapsed ? 72 : 256 }}
            transition={{ duration: 0.3, ease: [0.25, 0.46, 0.45, 0.94] }}
            className="bg-base-100 border-r border-base-300 flex flex-col flex-shrink-0 overflow-hidden h-full"
        >
            {/* Logo */}
            <div className={`border-b border-base-300 flex-shrink-0 ${collapsed ? 'p-3 flex justify-center' : 'p-5'}`}>
                <div className="flex items-center gap-3">
                    <Link to="/dashboard" className="flex-shrink-0">
                        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-violet-600 rounded-xl flex items-center justify-center shadow-lg">
                            <GraduationCap className="w-6 h-6 text-white" strokeWidth={2.5} />
                        </div>
                    </Link>
                    {!collapsed && (
                        <motion.div
                            initial={{ opacity: 0, x: -8 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ duration: 0.2, delay: 0.1 }}
                            className="min-w-0"
                        >
                            <Link to="/dashboard">
                                <h1 className="text-xl font-black text-base-content">SKR</h1>
                                <p className="text-[10px] font-bold text-base-content/60 uppercase tracking-wider whitespace-nowrap">
                                    Smart Knowledge Revise
                                </p>
                            </Link>
                        </motion.div>
                    )}
                </div>
            </div>

            {/* Toggle collapse button */}
            <div className={`px-3 pt-3 flex ${collapsed ? 'justify-center' : 'justify-end'}`}>
                <button
                    onClick={() => setCollapsed(prev => !prev)}
                    className="w-8 h-8 rounded-lg flex items-center justify-center text-base-content/40 hover:text-base-content hover:bg-base-200 transition-all"
                    title={collapsed ? 'Mở rộng sidebar' : 'Thu gọn sidebar'}
                >
                    {collapsed
                        ? <PanelLeftOpen className="w-4 h-4" />
                        : <PanelLeftClose className="w-4 h-4" />
                    }
                </button>
            </div>

            {/* Menu */}
            <nav className="flex-1 px-2 py-2 space-y-0.5 overflow-y-auto overflow-x-hidden">
                {menuItems.map((item, i) => (
                    <motion.div
                        key={item.path}
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: 0.3 + i * 0.04 }}
                    >
                        <Link
                            to={item.path}
                            className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl font-bold text-sm transition-all relative group
                                ${collapsed ? 'justify-center' : ''}
                                ${isActive(item.path)
                                    ? 'bg-gradient-to-r from-blue-600 to-violet-600 text-white shadow-lg'
                                    : 'text-base-content/60 hover:bg-base-200 hover:text-base-content'
                                }`}
                        >
                            <item.icon className="w-5 h-5 flex-shrink-0" />
                            {!collapsed && (
                                <span className="truncate whitespace-nowrap">{item.label}</span>
                            )}
                            {!collapsed && item.badge && (
                                <span className="ml-auto badge badge-xs badge-warning font-bold flex-shrink-0">
                                    {item.badge}
                                </span>
                            )}
                            {/* Tooltip when collapsed */}
                            {collapsed && (
                                <div className="absolute left-full ml-3 px-3 py-1.5 rounded-xl bg-base-content text-base-100 text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-[60] shadow-xl">
                                    {item.label}
                                    {item.badge && (
                                        <span className="ml-1.5 badge badge-xs badge-warning font-bold">
                                            {item.badge}
                                        </span>
                                    )}
                                    <div className="absolute top-1/2 -left-1 -translate-y-1/2 w-2 h-2 rotate-45 bg-base-content" />
                                </div>
                            )}
                        </Link>
                    </motion.div>
                ))}
            </nav>

            {/* Premium Upgrade CTA — expanded */}
            {!collapsed && (
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.9 }}
                    className="mx-3 mb-2 p-4 rounded-2xl bg-gradient-to-br from-orange-500/10 to-pink-500/10 border border-orange-500/20"
                >
                    <div className="flex items-center gap-2 mb-2">
                        <Zap className="w-5 h-5 text-orange-500" />
                        <h3 className="font-black text-sm text-base-content">Nâng cấp Premium</h3>
                    </div>
                    <p className="text-xs text-base-content/70 mb-3">
                        Mở khóa AI Assistant, Spaced Repetition và nhiều hơn!
                    </p>
                    <Link to="/pricing">
                        <button className="btn btn-sm w-full bg-gradient-to-r from-orange-500 to-pink-500 hover:from-orange-600 hover:to-pink-600 text-white border-none rounded-xl font-bold">
                            Nâng cấp ngay
                        </button>
                    </Link>
                </motion.div>
            )}
            {/* Premium icon — collapsed */}
            {collapsed && (
                <div className="flex justify-center mb-2">
                    <Link
                        to="/pricing"
                        className="w-10 h-10 rounded-xl bg-gradient-to-br from-orange-500/10 to-pink-500/10 border border-orange-500/20 flex items-center justify-center group relative"
                    >
                        <Zap className="w-4 h-4 text-orange-500" />
                        <div className="absolute left-full ml-3 px-3 py-1.5 rounded-xl bg-base-content text-base-100 text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-[60] shadow-xl">
                            Nâng cấp Premium
                            <div className="absolute top-1/2 -left-1 -translate-y-1/2 w-2 h-2 rotate-45 bg-base-content" />
                        </div>
                    </Link>
                </div>
            )}

            {/* Bottom Menu */}
            <div className="px-2 py-2 space-y-0.5 border-t border-base-300">
                {[
                    { icon: User, label: 'Hồ sơ', path: '/profile' },
                    { icon: Settings, label: 'Cài đặt', path: '/settings' },
                ].map((item) => (
                    <Link
                        key={item.path}
                        to={item.path}
                        className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl font-bold text-sm transition-all relative group
                            ${collapsed ? 'justify-center' : ''}
                            ${isActive(item.path)
                                ? 'bg-gradient-to-r from-blue-600 to-violet-600 text-white shadow-lg'
                                : 'text-base-content/60 hover:bg-base-200 hover:text-base-content'
                            }`}
                    >
                        <item.icon className="w-5 h-5 flex-shrink-0" />
                        {!collapsed && <span className="truncate">{item.label}</span>}
                        {collapsed && (
                            <div className="absolute left-full ml-3 px-3 py-1.5 rounded-xl bg-base-content text-base-100 text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-[60] shadow-xl">
                                {item.label}
                                <div className="absolute top-1/2 -left-1 -translate-y-1/2 w-2 h-2 rotate-45 bg-base-content" />
                            </div>
                        )}
                    </Link>
                ))}
                <button
                    onClick={handleLogout}
                    className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl font-bold text-sm text-red-500 hover:bg-red-500/10 transition-all relative group
                        ${collapsed ? 'justify-center' : ''}`}
                >
                    <LogOut className="w-5 h-5 flex-shrink-0" />
                    {!collapsed && <span>Đăng xuất</span>}
                    {collapsed && (
                        <div className="absolute left-full ml-3 px-3 py-1.5 rounded-xl bg-base-content text-base-100 text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-[60] shadow-xl">
                            Đăng xuất
                            <div className="absolute top-1/2 -left-1 -translate-y-1/2 w-2 h-2 rotate-45 bg-base-content" />
                        </div>
                    )}
                </button>
            </div>
        </motion.aside>
    );
}

import { Link } from 'react-router-dom';
import * as motion from 'motion/react-client';
import {
    Package,
    ChevronRight,
    Calendar,
    CreditCard,
    Tag
} from 'lucide-react';
import OrderStatusBadge from './OrderStatusBadge';
import { formatCurrency, formatDate, getPaymentMethodLabel } from './utils';

/**
 * OrderCard — Card hiển thị tóm tắt 1 đơn hàng trong danh sách
 * Maps to: orders + order_items tables
 * 
 * @param {object} order - Order data object
 * @param {number} index - Index for staggered animation
 * @param {object} variants - Motion animation variants
 */
export default function OrderCard({ order, index = 0, variants }) {
    const itemCount = order.items?.length || 0;
    const firstItem = order.items?.[0];
    const remainingCount = itemCount - 1;

    return (
        <motion.div
            variants={variants}
            initial="hidden"
            animate="visible"
            transition={{ delay: index * 0.05 }}
        >
            <Link
                to={`/orders/${order.id}`}
                className="block group"
            >
                <div className="bg-base-100 rounded-2xl border border-base-300 p-5 shadow-sm
                    hover:shadow-lg hover:border-blue-500/20 hover:-translate-y-0.5
                    transition-all duration-300 cursor-pointer"
                >
                    {/* Row 1: Order ID + Status + Date */}
                    <div className="flex items-start justify-between gap-4 mb-4">
                        <div className="flex items-center gap-3 min-w-0">
                            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500/10 to-violet-500/10 
                                flex items-center justify-center flex-shrink-0
                                group-hover:from-blue-500/20 group-hover:to-violet-500/20 transition-colors"
                            >
                                <Package className="w-5 h-5 text-blue-600" />
                            </div>
                            <div className="min-w-0">
                                <h3 className="text-sm font-black text-base-content truncate">
                                    {order.id}
                                </h3>
                                <p className="text-xs text-base-content/50 font-medium flex items-center gap-1.5 mt-0.5">
                                    <Calendar className="w-3 h-3" />
                                    {formatDate(order.createdAt)}
                                </p>
                            </div>
                        </div>
                        <OrderStatusBadge status={order.status} size="sm" />
                    </div>

                    {/* Row 2: Items preview */}
                    <div className="mb-4 pl-[52px]">
                        {firstItem && (
                            <div className="flex items-center gap-2">
                                <span className="text-sm font-semibold text-base-content/80 truncate">
                                    {firstItem.name}
                                </span>
                                {firstItem.itemType && (
                                    <span className="badge badge-xs badge-ghost font-bold flex-shrink-0">
                                        {firstItem.itemType === 'subscription' ? 'Gói' : 'Môn học'}
                                    </span>
                                )}
                            </div>
                        )}
                        {remainingCount > 0 && (
                            <p className="text-xs text-base-content/40 font-medium mt-1">
                                +{remainingCount} sản phẩm khác
                            </p>
                        )}
                    </div>

                    {/* Row 3: Payment info + Total + Arrow */}
                    <div className="flex items-center justify-between pt-3 border-t border-base-200">
                        <div className="flex items-center gap-4">
                            {/* Payment method */}
                            <span className="text-xs text-base-content/50 font-medium flex items-center gap-1">
                                <CreditCard className="w-3 h-3" />
                                {getPaymentMethodLabel(order.paymentMethod)}
                            </span>

                            {/* Coupon */}
                            {order.couponCode && (
                                <span className="text-xs text-emerald-600 font-bold flex items-center gap-1">
                                    <Tag className="w-3 h-3" />
                                    {order.couponCode}
                                </span>
                            )}
                        </div>

                        <div className="flex items-center gap-3">
                            {/* Discount */}
                            {order.discountAmount > 0 && (
                                <span className="text-xs text-base-content/40 line-through font-medium">
                                    {formatCurrency(order.totalAmount)}
                                </span>
                            )}

                            {/* Final amount */}
                            <span className="text-base font-black text-base-content">
                                {formatCurrency(order.finalAmount)}
                            </span>

                            <ChevronRight className="w-4 h-4 text-base-content/30 group-hover:text-blue-500 group-hover:translate-x-1 transition-all" />
                        </div>
                    </div>
                </div>
            </Link>
        </motion.div>
    );
}

import { useState } from 'react';
import * as motion from 'motion/react-client';
import {
    Search,
    Filter,
    SlidersHorizontal,
    CalendarDays,
    ChevronDown,
    X
} from 'lucide-react';

/**
 * OrderFilters — Bộ lọc và tìm kiếm cho danh sách đơn hàng
 * 
 * @param {object} filters - Current filter state
 * @param {function} onFilterChange - Callback when filters change
 */

const STATUS_OPTIONS = [
    { value: 'all', label: 'Tất cả' },
    { value: 'pending', label: 'Chờ xử lý' },
    { value: 'processing', label: 'Đang xử lý' },
    { value: 'completed', label: 'Hoàn thành' },
    { value: 'cancelled', label: 'Đã hủy' },
    { value: 'refunded', label: 'Đã hoàn tiền' }
];

const SORT_OPTIONS = [
    { value: 'newest', label: 'Mới nhất' },
    { value: 'oldest', label: 'Cũ nhất' },
    { value: 'highest', label: 'Giá cao nhất' },
    { value: 'lowest', label: 'Giá thấp nhất' }
];

const TIME_OPTIONS = [
    { value: 'all', label: 'Tất cả thời gian' },
    { value: '7d', label: '7 ngày qua' },
    { value: '30d', label: '30 ngày qua' },
    { value: '90d', label: '3 tháng qua' },
    { value: '1y', label: '1 năm qua' }
];

export default function OrderFilters({ filters, onFilterChange }) {
    const [isExpanded, setIsExpanded] = useState(false);

    const hasActiveFilters = filters.status !== 'all'
        || filters.timeRange !== 'all'
        || filters.search;

    const handleReset = () => {
        onFilterChange({
            status: 'all',
            sortBy: 'newest',
            timeRange: 'all',
            search: ''
        });
    };

    return (
        <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.15 }}
            className="bg-base-100 rounded-2xl border border-base-300 shadow-sm overflow-hidden"
        >
            {/* Main filter bar */}
            <div className="p-4 flex items-center gap-3 flex-wrap">
                {/* Search */}
                <div className="relative flex-1 min-w-[200px]">
                    <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-base-content/30" />
                    <input
                        type="text"
                        placeholder="Tìm theo mã đơn, tên sản phẩm..."
                        value={filters.search}
                        onChange={(e) => onFilterChange({ ...filters, search: e.target.value })}
                        className="input input-bordered input-sm w-full pl-9 rounded-xl bg-base-200/50
                            border-base-300 focus:border-blue-500 focus:bg-base-100 font-medium text-sm"
                    />
                    {filters.search && (
                        <button
                            onClick={() => onFilterChange({ ...filters, search: '' })}
                            className="btn btn-ghost btn-xs btn-circle absolute right-1.5 top-1/2 -translate-y-1/2"
                        >
                            <X className="w-3 h-3" />
                        </button>
                    )}
                </div>

                {/* Status quick filter */}
                <div className="flex gap-1.5">
                    {STATUS_OPTIONS.slice(0, 4).map((option) => (
                        <button
                            key={option.value}
                            onClick={() => onFilterChange({ ...filters, status: option.value })}
                            className={`btn btn-xs rounded-lg font-bold transition-all ${filters.status === option.value
                                ? 'btn-primary shadow-sm'
                                : 'btn-ghost text-base-content/50 hover:text-base-content'
                                }`}
                        >
                            {option.label}
                        </button>
                    ))}
                </div>

                {/* Expand filters */}
                <button
                    onClick={() => setIsExpanded(!isExpanded)}
                    className={`btn btn-sm btn-ghost rounded-xl font-bold gap-1.5 ${isExpanded ? 'bg-blue-500/10 text-blue-600' : 'text-base-content/50'
                        }`}
                >
                    <SlidersHorizontal className="w-3.5 h-3.5" />
                    Bộ lọc
                    <ChevronDown className={`w-3 h-3 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                </button>

                {/* Reset */}
                {hasActiveFilters && (
                    <motion.button
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        onClick={handleReset}
                        className="btn btn-xs btn-ghost text-red-500 rounded-lg font-bold"
                    >
                        <X className="w-3 h-3" />
                        Xóa lọc
                    </motion.button>
                )}
            </div>

            {/* Expanded filters */}
            {isExpanded && (
                <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{ duration: 0.2 }}
                    className="px-4 pb-4 pt-1 border-t border-base-200"
                >
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 pt-3">
                        {/* Status dropdown */}
                        <div>
                            <label className="text-[10px] font-bold text-base-content/40 uppercase tracking-wider mb-1.5 block">
                                Trạng thái
                            </label>
                            <select
                                value={filters.status}
                                onChange={(e) => onFilterChange({ ...filters, status: e.target.value })}
                                className="select select-bordered select-sm w-full rounded-xl font-medium"
                            >
                                {STATUS_OPTIONS.map(option => (
                                    <option key={option.value} value={option.value}>{option.label}</option>
                                ))}
                            </select>
                        </div>

                        {/* Sort */}
                        <div>
                            <label className="text-[10px] font-bold text-base-content/40 uppercase tracking-wider mb-1.5 block">
                                Sắp xếp
                            </label>
                            <select
                                value={filters.sortBy}
                                onChange={(e) => onFilterChange({ ...filters, sortBy: e.target.value })}
                                className="select select-bordered select-sm w-full rounded-xl font-medium"
                            >
                                {SORT_OPTIONS.map(option => (
                                    <option key={option.value} value={option.value}>{option.label}</option>
                                ))}
                            </select>
                        </div>

                        {/* Time range */}
                        <div>
                            <label className="text-[10px] font-bold text-base-content/40 uppercase tracking-wider mb-1.5 block flex items-center gap-1">
                                <CalendarDays className="w-3 h-3" />
                                Thời gian
                            </label>
                            <select
                                value={filters.timeRange}
                                onChange={(e) => onFilterChange({ ...filters, timeRange: e.target.value })}
                                className="select select-bordered select-sm w-full rounded-xl font-medium"
                            >
                                {TIME_OPTIONS.map(option => (
                                    <option key={option.value} value={option.value}>{option.label}</option>
                                ))}
                            </select>
                        </div>
                    </div>
                </motion.div>
            )}
        </motion.div>
    );
}

import * as motion from 'motion/react-client';
import { Package, BookOpen, Crown, Zap } from 'lucide-react';
import { formatCurrency } from './utils';

/**
 * OrderItemsList — Danh sách sản phẩm trong đơn hàng
 * Maps to: order_items table (item_type, item_id, quantity, unit_price, total_price)
 * 
 * @param {Array} items - Array of order item objects
 */

const ITEM_TYPE_CONFIG = {
    subscription: {
        icon: Crown,
        label: 'Gói đăng ký',
        gradient: 'from-amber-500/10 to-orange-500/10',
        iconColor: 'text-amber-600',
        badgeClass: 'bg-amber-500/10 text-amber-700 border-amber-500/20'
    },
    subject: {
        icon: BookOpen,
        label: 'Môn học',
        gradient: 'from-blue-500/10 to-violet-500/10',
        iconColor: 'text-blue-600',
        badgeClass: 'bg-blue-500/10 text-blue-700 border-blue-500/20'
    }
};

export default function OrderItemsList({ items = [] }) {
    if (items.length === 0) return null;

    return (
        <div className="bg-base-100 rounded-2xl border border-base-300 p-6 shadow-sm">
            <h3 className="text-base font-black text-base-content mb-5 flex items-center gap-2">
                <Package className="w-4 h-4 text-violet-500" />
                Chi Tiết Sản Phẩm
                <span className="badge badge-sm badge-ghost font-bold ml-1">{items.length}</span>
            </h3>

            <div className="space-y-3">
                {items.map((item, index) => {
                    const typeConfig = ITEM_TYPE_CONFIG[item.itemType] || ITEM_TYPE_CONFIG.subject;
                    const IconComponent = typeConfig.icon;

                    return (
                        <motion.div
                            key={item.id || index}
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: 0.1 + index * 0.08 }}
                            className="flex items-center gap-4 p-4 rounded-xl bg-base-200/50
                                hover:bg-base-200 transition-colors border border-transparent hover:border-base-300"
                        >
                            {/* Icon */}
                            <div className={`
                                w-12 h-12 rounded-xl bg-gradient-to-br ${typeConfig.gradient}
                                flex items-center justify-center flex-shrink-0
                            `}>
                                <IconComponent className={`w-5 h-5 ${typeConfig.iconColor}`} />
                            </div>

                            {/* Item info */}
                            <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2 mb-1">
                                    <h4 className="text-sm font-bold text-base-content truncate">
                                        {item.name}
                                    </h4>
                                    <span className={`
                                        inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold
                                        border flex-shrink-0 ${typeConfig.badgeClass}
                                    `}>
                                        {typeConfig.label}
                                    </span>
                                </div>
                                {item.description && (
                                    <p className="text-xs text-base-content/50 truncate">
                                        {item.description}
                                    </p>
                                )}
                                {item.duration && (
                                    <p className="text-xs text-base-content/40 mt-0.5">
                                        Thời hạn: {item.duration}
                                    </p>
                                )}
                            </div>

                            {/* Quantity + Price */}
                            <div className="text-right flex-shrink-0">
                                {item.quantity > 1 && (
                                    <p className="text-xs text-base-content/40 font-medium mb-0.5">
                                        x{item.quantity}
                                    </p>
                                )}
                                <p className="text-sm font-black text-base-content">
                                    {formatCurrency(item.totalPrice)}
                                </p>
                                {item.unitPrice !== item.totalPrice && item.quantity > 1 && (
                                    <p className="text-[11px] text-base-content/40">
                                        {formatCurrency(item.unitPrice)}/sp
                                    </p>
                                )}
                            </div>
                        </motion.div>
                    );
                })}
            </div>
        </div>
    );
}

import * as motion from 'motion/react-client';
import {
    Clock,
    CreditCard,
    CheckCircle2,
    Package,
    XCircle,
    RotateCcw
} from 'lucide-react';

/**
 * OrderTimeline — Hiển thị lịch sử trạng thái đơn hàng
 * Maps to: orders.status + orders.created_at + transactions.created_at
 * 
 * @param {object} order - Order data with timeline events
 */

const TIMELINE_ICONS = {
    created: Package,
    pending: Clock,
    processing: CreditCard,
    completed: CheckCircle2,
    cancelled: XCircle,
    refunded: RotateCcw
};

const TIMELINE_COLORS = {
    created: 'from-blue-500 to-blue-600',
    pending: 'from-amber-500 to-amber-600',
    processing: 'from-blue-500 to-cyan-500',
    completed: 'from-emerald-500 to-green-500',
    cancelled: 'from-red-500 to-red-600',
    refunded: 'from-purple-500 to-purple-600'
};

export default function OrderTimeline({ events = [] }) {
    return (
        <div className="bg-base-100 rounded-2xl border border-base-300 p-6 shadow-sm">
            <h3 className="text-base font-black text-base-content mb-6 flex items-center gap-2">
                <Clock className="w-4 h-4 text-blue-500" />
                Lịch Sử Đơn Hàng
            </h3>

            <div className="relative">
                {events.map((event, index) => {
                    const IconComponent = TIMELINE_ICONS[event.type] || Package;
                    const gradientColor = TIMELINE_COLORS[event.type] || TIMELINE_COLORS.created;
                    const isLast = index === events.length - 1;
                    const isActive = event.isActive;

                    return (
                        <motion.div
                            key={index}
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: 0.1 + index * 0.1, duration: 0.4 }}
                            className="flex gap-4 relative"
                        >
                            {/* Timeline line + dot */}
                            <div className="flex flex-col items-center">
                                <div className={`
                                    w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0 shadow-sm
                                    ${isActive
                                        ? `bg-gradient-to-br ${gradientColor} text-white shadow-lg`
                                        : 'bg-base-200 text-base-content/40'
                                    }
                                `}>
                                    <IconComponent className="w-4 h-4" />
                                </div>

                                {/* Connector line */}
                                {!isLast && (
                                    <div className={`w-0.5 flex-1 my-1 min-h-[24px] rounded-full
                                        ${isActive ? 'bg-gradient-to-b from-base-300 to-base-200' : 'bg-base-200'}
                                    `} />
                                )}
                            </div>

                            {/* Content */}
                            <div className={`flex-1 pb-6 ${isLast ? 'pb-0' : ''}`}>
                                <div className="flex items-center justify-between gap-2">
                                    <h4 className={`text-sm font-bold ${isActive ? 'text-base-content' : 'text-base-content/50'}`}>
                                        {event.title}
                                    </h4>
                                    <span className="text-[11px] text-base-content/40 font-medium whitespace-nowrap">
                                        {event.time}
                                    </span>
                                </div>
                                {event.description && (
                                    <p className="text-xs text-base-content/50 mt-1 leading-relaxed">
                                        {event.description}
                                    </p>
                                )}
                            </div>
                        </motion.div>
                    );
                })}
            </div>
        </div>
    );
}

import * as motion from 'motion/react-client';
import {
    CreditCard,
    Hash,
    Calendar,
    ShieldCheck,
    Copy,
    CheckCircle2,
    ExternalLink
} from 'lucide-react';
import { useState } from 'react';
import OrderStatusBadge from './OrderStatusBadge';
import { formatCurrency, formatDate, getPaymentMethodLabel, getPaymentMethodIcon } from './utils';

/**
 * TransactionInfo — Hiển thị thông tin giao dịch thanh toán
 * Maps to: transactions table (payment_method, amount, status, transaction_ref, gateway_response)
 * 
 * @param {object} transaction - Transaction data object
 * @param {object} order - Order data for price breakdown
 */
export default function TransactionInfo({ transaction, order }) {
    const [copied, setCopied] = useState(false);

    const handleCopy = (text) => {
        navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    if (!transaction) return null;

    const PaymentIcon = getPaymentMethodIcon(transaction.paymentMethod);

    return (
        <div className="bg-base-100 rounded-2xl border border-base-300 p-6 shadow-sm">
            <h3 className="text-base font-black text-base-content mb-5 flex items-center gap-2">
                <CreditCard className="w-4 h-4 text-emerald-500" />
                Thông Tin Thanh Toán
            </h3>

            {/* Payment method highlight */}
            <div className="bg-gradient-to-br from-blue-500/5 to-violet-500/5 rounded-xl p-4 mb-5 border border-blue-500/10">
                <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-xl bg-base-100 flex items-center justify-center shadow-sm border border-base-200">
                        <PaymentIcon className="w-6 h-6 text-blue-600" />
                    </div>
                    <div className="flex-1">
                        <p className="text-sm font-bold text-base-content">
                            {getPaymentMethodLabel(transaction.paymentMethod)}
                        </p>
                        <p className="text-xs text-base-content/40 font-medium">
                            Phương thức thanh toán
                        </p>
                    </div>
                    <OrderStatusBadge status={transaction.status} size="sm" />
                </div>
            </div>

            {/* Info rows */}
            <div className="space-y-3">
                {/* Transaction ref */}
                <InfoRow
                    icon={Hash}
                    label="Mã giao dịch"
                    value={transaction.transactionRef}
                    action={
                        <button
                            onClick={() => handleCopy(transaction.transactionRef)}
                            className="btn btn-ghost btn-xs rounded-lg"
                            title="Sao chép"
                        >
                            {copied
                                ? <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" />
                                : <Copy className="w-3.5 h-3.5" />
                            }
                        </button>
                    }
                />

                {/* Amount */}
                <InfoRow
                    icon={CreditCard}
                    label="Số tiền thanh toán"
                    value={formatCurrency(transaction.amount)}
                    valueClass="font-black text-emerald-600"
                />

                {/* Date */}
                <InfoRow
                    icon={Calendar}
                    label="Thời gian thanh toán"
                    value={formatDate(transaction.createdAt, true)}
                />

                {/* Secure badge */}
                <InfoRow
                    icon={ShieldCheck}
                    label="Bảo mật"
                    value="Giao dịch được mã hóa SSL 256-bit"
                    valueClass="text-emerald-600"
                />
            </div>

            {/* Price breakdown */}
            {order && (
                <div className="mt-5 pt-5 border-t border-base-200 space-y-2.5">
                    <PriceRow label="Tổng tiền hàng" value={formatCurrency(order.totalAmount)} />

                    {order.discountAmount > 0 && (
                        <PriceRow
                            label={`Giảm giá ${order.couponCode ? `(${order.couponCode})` : ''}`}
                            value={`-${formatCurrency(order.discountAmount)}`}
                            valueClass="text-emerald-600"
                        />
                    )}

                    <div className="pt-2.5 border-t border-base-200">
                        <PriceRow
                            label="Thành tiền"
                            value={formatCurrency(order.finalAmount)}
                            bold
                        />
                    </div>
                </div>
            )}
        </div>
    );
}

/**
 * InfoRow — Hàng thông tin key-value
 */
function InfoRow({ icon: Icon, label, value, valueClass = '', action }) {
    return (
        <div className="flex items-center justify-between py-2 px-3 rounded-lg hover:bg-base-200/50 transition-colors">
            <div className="flex items-center gap-2.5 min-w-0">
                <Icon className="w-4 h-4 text-base-content/30 flex-shrink-0" />
                <span className="text-xs text-base-content/50 font-medium">{label}</span>
            </div>
            <div className="flex items-center gap-1.5">
                <span className={`text-sm font-semibold text-base-content ${valueClass}`}>
                    {value}
                </span>
                {action}
            </div>
        </div>
    );
}

/**
 * PriceRow — Hàng giá tiền trong breakdown
 */
function PriceRow({ label, value, valueClass = '', bold = false }) {
    return (
        <div className="flex items-center justify-between">
            <span className={`text-sm ${bold ? 'font-bold text-base-content' : 'text-base-content/60 font-medium'}`}>
                {label}
            </span>
            <span className={`text-sm ${bold ? 'text-lg font-black text-base-content' : `font-bold text-base-content ${valueClass}`}`}>
                {value}
            </span>
        </div>
    );
}

import { useState } from 'react';
import * as motion from 'motion/react-client';
import Icon from '../icons/Icon';
import { DIFFICULTY_CONFIG, SUBJECT_CONFIG, QUESTION_TYPE_CONFIG } from './utils';

/**
 * CreateTestModal - Modal tạo bài thi mới
 * Maps to: lrn_practice_tests table
 */
export default function CreateTestModal({ isOpen, onClose, onCreate }) {
    const [formData, setFormData] = useState({
        title: '',
        description: '',
        subjectKey: '',
        difficulty: 'medium',
        totalQuestions: 20,
        timeLimitMinutes: 30,
        questionTypes: ['multiple_choice'],
        randomizeQuestions: true,
        randomizeOptions: true,
        showCorrectAnswers: true,
    });

    const handleChange = (field, value) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    };

    const toggleQuestionType = (type) => {
        setFormData(prev => ({
            ...prev,
            questionTypes: prev.questionTypes.includes(type)
                ? prev.questionTypes.filter(t => t !== type)
                : [...prev.questionTypes, type]
        }));
    };

    const handleSubmit = () => {
        if (!formData.title || !formData.subjectKey) return;
        onCreate({
            ...formData,
            id: `pt-${Date.now()}`,
            attemptsCount: 0,
            bestScore: null,
            averageScore: null,
            lastAttemptAt: null,
            createdAt: new Date().toISOString(),
            status: 'active',
        });
        onClose();
    };

    if (!isOpen) return null;

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4"
        >
            {/* Backdrop */}
            <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />

            {/* Modal */}
            <motion.div
                initial={{ opacity: 0, scale: 0.9, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                transition={{ duration: 0.3, ease: [0.25, 0.46, 0.45, 0.94] }}
                className="bg-base-100 rounded-3xl shadow-2xl w-full max-w-lg relative z-10 max-h-[90vh] overflow-y-auto"
            >
                {/* Header */}
                <div className="p-6 pb-4 border-b border-base-300">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-violet-600 rounded-xl flex items-center justify-center">
                                <Icon name="FilePlus2" size="md" className="text-white" />
                            </div>
                            <div>
                                <h3 className="text-lg font-black text-base-content">Tạo Bài Thi Mới</h3>
                                <p className="text-xs text-base-content/60">Cấu hình bài thi thử của bạn</p>
                            </div>
                        </div>
                        <button onClick={onClose} className="btn btn-circle btn-ghost btn-sm">
                            <Icon name="X" size="md" />
                        </button>
                    </div>
                </div>

                {/* Form */}
                <div className="p-6 space-y-5">
                    {/* Title */}
                    <div className="form-control">
                        <label className="label">
                            <span className="label-text font-bold text-sm">Tên bài thi <span className="text-red-500">*</span></span>
                        </label>
                        <input
                            type="text"
                            placeholder="VD: Toán Cao Cấp - Đạo Hàm"
                            className="input input-bordered w-full rounded-xl focus:border-blue-500"
                            value={formData.title}
                            onChange={(e) => handleChange('title', e.target.value)}
                        />
                    </div>

                    {/* Description */}
                    <div className="form-control">
                        <label className="label">
                            <span className="label-text font-bold text-sm">Mô tả</span>
                        </label>
                        <textarea
                            placeholder="Mô tả ngắn gọn về nội dung bài thi..."
                            className="textarea textarea-bordered w-full rounded-xl focus:border-blue-500 resize-none"
                            rows={2}
                            value={formData.description}
                            onChange={(e) => handleChange('description', e.target.value)}
                        />
                    </div>

                    {/* Subject */}
                    <div className="form-control">
                        <label className="label">
                            <span className="label-text font-bold text-sm">Môn học <span className="text-red-500">*</span></span>
                        </label>
                        <div className="grid grid-cols-3 gap-2">
                            {Object.entries(SUBJECT_CONFIG).map(([key, config]) => (
                                <button
                                    key={key}
                                    onClick={() => handleChange('subjectKey', key)}
                                    className={`p-3 rounded-xl border-2 text-center transition-all ${formData.subjectKey === key
                                        ? 'border-blue-500 bg-blue-500/10'
                                        : 'border-base-300 hover:border-blue-500/30'
                                        }`}
                                >
                                    <span className="text-lg">{config.icon}</span>
                                    <p className="text-xs font-bold mt-1">{config.label}</p>
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Difficulty */}
                    <div className="form-control">
                        <label className="label">
                            <span className="label-text font-bold text-sm">Độ khó</span>
                        </label>
                        <div className="flex gap-2">
                            {Object.entries(DIFFICULTY_CONFIG).map(([key, config]) => (
                                <button
                                    key={key}
                                    onClick={() => handleChange('difficulty', key)}
                                    className={`flex-1 py-2 px-3 rounded-xl text-xs font-bold transition-all border-2 ${formData.difficulty === key
                                        ? `${config.bg} ${config.color} border-current`
                                        : 'border-base-300 text-base-content/60 hover:border-base-content/20'
                                        }`}
                                >
                                    {config.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Questions & Time */}
                    <div className="grid grid-cols-2 gap-4">
                        <div className="form-control">
                            <label className="label">
                                <span className="label-text font-bold text-sm">Số câu hỏi</span>
                            </label>
                            <input
                                type="number"
                                min={5}
                                max={100}
                                className="input input-bordered w-full rounded-xl focus:border-blue-500"
                                value={formData.totalQuestions}
                                onChange={(e) => handleChange('totalQuestions', parseInt(e.target.value) || 20)}
                            />
                        </div>
                        <div className="form-control">
                            <label className="label">
                                <span className="label-text font-bold text-sm">Thời gian (phút)</span>
                            </label>
                            <input
                                type="number"
                                min={5}
                                max={180}
                                className="input input-bordered w-full rounded-xl focus:border-blue-500"
                                value={formData.timeLimitMinutes}
                                onChange={(e) => handleChange('timeLimitMinutes', parseInt(e.target.value) || 30)}
                            />
                        </div>
                    </div>

                    {/* Question Types */}
                    <div className="form-control">
                        <label className="label">
                            <span className="label-text font-bold text-sm">Loại câu hỏi</span>
                        </label>
                        <div className="flex flex-wrap gap-2">
                            {Object.entries(QUESTION_TYPE_CONFIG).map(([key, config]) => (
                                <button
                                    key={key}
                                    onClick={() => toggleQuestionType(key)}
                                    className={`flex items-center gap-2 py-2 px-3 rounded-xl text-xs font-bold transition-all border-2 ${formData.questionTypes.includes(key)
                                        ? 'border-blue-500 bg-blue-500/10 text-blue-600'
                                        : 'border-base-300 text-base-content/60 hover:border-blue-500/30'
                                        }`}
                                >
                                    <Icon name={config.icon} size="sm" className={formData.questionTypes.includes(key) ? config.color : ''} />
                                    {config.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Options */}
                    <div className="space-y-3">
                        <label className="label">
                            <span className="label-text font-bold text-sm">Tùy chọn</span>
                        </label>
                        {[
                            { key: 'randomizeQuestions', label: 'Trộn thứ tự câu hỏi', icon: 'Shuffle' },
                            { key: 'randomizeOptions', label: 'Trộn thứ tự đáp án', icon: 'ArrowLeftRight' },
                            { key: 'showCorrectAnswers', label: 'Hiện đáp án đúng sau khi nộp', icon: 'Eye' },
                        ].map(opt => (
                            <label key={opt.key} className="flex items-center gap-3 p-3 bg-base-200/50 rounded-xl cursor-pointer hover:bg-base-200 transition-colors">
                                <input
                                    type="checkbox"
                                    className="toggle toggle-sm toggle-primary"
                                    checked={formData[opt.key]}
                                    onChange={(e) => handleChange(opt.key, e.target.checked)}
                                />
                                <Icon name={opt.icon} size="sm" className="text-base-content/60" />
                                <span className="text-sm font-medium">{opt.label}</span>
                            </label>
                        ))}
                    </div>
                </div>

                {/* Footer */}
                <div className="p-6 pt-4 border-t border-base-300 flex items-center justify-end gap-3">
                    <button onClick={onClose} className="btn btn-ghost rounded-xl font-bold">
                        Hủy
                    </button>
                    <motion.button
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        onClick={handleSubmit}
                        disabled={!formData.title || !formData.subjectKey}
                        className="btn bg-gradient-to-r from-blue-600 to-violet-600 hover:from-blue-700 hover:to-violet-700 text-white border-none rounded-xl font-bold shadow-lg shadow-blue-600/20 gap-2 disabled:opacity-50"
                    >
                        <Icon name="Plus" size="md" />
                        Tạo bài thi
                    </motion.button>
                </div>
            </motion.div>
        </motion.div>
    );
}

import { useParams, useLocation, useNavigate, Link } from 'react-router-dom';
import { useState } from 'react';
import * as motion from 'motion/react-client';
import Icon from '../icons/Icon';
import { CircularProgress } from '../common/ProgressBar';
import { DIFFICULTY_CONFIG, formatTime, getScoreColor, getScoreGrade } from './utils';

/**
 * ResultsHeader - Summary header with score circle
 */
function ResultsHeader({ percentScore, correctCount, totalQuestions, earnedPoints, totalPoints, timeSpent, testTitle }) {
    const grade = getScoreGrade(percentScore);
    const isPassed = percentScore >= 50;

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="bg-base-100 rounded-3xl shadow-xl border border-base-300 p-8 mb-6"
        >
            <div className="flex flex-col md:flex-row items-center gap-8">
                {/* Score Circle */}
                <div className="relative">
                    <svg width={160} height={160} className="-rotate-90">
                        <circle cx={80} cy={80} r={70} strokeWidth={10} fill="none" className="stroke-base-300" />
                        <motion.circle
                            cx={80} cy={80} r={70}
                            strokeWidth={10}
                            fill="none"
                            className={percentScore >= 80 ? 'stroke-green-500' : percentScore >= 50 ? 'stroke-blue-500' : 'stroke-red-500'}
                            strokeLinecap="round"
                            initial={{ strokeDashoffset: 440 }}
                            animate={{ strokeDashoffset: 440 - (440 * percentScore) / 100 }}
                            style={{ strokeDasharray: 440 }}
                            transition={{ duration: 1.5, ease: 'easeOut', delay: 0.3 }}
                        />
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                        <motion.span
                            initial={{ opacity: 0, scale: 0.5 }}
                            animate={{ opacity: 1, scale: 1 }}
                            transition={{ delay: 0.5, duration: 0.5 }}
                            className={`text-3xl font-black ${getScoreColor(percentScore)}`}
                        >
                            {Math.round(percentScore)}%
                        </motion.span>
                        <span className={`text-xs font-bold ${grade.color}`}>{grade.label}</span>
                    </div>
                </div>

                {/* Summary Stats */}
                <div className="flex-1 text-center md:text-left">
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        transition={{ delay: 0.3 }}
                    >
                        <h2 className="text-2xl font-black text-base-content mb-1">{testTitle}</h2>
                        <div className="flex items-center justify-center md:justify-start gap-2 mb-4">
                            {isPassed ? (
                                <span className="badge badge-success gap-1 font-bold">
                                    <Icon name="CheckCircle2" size="xs" /> Đạt
                                </span>
                            ) : (
                                <span className="badge badge-error gap-1 font-bold">
                                    <Icon name="XCircle" size="xs" /> Chưa đạt
                                </span>
                            )}
                        </div>
                    </motion.div>

                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                        {[
                            { icon: 'CheckCircle2', label: 'Câu đúng', value: `${correctCount}/${totalQuestions}`, color: 'text-green-500', bg: 'bg-green-500/10' },
                            { icon: 'XCircle', label: 'Câu sai', value: `${totalQuestions - correctCount}/${totalQuestions}`, color: 'text-red-500', bg: 'bg-red-500/10' },
                            { icon: 'Star', label: 'Điểm', value: `${earnedPoints.toFixed(1)}/${totalPoints.toFixed(1)}`, color: 'text-yellow-500', bg: 'bg-yellow-500/10' },
                            { icon: 'Clock', label: 'Thời gian', value: formatTime(timeSpent), color: 'text-blue-500', bg: 'bg-blue-500/10' },
                        ].map((stat, i) => (
                            <motion.div
                                key={stat.label}
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: 0.5 + i * 0.1 }}
                                className={`${stat.bg} rounded-xl p-3 text-center`}
                            >
                                <Icon name={stat.icon} size="md" className={`${stat.color} mx-auto mb-1`} />
                                <p className={`text-lg font-black ${stat.color}`}>{stat.value}</p>
                                <p className="text-[10px] font-bold text-base-content/50 uppercase">{stat.label}</p>
                            </motion.div>
                        ))}
                    </div>
                </div>
            </div>
        </motion.div>
    );
}

/**
 * ReviewQuestionCard - Shows question with correct/incorrect answer highlighting
 */
function ReviewQuestionCard({ question, questionIndex, userAnswer, showExplanation, onToggleExplanation }) {
    const isMultipleChoice = question.type === 'multiple_choice' || question.type === 'true_false';
    const isFillIn = question.type === 'fill_in_blank' || question.type === 'short_answer';
    const diffConfig = DIFFICULTY_CONFIG[question.difficulty] || {};

    let isCorrect = false;
    if (isMultipleChoice) {
        const correctOption = question.options.find(o => o.isCorrect);
        isCorrect = correctOption && userAnswer === correctOption.id;
    } else if (question.type === 'fill_in_blank') {
        isCorrect = question.acceptedAnswers?.some(a => a.toLowerCase() === (userAnswer || '').toLowerCase());
    }

    const borderColor = !userAnswer ? 'border-base-300' : isCorrect ? 'border-green-500/30' : 'border-red-500/30';
    const bgColor = !userAnswer ? '' : isCorrect ? 'bg-green-500/[0.02]' : 'bg-red-500/[0.02]';

    return (
        <motion.div
            initial={{ opacity: 0, y: 10 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.3 }}
            className={`bg-base-100 rounded-2xl shadow-md border-2 ${borderColor} ${bgColor} overflow-hidden`}
        >
            {/* Question Header */}
            <div className="p-5 pb-3">
                <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                        <span className={`text-xs font-black px-3 py-1 rounded-lg ${isCorrect
                            ? 'bg-green-500/10 text-green-600'
                            : !userAnswer
                                ? 'bg-base-200 text-base-content/50'
                                : 'bg-red-500/10 text-red-600'
                            }`}>
                            Câu {questionIndex + 1}
                        </span>
                        <span className={`badge badge-sm font-bold ${diffConfig.badge}`}>
                            {diffConfig.label}
                        </span>
                        <span className="text-xs text-base-content/40">{question.points} điểm</span>
                    </div>
                    <div className="flex items-center gap-2">
                        {isCorrect ? (
                            <span className="badge badge-success badge-sm gap-1 font-bold">
                                <Icon name="Check" size="xs" /> Đúng
                            </span>
                        ) : !userAnswer ? (
                            <span className="badge badge-ghost badge-sm gap-1 font-bold">
                                <Icon name="Minus" size="xs" /> Bỏ qua
                            </span>
                        ) : (
                            <span className="badge badge-error badge-sm gap-1 font-bold">
                                <Icon name="X" size="xs" /> Sai
                            </span>
                        )}
                    </div>
                </div>

                <p className="text-sm font-bold text-base-content leading-relaxed">{question.text}</p>
            </div>

            {/* Options with highlighting */}
            {isMultipleChoice && (
                <div className="px-5 pb-3 space-y-2">
                    {question.options.map((option, idx) => {
                        const isUserSelected = userAnswer === option.id;
                        const letters = ['A', 'B', 'C', 'D', 'E', 'F'];

                        let optionStyle = 'border-base-300 bg-base-100';
                        let letterStyle = 'bg-base-200 text-base-content/50';
                        let textStyle = 'text-base-content/70';

                        if (option.isCorrect) {
                            optionStyle = 'border-green-500/50 bg-green-500/5';
                            letterStyle = 'bg-green-500 text-white';
                            textStyle = 'text-green-700 font-bold';
                        } else if (isUserSelected && !option.isCorrect) {
                            optionStyle = 'border-red-500/50 bg-red-500/5';
                            letterStyle = 'bg-red-500 text-white';
                            textStyle = 'text-red-700 line-through font-medium';
                        }

                        return (
                            <div
                                key={option.id}
                                className={`flex items-center gap-3 p-3 rounded-xl border-2 ${optionStyle}`}
                            >
                                <span className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-black shrink-0 ${letterStyle}`}>
                                    {letters[idx]}
                                </span>
                                <span className={`text-sm ${textStyle}`}>{option.text}</span>
                                {option.isCorrect && (
                                    <Icon name="CheckCircle2" size="sm" className="ml-auto text-green-500 shrink-0" />
                                )}
                                {isUserSelected && !option.isCorrect && (
                                    <Icon name="XCircle" size="sm" className="ml-auto text-red-500 shrink-0" />
                                )}
                            </div>
                        );
                    })}
                </div>
            )}

            {/* Fill in blank answer */}
            {isFillIn && (
                <div className="px-5 pb-3 space-y-2">
                    <div className={`p-3 rounded-xl border-2 ${isCorrect ? 'border-green-500/30 bg-green-500/5' : 'border-red-500/30 bg-red-500/5'}`}>
                        <p className="text-xs text-base-content/50 font-bold mb-1">Câu trả lời của bạn:</p>
                        <p className={`text-sm font-bold ${isCorrect ? 'text-green-600' : 'text-red-600'}`}>
                            {userAnswer || '(Không trả lời)'}
                        </p>
                    </div>
                    {!isCorrect && question.correctAnswer && (
                        <div className="p-3 rounded-xl border-2 border-green-500/30 bg-green-500/5">
                            <p className="text-xs text-base-content/50 font-bold mb-1">Đáp án đúng:</p>
                            <p className="text-sm font-bold text-green-600">{question.correctAnswer}</p>
                        </div>
                    )}
                </div>
            )}

            {/* Explanation */}
            <div className="px-5 pb-4">
                <button
                    onClick={onToggleExplanation}
                    className="flex items-center gap-2 text-xs font-bold text-blue-500 hover:text-blue-600 transition-colors"
                >
                    <Icon name={showExplanation ? 'ChevronUp' : 'ChevronDown'} size="sm" />
                    {showExplanation ? 'Ẩn giải thích' : 'Xem giải thích'}
                </button>
                {showExplanation && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        transition={{ duration: 0.2 }}
                        className="mt-3 p-4 bg-blue-500/5 border border-blue-500/20 rounded-xl"
                    >
                        <div className="flex items-start gap-2">
                            <Icon name="Lightbulb" size="sm" className="text-blue-500 shrink-0 mt-0.5" />
                            <p className="text-sm text-base-content/80 leading-relaxed">{question.explanation}</p>
                        </div>
                    </motion.div>
                )}
            </div>
        </motion.div>
    );
}

/**
 * QuizResults - Main results page component
 * Route: /tests/:id/results
 */
export default function QuizResults() {
    const { id } = useParams();
    const location = useLocation();
    const navigate = useNavigate();
    const [expandedExplanations, setExpandedExplanations] = useState({});
    const [showAll, setShowAll] = useState(false);
    const [filterMode, setFilterMode] = useState('all'); // 'all', 'correct', 'incorrect', 'skipped'

    // Get data from navigation state
    const data = location.state;

    if (!data) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-base-200">
                <div className="text-center">
                    <Icon name="FileX" size="3xl" className="text-base-content/30 mx-auto mb-4" />
                    <h2 className="text-xl font-black text-base-content mb-2">Không có dữ liệu kết quả</h2>
                    <p className="text-sm text-base-content/60 mb-4">Bạn cần hoàn thành bài thi trước</p>
                    <button onClick={() => navigate('/tests')} className="btn btn-primary rounded-xl">
                        Về danh sách bài thi
                    </button>
                </div>
            </div>
        );
    }

    const { test, questions, answers, correctCount, totalQuestions, earnedPoints, totalPoints, percentScore, timeSpent } = data;

    const toggleExplanation = (idx) => {
        setExpandedExplanations(prev => ({ ...prev, [idx]: !prev[idx] }));
    };

    const expandAll = () => {
        const allExpanded = {};
        questions.forEach((_, idx) => { allExpanded[idx] = true; });
        setExpandedExplanations(allExpanded);
    };

    const collapseAll = () => {
        setExpandedExplanations({});
    };

    // Filter questions
    const filteredQuestions = questions.map((q, idx) => ({ question: q, index: idx })).filter(({ question, index }) => {
        const userAnswer = answers[index];
        const isMultipleChoice = question.type === 'multiple_choice' || question.type === 'true_false';

        let isCorrect = false;
        if (isMultipleChoice) {
            const correctOption = question.options.find(o => o.isCorrect);
            isCorrect = correctOption && userAnswer === correctOption.id;
        } else if (question.type === 'fill_in_blank') {
            isCorrect = question.acceptedAnswers?.some(a => a.toLowerCase() === (userAnswer || '').toLowerCase());
        }

        if (filterMode === 'correct') return isCorrect;
        if (filterMode === 'incorrect') return userAnswer && !isCorrect;
        if (filterMode === 'skipped') return !userAnswer;
        return true;
    });

    return (
        <div className="min-h-screen bg-base-200">
            {/* Top Navigation */}
            <div className="bg-base-100 border-b border-base-300 px-6 py-3">
                <div className="max-w-5xl mx-auto flex items-center justify-between">
                    <Link
                        to="/tests"
                        className="flex items-center gap-2 text-sm font-bold text-base-content/60 hover:text-base-content transition-colors"
                    >
                        <Icon name="ArrowLeft" size="sm" />
                        Quay lại danh sách
                    </Link>
                    <div className="flex items-center gap-3">
                        <Link
                            to={`/tests/${id}/take`}
                            className="btn btn-sm btn-ghost gap-2 rounded-xl font-bold"
                        >
                            <Icon name="RotateCcw" size="sm" />
                            Thi lại
                        </Link>
                        <motion.button
                            whileHover={{ scale: 1.02 }}
                            whileTap={{ scale: 0.98 }}
                            onClick={() => navigate('/tests')}
                            className="btn btn-sm bg-gradient-to-r from-blue-600 to-violet-600 text-white border-none rounded-xl font-bold"
                        >
                            Bài thi khác
                        </motion.button>
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <div className="max-w-5xl mx-auto p-6 lg:p-8">
                {/* Score Header */}
                <ResultsHeader
                    percentScore={percentScore}
                    correctCount={correctCount}
                    totalQuestions={totalQuestions}
                    earnedPoints={earnedPoints}
                    totalPoints={totalPoints}
                    timeSpent={timeSpent}
                    testTitle={test?.title || 'Bài thi'}
                />

                {/* Review Section Header */}
                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-6 gap-4">
                    <div>
                        <h3 className="text-xl font-black text-base-content">Xem lại bài làm</h3>
                        <p className="text-sm text-base-content/60">Phân tích chi tiết từng câu hỏi</p>
                    </div>
                    <div className="flex items-center gap-2">
                        {/* Filter Tabs */}
                        <div className="join">
                            {[
                                { key: 'all', label: 'Tất cả', count: totalQuestions },
                                { key: 'correct', label: 'Đúng', count: correctCount },
                                { key: 'incorrect', label: 'Sai', count: totalQuestions - correctCount - Object.keys(answers).filter(k => !answers[k]).length },
                                { key: 'skipped', label: 'Bỏ qua', count: totalQuestions - Object.keys(answers).filter(k => answers[k]).length },
                            ].map(tab => (
                                <button
                                    key={tab.key}
                                    onClick={() => setFilterMode(tab.key)}
                                    className={`btn btn-sm join-item gap-1 font-bold ${filterMode === tab.key ? 'btn-primary' : 'btn-ghost'}`}
                                >
                                    {tab.label}
                                    <span className="badge badge-xs">{tab.count}</span>
                                </button>
                            ))}
                        </div>

                        {/* Expand/Collapse */}
                        <button
                            onClick={Object.keys(expandedExplanations).length > 0 ? collapseAll : expandAll}
                            className="btn btn-sm btn-ghost gap-1 font-bold"
                        >
                            <Icon name={Object.keys(expandedExplanations).length > 0 ? 'ChevronsUp' : 'ChevronsDown'} size="sm" />
                        </button>
                    </div>
                </div>

                {/* Questions Review */}
                <div className="space-y-4">
                    {filteredQuestions.map(({ question, index }) => (
                        <ReviewQuestionCard
                            key={question.id}
                            question={question}
                            questionIndex={index}
                            userAnswer={answers[index]}
                            showExplanation={expandedExplanations[index]}
                            onToggleExplanation={() => toggleExplanation(index)}
                        />
                    ))}
                </div>

                {filteredQuestions.length === 0 && (
                    <div className="text-center py-12">
                        <Icon name="Inbox" size="3xl" className="text-base-content/20 mx-auto mb-4" />
                        <p className="text-base-content/50 font-bold">Không có câu hỏi nào trong danh mục này</p>
                    </div>
                )}

                {/* Bottom Actions */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true }}
                    className="mt-8 flex items-center justify-center gap-4"
                >
                    <Link
                        to={`/tests/${id}/take`}
                        className="btn bg-gradient-to-r from-blue-600 to-violet-600 text-white border-none rounded-xl font-bold shadow-lg shadow-blue-600/20 gap-2"
                    >
                        <Icon name="RotateCcw" size="sm" />
                        Thi lại bài này
                    </Link>
                    <Link
                        to="/tests"
                        className="btn btn-ghost rounded-xl font-bold gap-2"
                    >
                        <Icon name="LayoutGrid" size="sm" />
                        Tất cả bài thi
                    </Link>
                </motion.div>
            </div>
        </div>
    );
}

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import * as motion from 'motion/react-client';
import Icon from '../icons/Icon';
import { MOCK_QUESTIONS, MOCK_PRACTICE_TESTS, formatTime, DIFFICULTY_CONFIG } from './utils';

/**
 * QuizHeader - Header bar during quiz with timer, progress, and controls
 */
function QuizHeader({ test, currentIndex, totalQuestions, timeLeft, onSubmit, flaggedCount }) {
    const progress = ((currentIndex + 1) / totalQuestions) * 100;
    const isTimeLow = timeLeft <= 60;

    return (
        <div className="bg-base-100 border-b border-base-300 px-6 py-3">
            <div className="flex items-center justify-between">
                {/* Test Title */}
                <div className="flex items-center gap-3">
                    <div className="w-9 h-9 bg-gradient-to-br from-blue-600 to-violet-600 rounded-xl flex items-center justify-center">
                        <Icon name="FileText" size="sm" className="text-white" />
                    </div>
                    <div>
                        <h3 className="font-black text-sm text-base-content line-clamp-1">{test.title}</h3>
                        <p className="text-xs text-base-content/50">
                            Câu {currentIndex + 1}/{totalQuestions}
                        </p>
                    </div>
                </div>

                {/* Progress Bar */}
                <div className="hidden md:flex flex-1 mx-8 items-center gap-3">
                    <div className="flex-1 h-2 bg-base-300 rounded-full overflow-hidden">
                        <motion.div
                            className="h-full bg-gradient-to-r from-blue-500 to-violet-500 rounded-full"
                            animate={{ width: `${progress}%` }}
                            transition={{ duration: 0.3 }}
                        />
                    </div>
                    <span className="text-xs font-bold text-base-content/60 whitespace-nowrap">
                        {Math.round(progress)}%
                    </span>
                </div>

                {/* Timer + Actions */}
                <div className="flex items-center gap-3">
                    {/* Timer */}
                    <div className={`flex items-center gap-2 px-4 py-2 rounded-xl font-mono text-sm font-black ${isTimeLow
                        ? 'bg-red-500/10 text-red-500 animate-pulse'
                        : 'bg-base-200 text-base-content'
                        }`}>
                        <Icon name="Clock" size="sm" />
                        {formatTime(timeLeft)}
                    </div>

                    {/* Flagged */}
                    {flaggedCount > 0 && (
                        <div className="flex items-center gap-1 px-3 py-2 bg-orange-500/10 rounded-xl">
                            <Icon name="Flag" size="sm" className="text-orange-500" />
                            <span className="text-xs font-bold text-orange-500">{flaggedCount}</span>
                        </div>
                    )}

                    {/* Submit */}
                    <motion.button
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        onClick={onSubmit}
                        className="btn btn-sm bg-gradient-to-r from-blue-600 to-violet-600 text-white border-none rounded-xl font-bold shadow-lg shadow-blue-600/20 gap-1"
                    >
                        <Icon name="Send" size="sm" />
                        Nộp bài
                    </motion.button>
                </div>
            </div>
        </div>
    );
}

/**
 * QuestionCard - Renders a single question depending on type
 */
function QuestionCard({ question, questionIndex, answer, onAnswer, isFlagged, onToggleFlag }) {
    const diffConfig = DIFFICULTY_CONFIG[question.difficulty] || {};

    return (
        <motion.div
            key={question.id}
            initial={{ opacity: 0, x: 30 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -30 }}
            transition={{ duration: 0.3, ease: [0.25, 0.46, 0.45, 0.94] }}
            className="bg-base-100 rounded-3xl shadow-xl border border-base-300 overflow-hidden"
        >
            {/* Question Header */}
            <div className="p-6 pb-4 border-b border-base-200">
                <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                        <span className="text-xs font-black text-blue-500 bg-blue-500/10 px-3 py-1 rounded-lg">
                            Câu {questionIndex + 1}
                        </span>
                        <span className={`badge badge-sm font-bold ${diffConfig.badge}`}>
                            {diffConfig.label}
                        </span>
                        <span className="text-xs text-base-content/40 font-medium">
                            {question.points} điểm
                        </span>
                    </div>
                    <button
                        onClick={onToggleFlag}
                        className={`btn btn-circle btn-sm ${isFlagged ? 'btn-warning' : 'btn-ghost'}`}
                        title={isFlagged ? 'Bỏ đánh dấu' : 'Đánh dấu xem lại'}
                    >
                        <Icon name="Flag" size="sm" className={isFlagged ? 'text-white fill-white' : ''} />
                    </button>
                </div>

                <p className="text-base font-bold text-base-content leading-relaxed">
                    {question.text}
                </p>

                {question.imageUrl && (
                    <img
                        src={question.imageUrl}
                        alt="Question"
                        className="mt-3 rounded-xl max-h-60 object-contain"
                    />
                )}
            </div>

            {/* Answer Area */}
            <div className="p-6">
                {(question.type === 'multiple_choice' || question.type === 'true_false') && (
                    <div className="space-y-3">
                        {question.options.map((option, idx) => {
                            const isSelected = answer === option.id;
                            const letters = ['A', 'B', 'C', 'D', 'E', 'F'];
                            return (
                                <motion.button
                                    key={option.id}
                                    whileHover={{ scale: 1.01 }}
                                    whileTap={{ scale: 0.99 }}
                                    onClick={() => onAnswer(option.id)}
                                    className={`w-full flex items-center gap-4 p-4 rounded-2xl border-2 text-left transition-all ${isSelected
                                        ? 'border-blue-500 bg-blue-500/10 shadow-lg shadow-blue-500/10'
                                        : 'border-base-300 hover:border-blue-500/30 hover:bg-base-200/50'
                                        }`}
                                >
                                    <span className={`w-9 h-9 rounded-xl flex items-center justify-center text-sm font-black shrink-0 transition-all ${isSelected
                                        ? 'bg-blue-500 text-white'
                                        : 'bg-base-200 text-base-content/60'
                                        }`}>
                                        {letters[idx]}
                                    </span>
                                    <span className={`font-medium text-sm ${isSelected ? 'text-blue-600 font-bold' : 'text-base-content'}`}>
                                        {option.text}
                                    </span>
                                    {isSelected && (
                                        <Icon name="CheckCircle2" size="md" className="ml-auto text-blue-500 shrink-0" />
                                    )}
                                </motion.button>
                            );
                        })}
                    </div>
                )}

                {(question.type === 'fill_in_blank' || question.type === 'short_answer') && (
                    <div>
                        <textarea
                            placeholder={question.type === 'fill_in_blank' ? 'Nhập câu trả lời...' : 'Viết câu trả lời ngắn gọn...'}
                            className="textarea textarea-bordered w-full rounded-xl focus:border-blue-500 text-sm resize-none"
                            rows={question.type === 'fill_in_blank' ? 2 : 4}
                            value={answer || ''}
                            onChange={(e) => onAnswer(e.target.value)}
                        />
                    </div>
                )}
            </div>
        </motion.div>
    );
}

/**
 * QuestionNavigator - Panel showing all question numbers for quick navigation
 */
function QuestionNavigator({ totalQuestions, currentIndex, answers, flaggedQuestions, onNavigate }) {
    return (
        <div className="bg-base-100 rounded-2xl shadow-lg border border-base-300 p-4">
            <h4 className="font-black text-sm text-base-content mb-3 flex items-center gap-2">
                <Icon name="LayoutGrid" size="sm" className="text-blue-500" />
                Danh sách câu hỏi
            </h4>
            <div className="grid grid-cols-5 gap-2">
                {Array.from({ length: totalQuestions }, (_, i) => {
                    const isActive = i === currentIndex;
                    const isAnswered = answers[i] !== undefined && answers[i] !== null && answers[i] !== '';
                    const isFlagged = flaggedQuestions.includes(i);

                    return (
                        <motion.button
                            key={i}
                            whileHover={{ scale: 1.1 }}
                            whileTap={{ scale: 0.9 }}
                            onClick={() => onNavigate(i)}
                            className={`relative w-full aspect-square rounded-xl text-xs font-black transition-all flex items-center justify-center ${isActive
                                ? 'bg-gradient-to-br from-blue-600 to-violet-600 text-white shadow-lg'
                                : isAnswered
                                    ? 'bg-green-500/15 text-green-600 border border-green-500/30'
                                    : 'bg-base-200 text-base-content/50 hover:bg-base-300'
                                }`}
                        >
                            {i + 1}
                            {isFlagged && (
                                <span className="absolute -top-1 -right-1 w-3 h-3 bg-orange-500 rounded-full border-2 border-base-100" />
                            )}
                        </motion.button>
                    );
                })}
            </div>

            {/* Legend */}
            <div className="mt-4 space-y-2">
                <div className="flex items-center gap-2 text-xs text-base-content/50">
                    <span className="w-4 h-4 rounded bg-gradient-to-br from-blue-600 to-violet-600" />
                    Đang xem
                </div>
                <div className="flex items-center gap-2 text-xs text-base-content/50">
                    <span className="w-4 h-4 rounded bg-green-500/15 border border-green-500/30" />
                    Đã trả lời
                </div>
                <div className="flex items-center gap-2 text-xs text-base-content/50">
                    <span className="w-4 h-4 rounded bg-base-200" />
                    Chưa trả lời
                </div>
                <div className="flex items-center gap-2 text-xs text-base-content/50">
                    <span className="relative w-4 h-4 rounded bg-base-200">
                        <span className="absolute -top-0.5 -right-0.5 w-2 h-2 bg-orange-500 rounded-full" />
                    </span>
                    Đánh dấu
                </div>
            </div>
        </div>
    );
}

/**
 * SubmitConfirmModal - Confirm dialog before submitting quiz
 */
function SubmitConfirmModal({ isOpen, onClose, onConfirm, answered, total, flagged }) {
    if (!isOpen) return null;

    const unanswered = total - answered;

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4"
        >
            <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
            <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-base-100 rounded-3xl shadow-2xl w-full max-w-md relative z-10 p-6"
            >
                <div className="text-center mb-6">
                    <div className="w-16 h-16 mx-auto bg-gradient-to-br from-blue-600 to-violet-600 rounded-2xl flex items-center justify-center mb-4">
                        <Icon name="Send" size="xl" className="text-white" />
                    </div>
                    <h3 className="text-xl font-black text-base-content mb-2">Nộp bài thi?</h3>
                    <p className="text-sm text-base-content/60">Hãy kiểm tra lại trước khi nộp bài</p>
                </div>

                {/* Stats */}
                <div className="grid grid-cols-3 gap-3 mb-6">
                    <div className="text-center p-3 bg-green-500/10 rounded-xl">
                        <p className="text-lg font-black text-green-600">{answered}</p>
                        <p className="text-[10px] text-base-content/50 font-bold uppercase">Đã trả lời</p>
                    </div>
                    <div className="text-center p-3 bg-orange-500/10 rounded-xl">
                        <p className="text-lg font-black text-orange-600">{unanswered}</p>
                        <p className="text-[10px] text-base-content/50 font-bold uppercase">Chưa trả lời</p>
                    </div>
                    <div className="text-center p-3 bg-yellow-500/10 rounded-xl">
                        <p className="text-lg font-black text-yellow-600">{flagged}</p>
                        <p className="text-[10px] text-base-content/50 font-bold uppercase">Đánh dấu</p>
                    </div>
                </div>

                {unanswered > 0 && (
                    <div className="p-3 bg-orange-500/5 border border-orange-500/20 rounded-xl mb-4">
                        <p className="text-xs text-orange-600 font-bold flex items-center gap-2">
                            <Icon name="AlertTriangle" size="sm" />
                            Bạn còn {unanswered} câu chưa trả lời!
                        </p>
                    </div>
                )}

                <div className="flex gap-3">
                    <button onClick={onClose} className="btn flex-1 btn-ghost rounded-xl font-bold">
                        Quay lại
                    </button>
                    <motion.button
                        whileHover={{ scale: 1.02 }}
