/**
 * QuizTaking - Main quiz-taking component
 * Route: /tests/:id/take
 */
export default function QuizTaking() {
    const { id } = useParams();
    const navigate = useNavigate();

    // Find the test
    const test = MOCK_PRACTICE_TESTS.find(t => t.id === id);
    const questions = useMemo(() => MOCK_QUESTIONS.slice(0, test?.totalQuestions || 10), [test]);

    // State
    const [currentIndex, setCurrentIndex] = useState(0);
    const [answers, setAnswers] = useState({});
    const [flaggedQuestions, setFlaggedQuestions] = useState([]);
    const [timeLeft, setTimeLeft] = useState((test?.timeLimitMinutes || 30) * 60);
    const [showSubmitModal, setShowSubmitModal] = useState(false);

    // Timer
    useEffect(() => {
        if (timeLeft <= 0) {
            handleSubmit();
            return;
        }
        const timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
        return () => clearInterval(timer);
    }, [timeLeft]);

    // Keyboard navigation
    const handleKeyPress = useCallback((e) => {
        if (e.key === 'ArrowLeft' && currentIndex > 0) {
            e.preventDefault();
            setCurrentIndex(prev => prev - 1);
        } else if (e.key === 'ArrowRight' && currentIndex < questions.length - 1) {
            e.preventDefault();
            setCurrentIndex(prev => prev + 1);
        }
    }, [currentIndex, questions.length]);

    useEffect(() => {
        window.addEventListener('keydown', handleKeyPress);
        return () => window.removeEventListener('keydown', handleKeyPress);
    }, [handleKeyPress]);

    const handleAnswer = (value) => {
        setAnswers(prev => ({ ...prev, [currentIndex]: value }));
    };

    const handleToggleFlag = () => {
        setFlaggedQuestions(prev =>
            prev.includes(currentIndex)
                ? prev.filter(i => i !== currentIndex)
                : [...prev, currentIndex]
        );
    };

    const handleSubmit = () => {
        // Calculate results
        let correctCount = 0;
        let totalPoints = 0;
        let earnedPoints = 0;

        questions.forEach((q, idx) => {
            totalPoints += q.points;
            const userAnswer = answers[idx];
            if (!userAnswer) return;

            if (q.type === 'multiple_choice' || q.type === 'true_false') {
                const correctOption = q.options.find(o => o.isCorrect);
                if (correctOption && userAnswer === correctOption.id) {
                    correctCount++;
                    earnedPoints += q.points;
                }
            } else if (q.type === 'fill_in_blank') {
                if (q.acceptedAnswers?.some(a => a.toLowerCase() === userAnswer.toLowerCase())) {
                    correctCount++;
                    earnedPoints += q.points;
                }
            }
        });

        const percentScore = totalPoints > 0 ? (earnedPoints / totalPoints) * 100 : 0;

        // Navigate to results with state
        navigate(`/tests/${id}/results`, {
            state: {
                test,
                questions,
                answers,
                flaggedQuestions,
                correctCount,
                totalQuestions: questions.length,
                earnedPoints,
                totalPoints,
                percentScore,
                timeSpent: (test?.timeLimitMinutes || 30) * 60 - timeLeft,
            }
        });
    };

    if (!test) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-base-200">
                <div className="text-center">
                    <Icon name="FileX" size="3xl" className="text-base-content/30 mx-auto mb-4" />
                    <h2 className="text-xl font-black text-base-content mb-2">Không tìm thấy bài thi</h2>
                    <button onClick={() => navigate('/tests')} className="btn btn-primary rounded-xl mt-4">
                        Về danh sách
                    </button>
                </div>
            </div>
        );
    }

    const currentQuestion = questions[currentIndex];
    const answeredCount = Object.keys(answers).filter(k => answers[k] !== undefined && answers[k] !== null && answers[k] !== '').length;

    return (
        <div className="min-h-screen bg-base-200 flex flex-col">
            {/* Header */}
            <QuizHeader
                test={test}
                currentIndex={currentIndex}
                totalQuestions={questions.length}
                timeLeft={timeLeft}
                onSubmit={() => setShowSubmitModal(true)}
                flaggedCount={flaggedQuestions.length}
            />

            {/* Main Content */}
            <div className="flex-1 flex">
                {/* Question Area */}
                <div className="flex-1 p-6 lg:p-8 overflow-y-auto">
                    <div className="max-w-3xl mx-auto">
                        {currentQuestion && (
                            <QuestionCard
                                question={currentQuestion}
                                questionIndex={currentIndex}
                                answer={answers[currentIndex]}
                                onAnswer={handleAnswer}
                                isFlagged={flaggedQuestions.includes(currentIndex)}
                                onToggleFlag={handleToggleFlag}
                            />
                        )}

                        {/* Navigation */}
                        <div className="flex items-center justify-between mt-6">
                            <motion.button
                                whileHover={{ scale: 1.02 }}
                                whileTap={{ scale: 0.98 }}
                                onClick={() => setCurrentIndex(prev => prev - 1)}
                                disabled={currentIndex === 0}
                                className="btn btn-ghost rounded-xl gap-2 font-bold disabled:opacity-30"
                            >
                                <Icon name="ArrowLeft" size="sm" />
                                Câu trước
                            </motion.button>

                            <span className="text-sm font-bold text-base-content/50">
                                {currentIndex + 1} / {questions.length}
                            </span>

                            {currentIndex < questions.length - 1 ? (
                                <motion.button
                                    whileHover={{ scale: 1.02 }}
                                    whileTap={{ scale: 0.98 }}
                                    onClick={() => setCurrentIndex(prev => prev + 1)}
                                    className="btn bg-gradient-to-r from-blue-600 to-violet-600 text-white border-none rounded-xl gap-2 font-bold shadow-lg shadow-blue-600/20"
                                >
                                    Câu tiếp
                                    <Icon name="ArrowRight" size="sm" />
                                </motion.button>
                            ) : (
                                <motion.button
                                    whileHover={{ scale: 1.02 }}
                                    whileTap={{ scale: 0.98 }}
                                    onClick={() => setShowSubmitModal(true)}
                                    className="btn bg-gradient-to-r from-green-600 to-emerald-600 text-white border-none rounded-xl gap-2 font-bold shadow-lg"
                                >
                                    <Icon name="Send" size="sm" />
                                    Nộp bài
                                </motion.button>
                            )}
                        </div>

                        {/* Keyboard hint */}
                        <div className="mt-4 text-center">
                            <p className="text-xs text-base-content/30 font-medium">
                                Dùng phím ← → để di chuyển giữa các câu hỏi
                            </p>
                        </div>
                    </div>
                </div>

                {/* Side Panel - Question Navigator */}
                <div className="hidden lg:block w-72 p-4 border-l border-base-300 bg-base-100/50 overflow-y-auto">
                    <QuestionNavigator
                        totalQuestions={questions.length}
                        currentIndex={currentIndex}
                        answers={answers}
                        flaggedQuestions={flaggedQuestions}
                        onNavigate={setCurrentIndex}
                    />
                </div>
            </div>

            {/* Submit Confirmation Modal */}
            <SubmitConfirmModal
                isOpen={showSubmitModal}
                onClose={() => setShowSubmitModal(false)}
                onConfirm={handleSubmit}
                answered={answeredCount}
                total={questions.length}
                flagged={flaggedQuestions.length}
            />
        </div>
    );
}

