                    {/* Back link */}
                    {currentStep < 3 && (
                        <motion.div
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            className="mb-6"
                        >
                            <Link
                                to="/"
                                className="inline-flex items-center gap-2 text-sm font-bold text-base-content/50 hover:text-violet-600 transition-colors group"
                            >
