            try {
                setLoading(true);
                const response = await subjectApi.getAll({ limit: 100 });
                const items = response.data?.items || response.data || [];
                setSubjects(items.map(mapApiToCourse));
            } catch (err) {
                console.error('Error fetching subjects:', err);
                setError(err.message);
            } finally {
                setLoading(false);
            }
