                Vui lòng kiểm tra lại mã đơn hàng.
            </p>
            <button
                onClick={onGoBack}
                className="btn btn-sm btn-primary rounded-xl font-bold"
            >
                <ArrowLeft className="w-4 h-4" />
                Quay lại danh sách
            </button>
        </motion.div>
    );
}

import { useState, useMemo } from 'react';
import * as motion from 'motion/react-client';
import { DashboardSidebar } from '../components/learner';
import {
    Search,
    Bell,
    Star,
    ShoppingBag,
    TrendingUp,
    Package,
    AlertCircle,
    Inbox
} from 'lucide-react';
import { StatCard } from '../components/common';
import {
    OrderCard,
    OrderFilters,
    MOCK_ORDERS,
    formatCurrency
} from '../components/orders';

/**
 * Orders Page — Lịch sử đơn hàng
 * Route: /orders
 * 
 * Maps to: orders, order_items, transactions tables
 * 
 * Layout: DashboardSidebar + Header + Main Content
 * Sections: Stats → Filters → Order List → Empty State
 */
export default function Orders() {
    // ─── State ──────────────────────────────────────────
    const [filters, setFilters] = useState({
        status: 'all',
        sortBy: 'newest',
        timeRange: 'all',
        search: ''
    });

    // ─── Animation Variants ─────────────────────────────
    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: {
                staggerChildren: 0.08,
                delayChildren: 0.1
            }
        }
    };

    const cardVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: { duration: 0.4, ease: [0.25, 0.46, 0.45, 0.94] }
        }
    };

    // ─── Computed Data ──────────────────────────────────
    const stats = useMemo(() => {
        const total = MOCK_ORDERS.length;
        const completed = MOCK_ORDERS.filter(o => o.status === 'completed').length;
        const pending = MOCK_ORDERS.filter(o => o.status === 'pending').length;
        const totalSpent = MOCK_ORDERS
            .filter(o => o.status === 'completed')
            .reduce((sum, o) => sum + o.finalAmount, 0);

        return { total, completed, pending, totalSpent };
    }, []);

    const filteredOrders = useMemo(() => {
        let result = [...MOCK_ORDERS];

        // Filter by status
        if (filters.status !== 'all') {
            result = result.filter(o => o.status === filters.status);
        }

        // Filter by search
        if (filters.search) {
            const query = filters.search.toLowerCase();
            result = result.filter(o =>
                o.id.toLowerCase().includes(query)
                || o.items?.some(item => item.name.toLowerCase().includes(query))
            );
        }

        // Sort
        switch (filters.sortBy) {
            case 'oldest':
                result.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
                break;
            case 'highest':
                result.sort((a, b) => b.finalAmount - a.finalAmount);
                break;
            case 'lowest':
                result.sort((a, b) => a.finalAmount - b.finalAmount);
                break;
            default: // newest
                result.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
        }

        return result;
    }, [filters]);

    // ─── Render ─────────────────────────────────────────
    return (
        <div className="flex h-screen bg-base-200 overflow-hidden">
            {/* Sidebar */}
            <DashboardSidebar />

            {/* Main Content */}
            <div className="flex-1 flex flex-col overflow-hidden">
                {/* Header */}
                <OrdersHeader />

                {/* Page Content */}
                <motion.main
                    className="flex-1 overflow-y-auto p-6 lg:p-8"
                    variants={containerVariants}
                    initial="hidden"
                    animate="visible"
                >
                    {/* Stats Row */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
                        <StatCard
                            icon="ShoppingBag"
                            label="Tổng Đơn Hàng"
                            value={stats.total}
                            iconBgColor="bg-blue-500/10"
                            iconColor="text-blue-500"
                            variants={cardVariants}
                        />
                        <StatCard
                            icon="CheckCircle2"
                            label="Hoàn Thành"
                            value={stats.completed}
                            iconBgColor="bg-emerald-500/10"
                            iconColor="text-emerald-500"
                            variants={cardVariants}
                        />
                        <StatCard
                            icon="Clock"
                            label="Chờ Xử Lý"
                            value={stats.pending}
                            iconBgColor="bg-amber-500/10"
                            iconColor="text-amber-500"
                            variants={cardVariants}
                        />
                        <StatCard
                            icon="Wallet"
                            label="Tổng Chi Tiêu"
                            value={formatCurrency(stats.totalSpent)}
                            iconBgColor="bg-violet-500/10"
                            iconColor="text-violet-500"
                            variants={cardVariants}
                        />
                    </div>

                    {/* Filters */}
                    <motion.div variants={cardVariants} className="mb-6">
                        <OrderFilters
                            filters={filters}
                            onFilterChange={setFilters}
                        />
                    </motion.div>

                    {/* Results count */}
                    <motion.div
                        variants={cardVariants}
                        className="flex items-center justify-between mb-4"
                    >
                        <p className="text-sm text-base-content/50 font-medium">
                            Hiển thị <span className="font-bold text-base-content">{filteredOrders.length}</span> đơn hàng
                        </p>
                    </motion.div>

                    {/* Order List */}
                    {filteredOrders.length > 0 ? (
                        <div className="space-y-3">
                            {filteredOrders.map((order, index) => (
                                <OrderCard
                                    key={order.id}
                                    order={order}
                                    index={index}
                                    variants={cardVariants}
                                />
                            ))}
                        </div>
                    ) : (
                        /* Empty State */
                        <EmptyState
                            hasFilters={filters.status !== 'all' || filters.search}
                            onReset={() => setFilters({
                                status: 'all',
                                sortBy: 'newest',
                                timeRange: 'all',
                                search: ''
                            })}
                        />
                    )}

                    {/* Bottom spacer for smooth scroll */}
                    <div className="h-8" />
                </motion.main>
            </div>
        </div>
    );
}

// ─── Sub-Components ─────────────────────────────────────────

/**
 * OrdersHeader — Header riêng cho trang Orders
 */
function OrdersHeader() {
    return (
        <motion.header
            initial={{ y: -100 }}
            animate={{ y: 0 }}
            transition={{ duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] }}
            className="bg-base-100 border-b border-base-300 px-8 py-4"
        >
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-black text-base-content flex items-center gap-2">
