} from 'lucide-react';

export default function Profile() {
    const [isEditing, setIsEditing] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const [showNewPassword, setShowNewPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [activeSection, setActiveSection] = useState('profile');
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);

    // Password change state
    const [passwordData, setPasswordData] = useState({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [passwordError, setPasswordError] = useState('');
    const [passwordSuccess, setPasswordSuccess] = useState('');

    // Animation variants
    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: {
                staggerChildren: 0.1,
                delayChildren: 0.2
            }
        }
    };

    const cardVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: { duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] }
        }
    };

    // Mock user data
    const [userData, setUserData] = useState({
        name: 'Đoàn Thế Anh',
        email: 'anh.nguyen@skr.edu.vn',
        phone: '+84 912 345 678',
        location: 'Hà Nội, Việt Nam',
        bio: 'Sinh viên năm 3 ngành Công nghệ thông tin. Đam mê học AI và Machine Learning.',
        joinDate: 'Tháng 1, 2024',
        isPremium: true
    });

    // User stats
    const userStats = {
        studyStreak: 27,
        totalFlashcards: 1234,
        testsCompleted: 45,
        hoursStudied: 156,
        achievements: 12,
        rank: 'Platinum Learner'
    };

    // Notification settings
    const [notifications, setNotifications] = useState({
        emailNotifications: true,
        pushNotifications: true,
        studyReminders: true,
        weeklyReport: true,
        achievements: true,
        communityUpdates: false
    });

    // Fetch user data from API
    useEffect(() => {
        const fetchUserData = async () => {
            // Debug: kiem tra token
            const token = localStorage.getItem('accessToken');
            console.log('Profile: Token from localStorage:', token ? token.substring(0, 20) + '...' : 'NULL');

            try {
                setLoading(true);
                const response = await authApi.getMe();
                // Backend tra ve: { success, message, data: { userId, email, username, fullName, ... } }
                // axiosClient interceptor tra ve response.data => response = { success, message, data }
                const user = response.data || response.user || response;
                setUserData({
                    name: user.fullName || user.displayName || user.username || 'User',
                    email: user.email || '',
                    phone: user.phoneNumber || '',
                    location: '',
                    bio: user.bio || '',
                    joinDate: user.createdAt ? new Date(user.createdAt).toLocaleDateString('vi-VN', { month: 'long', year: 'numeric' }) : '',
                    isPremium: user.isPremium || false
                });
            } catch (err) {
                console.error('Failed to fetch user data:', err);
                // Neu 401 thi khong lam gi - hien thi mock data
                if (err.response?.status === 401) {
                    console.log('Unauthorized, using mock data');
                }
            } finally {
                setLoading(false);
            }
        };
        fetchUserData();
    }, []);

    // Handle save profile
    const handleSaveProfile = async () => {
        try {
            setSaving(true);
            await authApi.updateProfile({
                fullName: userData.name,
                phoneNumber: userData.phone,
                bio: userData.bio
            });
            setIsEditing(false);
        } catch (err) {
            console.error('Failed to update profile:', err);
            alert(err.response?.data?.message || 'Cập nhật thất bại');
        } finally {
            setSaving(false);
        }
    };

    // Handle change password
    const handleChangePassword = async () => {
        setPasswordError('');
        setPasswordSuccess('');

        if (passwordData.newPassword !== passwordData.confirmPassword) {
            setPasswordError('Mật khẩu mới không khớp');
            return;
        }

        if (passwordData.newPassword.length < 6) {
            setPasswordError('Mật khẩu mới phải có ít nhất 6 ký tự');
            return;
        }

        try {
            setSaving(true);
            await authApi.changePassword({
                currentPassword: passwordData.currentPassword,
                newPassword: passwordData.newPassword
            });
            setPasswordSuccess('Đổi mật khẩu thành công');
            setPasswordData({
                currentPassword: '',
                newPassword: '',
                confirmPassword: ''
