import { useState, useEffect, useRef, useCallback } from 'react';
import * as motion from 'motion/react-client';
import { useNavigate, useSearchParams, Link } from 'react-router-dom';
import {
    Lock,
    ShieldCheck,
    ArrowRight,
    ArrowLeft,
    AlertCircle,
    CheckCircle2,
    Loader2,
    RefreshCw,
    GraduationCap,
    Eye,
    EyeOff,
} from 'lucide-react';
import { authApi } from '../api';

/* ================== Constants ================== */

const OTP_LENGTH = 6;
const RESEND_COOLDOWN = 60; // giay

/* ================== Sub-components ================== */

/**
 * Single OTP digit input box.
 */
const OtpDigitInput = ({ index, value, onChange, onKeyDown, onPaste, inputRef, disabled }) => {
    const [isFocused, setIsFocused] = useState(false);
    const hasValue = value !== '';

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4, delay: 0.05 * index }}
            className="relative"
        >
            {/* Gradient glow khi focus */}
            <motion.div
                animate={isFocused ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0.9 }}
                transition={{ duration: 0.2 }}
                className="absolute -inset-1 bg-gradient-to-r from-blue-600 to-violet-600 rounded-2xl blur opacity-40"
            />

            <input
                ref={inputRef}
                type="text"
                inputMode="numeric"
                maxLength={1}
                value={value}
                disabled={disabled}
                onChange={(e) => onChange(index, e.target.value)}
                onKeyDown={(e) => onKeyDown(index, e)}
                onPaste={onPaste}
                onFocus={() => setIsFocused(true)}
                onBlur={() => setIsFocused(false)}
                aria-label={`Digit ${index + 1}`}
                className={`
                    relative w-14 h-16 sm:w-16 sm:h-[4.5rem] text-center text-2xl font-black
                    rounded-2xl border-2 outline-none transition-all duration-300
                    bg-base-100 caret-transparent select-none
                    disabled:opacity-50 disabled:cursor-not-allowed
                    ${isFocused
                        ? 'border-blue-500 shadow-lg shadow-blue-500/20'
                        : hasValue
                            ? 'border-blue-400/60 shadow-md shadow-blue-400/10'
                            : 'border-base-300 hover:border-base-content/20'
                    }
                    ${hasValue ? 'text-blue-600' : 'text-base-content'}
                `}
            />

            {/* Bottom dot indicator */}
            <motion.div
                animate={hasValue ? { scale: 1, opacity: 1 } : { scale: 0, opacity: 0 }}
                className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-1.5 h-1.5 rounded-full bg-gradient-to-r from-blue-600 to-violet-600"
            />
        </motion.div>
    );
};

/**
 * Countdown timer for OTP resend cooldown.
 */
const ResendTimer = ({ seconds }) => {
    const mins = String(Math.floor(seconds / 60)).padStart(2, '0');
    const secs = String(seconds % 60).padStart(2, '0');

    return (
        <span className="font-mono font-bold text-blue-600 tabular-nums">
            {mins}:{secs}
        </span>
    );
};

/* ================== Main Component ================== */

export default function ResetPassword() {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const email = searchParams.get('email') || '';

    // OTP state
    const [digits, setDigits] = useState(Array(OTP_LENGTH).fill(''));
    const inputRefs = useRef([]);

    // Password state
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);

    // UI state
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [resendCooldown, setResendCooldown] = useState(RESEND_COOLDOWN);
    const [resendLoading, setResendLoading] = useState(false);

    /* ---------- Redirect if no email ---------- */
    useEffect(() => {
        if (!email) {
            navigate('/forgot-password', { replace: true });
        }
    }, [email, navigate]);

    /* ---------- Resend cooldown timer ---------- */
    useEffect(() => {
        if (resendCooldown <= 0) return;

        const timer = setInterval(() => {
            setResendCooldown((prev) => prev - 1);
        }, 1000);

        return () => clearInterval(timer);
    }, [resendCooldown]);

    /* ---------- OTP input handlers ---------- */

    const focusInput = useCallback((index) => {
        inputRefs.current[index]?.focus();
    }, []);

    const handleChange = useCallback((index, value) => {
        const digit = value.replace(/\D/g, '').slice(-1);
        setDigits((prev) => {
            const next = [...prev];
            next[index] = digit;
            return next;
        });
        setError('');

        if (digit && index < OTP_LENGTH - 1) {
            focusInput(index + 1);
        }
    }, [focusInput]);

    const handleKeyDown = useCallback((index, e) => {
        if (e.key === 'Backspace') {
            if (!digits[index] && index > 0) {
                setDigits((prev) => {
                    const next = [...prev];
                    next[index - 1] = '';
                    return next;
                });
                focusInput(index - 1);
            } else {
                setDigits((prev) => {
                    const next = [...prev];
                    next[index] = '';
                    return next;
                });
            }
            e.preventDefault();
        } else if (e.key === 'ArrowLeft' && index > 0) {
            focusInput(index - 1);
        } else if (e.key === 'ArrowRight' && index < OTP_LENGTH - 1) {
            focusInput(index + 1);
        }
    }, [digits, focusInput]);

    const handlePaste = useCallback((e) => {
        e.preventDefault();
        const pasted = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, OTP_LENGTH);
        if (!pasted) return;

        const newDigits = Array(OTP_LENGTH).fill('');
        for (let i = 0; i < pasted.length; i++) {
            newDigits[i] = pasted[i];
        }
        setDigits(newDigits);
        setError('');

        const focusIdx = Math.min(pasted.length, OTP_LENGTH - 1);
        focusInput(focusIdx);
    }, [focusInput]);

    /* ---------- Submit OTP + Password ---------- */
    const otpString = digits.join('');
    const isOtpComplete = otpString.length === OTP_LENGTH;
    const isFormValid = isOtpComplete && newPassword.length >= 6 && newPassword === confirmPassword;

    const handleSubmit = async (e) => {
        e?.preventDefault();

        if (!isOtpComplete) {
            setError('Vui lòng nhập đầy đủ mã OTP 6 chữ số.');
            return;
        }

        if (!newPassword) {
            setError('Vui lòng nhập mật khẩu mới.');
            return;
        }

        if (newPassword.length < 6) {
            setError('Mật khẩu phải có ít nhất 6 ký tự.');
            return;
        }

        if (newPassword !== confirmPassword) {
            setError('Mật khẩu xác nhận không khớp!');
            return;
        }

        setLoading(true);
        setError('');
        setSuccess('');

        try {
            const data = await authApi.resetPassword({
                email,
                otp: otpString,
                newPassword,
            });
            setSuccess(data.message || 'Đặt lại mật khẩu thành công!');

            // Chuyen ve login sau 2 giay
            setTimeout(() => {
                navigate('/login', { replace: true });
            }, 2000);
        } catch (err) {
            const msg = err.response?.data?.message || 'Không thể đặt lại mật khẩu. Vui lòng thử lại!';
            setError(msg);
            setDigits(Array(OTP_LENGTH).fill(''));
            focusInput(0);
        } finally {
            setLoading(false);
        }
    };

    /* ---------- Resend OTP ---------- */
    const handleResend = async () => {
        if (resendCooldown > 0 || resendLoading) return;

        setResendLoading(true);
        setError('');
        setSuccess('');

        try {
            const data = await authApi.resendForgotOtp({ email });
            setSuccess(data.message || 'Đã gửi lại mã OTP!');
            setResendCooldown(RESEND_COOLDOWN);
            setDigits(Array(OTP_LENGTH).fill(''));
            focusInput(0);
        } catch (err) {
            const msg = err.response?.data?.message || 'Không thể gửi lại OTP. Vui lòng thử lại!';
            setError(msg);
        } finally {
            setResendLoading(false);
        }
    };

    /* ---------- Masked email ---------- */
    const maskedEmail = email
        ? email.replace(/(.{2})(.*)(@.*)/, (_, a, b, c) => a + '•'.repeat(Math.min(b.length, 6)) + c)
        : '';

    /* ---------- Animation variants ---------- */
    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: { staggerChildren: 0.08, delayChildren: 0.15 },
        },
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: { duration: 0.6, ease: [0.22, 1, 0.36, 1] },
        },
    };

    /* ---------- Render ---------- */
    return (
        <div className="min-h-screen w-full flex items-center justify-center bg-base-100 font-sans selection:bg-blue-500/30 overflow-hidden relative px-4">

            {/* ---- Animated Background Orbs ---- */}
            <motion.div
                animate={{
                    scale: [1, 1.2, 1],
                    x: [0, 30, 0],
                    y: [0, -20, 0],
                }}
                transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
                className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-blue-500/10 rounded-full blur-[120px] pointer-events-none"
            />
            <motion.div
                animate={{
                    scale: [1.2, 1, 1.2],
                    x: [0, -30, 0],
                    y: [0, 20, 0],
                }}
                transition={{ duration: 12, repeat: Infinity, ease: "easeInOut", delay: 1 }}
                className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-violet-500/10 rounded-full blur-[120px] pointer-events-none"
            />

            {/* ---- Main Card ---- */}
            <motion.div
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                className="w-full max-w-lg bg-base-100/70 backdrop-blur-xl rounded-[2.5rem] shadow-2xl p-10 sm:p-12 border border-base-200 relative overflow-hidden z-10"
            >
                {/* Accent bar */}
                <div className="absolute top-0 left-0 right-0 h-1.5 bg-gradient-to-r from-blue-600 via-violet-600 to-purple-600" />

                {/* Back link */}
                <motion.div variants={itemVariants}>
                    <Link
                        to="/forgot-password"
                        className="inline-flex items-center gap-2 text-sm font-bold text-base-content/50 hover:text-blue-600 transition-colors mb-8 group"
                    >
                        <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                        Quay lại
                    </Link>
                </motion.div>

                {/* Header */}
                <motion.div variants={itemVariants} className="text-center mb-8">
                    {/* Icon */}
                    <motion.div
                        initial={{ scale: 0 }}
                        animate={{ scale: 1 }}
                        transition={{ type: 'spring', stiffness: 200, damping: 15, delay: 0.2 }}
                        className="mx-auto w-20 h-20 bg-gradient-to-br from-blue-500/10 to-violet-500/10 rounded-3xl flex items-center justify-center mb-6 border border-blue-500/20"
                    >
                        <motion.div
                            animate={{ rotate: [0, 5, -5, 0] }}
                            transition={{ duration: 4, repeat: Infinity, ease: 'easeInOut' }}
                        >
                            <Lock className="w-10 h-10 text-blue-600" strokeWidth={1.5} />
                        </motion.div>
                    </motion.div>

                    <h1 className="text-3xl font-black text-base-content mb-3 tracking-tight">
                        Đặt lại mật khẩu
                    </h1>
                    <p className="text-base-content/60 font-medium text-sm leading-relaxed max-w-sm mx-auto">
                        Nhập mã OTP được gửi đến{' '}
                        <span className="text-blue-600 font-bold">{maskedEmail}</span>
                    </p>
                </motion.div>

                {/* Status messages */}
                {error && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="flex items-center gap-3 p-4 rounded-xl bg-red-500/10 border border-red-500/20 text-red-600 text-sm font-medium mb-6"
                    >
                        <AlertCircle className="w-5 h-5 shrink-0" />
                        {error}
                    </motion.div>
                )}

                {success && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="flex items-center gap-3 p-4 rounded-xl bg-green-500/10 border border-green-500/20 text-green-600 text-sm font-medium mb-6"
                    >
                        <CheckCircle2 className="w-5 h-5 shrink-0" />
                        {success}
                    </motion.div>
                )}

                {/* Form */}
                <form onSubmit={handleSubmit}>
                    {/* OTP Input */}
                    <motion.div variants={itemVariants} className="mb-6">
                        <label className="block text-xs font-bold text-base-content/60 uppercase tracking-wider mb-3 text-center">
                            Mã xác nhận OTP
                        </label>
                        <div className="flex items-center justify-center gap-2 sm:gap-3">
                            {digits.map((digit, i) => (
                                <OtpDigitInput
                                    key={i}
                                    index={i}
                                    value={digit}
                                    onChange={handleChange}
                                    onKeyDown={handleKeyDown}
                                    onPaste={handlePaste}
                                    inputRef={(el) => (inputRefs.current[i] = el)}
                                    disabled={loading || success}
                                />
                            ))}
                        </div>
                    </motion.div>

                    {/* Password Input */}
                    <motion.div variants={itemVariants} className="mb-4">
                        <label className="block text-xs font-bold text-base-content/60 uppercase tracking-wider mb-2">
                            Mật khẩu mới
                        </label>
                        <div className="relative">
                            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-base-content/40">
                                <Lock className="w-5 h-5" />
                            </div>
                            <input
                                type={showPassword ? 'text' : 'password'}
                                value={newPassword}
                                onChange={(e) => {
                                    setNewPassword(e.target.value);
                                    setError('');
                                }}
                                disabled={loading || success}
                                placeholder="Nhập mật khẩu mới"
                                className="w-full h-12 pl-12 pr-12 bg-base-100 border-2 border-base-300 rounded-xl focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all font-medium"
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute inset-y-0 right-0 pr-4 flex items-center text-base-content/40 hover:text-blue-600 transition-colors"
                            >
                                {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                            </button>
                        </div>
                    </motion.div>

                    {/* Confirm Password Input */}
                    <motion.div variants={itemVariants} className="mb-6">
                        <label className="block text-xs font-bold text-base-content/60 uppercase tracking-wider mb-2">
                            Xác nhận mật khẩu
                        </label>
                        <div className="relative">
                            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-base-content/40">
                                <Lock className="w-5 h-5" />
                            </div>
                            <input
                                type={showConfirmPassword ? 'text' : 'password'}
                                value={confirmPassword}
                                onChange={(e) => {
                                    setConfirmPassword(e.target.value);
                                    setError('');
                                }}
                                disabled={loading || success}
                                placeholder="Nhập lại mật khẩu mới"
                                className="w-full h-12 pl-12 pr-12 bg-base-100 border-2 border-base-300 rounded-xl focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all font-medium"
                            />
                            <button
                                type="button"
                                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                className="absolute inset-y-0 right-0 pr-4 flex items-center text-base-content/40 hover:text-blue-600 transition-colors"
                            >
                                {showConfirmPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                            </button>
                        </div>
                    </motion.div>

                    {/* Submit button */}
                    <motion.div variants={itemVariants}>
                        <motion.button
                            type="submit"
                            disabled={!isFormValid || loading || success}
                            whileHover={isFormValid && !loading && !success ? { scale: 1.02, y: -2 } : {}}
                            whileTap={isFormValid && !loading && !success ? { scale: 0.98 } : {}}
                            className={`
                                btn w-full rounded-xl shadow-xl border-none text-base h-12 font-bold
                                group transition-all duration-300
                                ${isFormValid && !success
                                    ? 'bg-gradient-to-r from-blue-600 to-violet-600 hover:from-blue-700 hover:to-violet-700 text-white shadow-blue-600/20'
                                    : success
                                        ? 'bg-green-500 text-white'
                                        : 'bg-base-300 text-base-content/40 cursor-not-allowed'
                                }
                            `}
                        >
                            {loading ? (
                                <>
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                    Đang xử lý...
                                </>
                            ) : success ? (
                                <>
                                    <CheckCircle2 className="w-5 h-5" />
                                    Thành công!
                                </>
                            ) : (
                                <>
                                    <ShieldCheck className="w-5 h-5" />
                                    Đặt lại mật khẩu
                                    <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                                </>
                            )}
                        </motion.button>
                    </motion.div>
                </form>

                {/* Resend section */}
                <motion.div variants={itemVariants} className="mt-8 text-center">
                    <div className="flex items-center justify-center gap-2 text-sm text-base-content/60 font-medium">
                        {resendCooldown > 0 ? (
                            <p>
                                Gửi lại mã sau <ResendTimer seconds={resendCooldown} />
                            </p>
                        ) : (
                            <p>Chưa nhận được mã?</p>
                        )}
                    </div>

                    {resendCooldown <= 0 && (
                        <motion.button
                            initial={{ opacity: 0, y: 5 }}
                            animate={{ opacity: 1, y: 0 }}
                            onClick={handleResend}
                            disabled={resendLoading || success}
                            className="mt-3 inline-flex items-center gap-2 text-sm font-bold text-blue-600 hover:text-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            {resendLoading ? (
                                <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                                <RefreshCw className="w-4 h-4" />
                            )}
                            Gửi lại mã OTP
                        </motion.button>
                    )}
                </motion.div>

                {/* Footer */}
                <motion.div variants={itemVariants} className="mt-10 pt-6 border-t border-base-200">
                    <div className="flex items-center justify-center gap-3 text-base-content/40">
                        <div className="w-8 h-8 bg-gradient-to-br from-blue-600 to-violet-600 rounded-lg flex items-center justify-center">
                            <GraduationCap className="w-4 h-4 text-white" strokeWidth={2.5} />
                        </div>
                        <span className="text-sm font-bold tracking-tight">
                            SKR<span className="text-blue-600">.</span>
                        </span>
                    </div>
                </motion.div>
            </motion.div>
        </div>
    );
}

import React, { useState } from 'react';
import * as motion from 'motion/react-client';
import { Link, useNavigate } from 'react-router-dom';
import {
    Mail,
    UserPen,
    Lock,
    RotateCcw,
    Brain,
    Eye,
    EyeOff,
    Sparkles,
    HelpCircle,
    Database,
    Share2,
    ArrowRight,
    GraduationCap,
    CheckCircle2,
    AlertCircle,
    Loader2
} from 'lucide-react';
import { authApi } from '../api';

/* ================== Small Components ================== */

const FeatureCard = ({ icon: Icon, title, description, index }) => (
    <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: index * 0.1 }}
        whileHover={{ y: -5, scale: 1.02 }}
        className="bg-base-100/50 backdrop-blur-md p-5 rounded-2xl shadow-sm border border-base-200 flex flex-col gap-3 group transition-all hover:shadow-xl hover:border-blue-500/30"
    >
        <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-blue-500/10 to-violet-500/10 flex items-center justify-center text-blue-600 group-hover:scale-110 transition-transform">
            <Icon className="w-6 h-6" />
        </div>
        <div>
            <h3 className="font-bold text-base-content text-sm mb-1">{title}</h3>
            <p className="text-base-content/60 text-xs leading-relaxed font-medium">{description}</p>
        </div>
    </motion.div>
);

const InputField = ({
    label,
    type = 'text',
    placeholder,
    icon: Icon,
    isPassword = false,
    value,
    onChange,
    name,
}) => {
    const [showPassword, setShowPassword] = useState(false);
    const [isFocused, setIsFocused] = useState(false);
    const inputType = isPassword ? (showPassword ? 'text' : 'password') : type;

    return (
        <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5 }}
            className="form-control w-full"
        >
            <label className="label py-1">
                <span className="label-text font-bold text-base-content/70 text-xs uppercase tracking-widest">{label}</span>
            </label>

            <div className="relative group">
                <motion.div
                    animate={isFocused ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0.95 }}
                    className="absolute -inset-0.5 bg-gradient-to-r from-blue-600 to-violet-600 rounded-xl blur opacity-30 group-hover:opacity-50 transition duration-300"
                />
                <div className="relative">
                    <div className={`absolute inset-y-0 left-0 pl-4 flex items-center transition-colors duration-300 pointer-events-none ${isFocused ? 'text-blue-600' : 'text-base-content/30'}`}>
                        <Icon className="w-5 h-5" />
                    </div>

                    <input
                        type={inputType}
                        name={name}
                        value={value}
                        onChange={onChange}
                        placeholder={placeholder}
                        onFocus={() => setIsFocused(true)}
                        onBlur={() => setIsFocused(false)}
                        className="input w-full pl-12 bg-base-100 border-base-300 focus:border-blue-500 focus:outline-none transition-all rounded-xl font-medium h-12 text-sm"
                    />

                    {isPassword && (
                        <button
                            type="button"
                            onClick={() => setShowPassword(!showPassword)}
                            className="absolute inset-y-0 right-0 pr-4 flex items-center text-base-content/30 hover:text-blue-600 transition-colors"
                        >
                            {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                        </button>
                    )}
                </div>
            </div>
        </motion.div>
    );
};

/* ================== Main Component ================== */

export default function SignUp() {
    const navigate = useNavigate();
    const [formData, setFormData] = useState({
        username: '',
        email: '',
        password: '',
        confirmPassword: '',
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        setError('');
    };

    const handleSignUp = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        setSuccess('');

        // Kiem tra mat khau khop
        if (formData.password !== formData.confirmPassword) {
            setError('Mật khẩu xác nhận không khớp!');
            setLoading(false);
            return;
        }

        try {
            const data = await authApi.register({
                username: formData.username,
                email: formData.email,
                password: formData.password,
            });

            setSuccess(data.message || 'Đăng ký thành công! Đang chuyển đến xác minh email...');

            // Chuyen den trang xac minh OTP sau 1.5 giay
            setTimeout(() => {
                navigate(`/verify-email?email=${encodeURIComponent(formData.email)}`);
            }, 1500);
        } catch (err) {
            const msg = err.response?.data?.message || 'Đăng ký thất bại. Vui lòng thử lại!';
            setError(msg);
        } finally {
            setLoading(false);
        }
    };

    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: {
                staggerChildren: 0.1,
                delayChildren: 0.2
            }
        }
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: { duration: 0.6, ease: [0.22, 1, 0.36, 1] }
        }
    };

    return (
        <div className="min-h-screen w-full flex bg-base-100 font-sans selection:bg-blue-500/30 overflow-hidden relative">

            {/* Animated Background Orbs */}
            <motion.div
                animate={{
                    scale: [1, 1.2, 1],
                    x: [0, 30, 0],
                    y: [0, -20, 0],
                }}
                transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
                className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-blue-500/10 rounded-full blur-[120px] pointer-events-none"
            />
            <motion.div
                animate={{
                    scale: [1.2, 1, 1.2],
                    x: [0, -30, 0],
                    y: [0, 20, 0],
                }}
                transition={{ duration: 12, repeat: Infinity, ease: "easeInOut", delay: 1 }}
                className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-violet-500/10 rounded-full blur-[120px] pointer-events-none"
            />

            {/* LEFT SIDE - Brand Content */}
            <div className="hidden lg:flex lg:w-1/2 p-16 flex-col justify-between relative z-10 border-r border-base-200">
                <motion.div
                    initial={{ opacity: 0, x: -50 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ duration: 0.8 }}
                    className="space-y-12 max-w-lg"
                >
                    {/* Brand Logo */}
                    <Link to="/" className="flex items-center gap-3 group">
                        <motion.div
                            whileHover={{ rotate: 360 }}
                            transition={{ duration: 0.6 }}
                            className="w-12 h-12 bg-gradient-to-br from-blue-600 to-violet-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-600/20"
                        >
                            <GraduationCap className="w-7 h-7 text-white" strokeWidth={2.5} />
                        </motion.div>
                        <span className="text-3xl font-black text-base-content tracking-tighter">
                            SKR<span className="text-blue-600">.</span>
                        </span>
                    </Link>

                    <div className="space-y-6">
                        <h1 className="text-5xl font-black leading-tight tracking-tight text-base-content">
                            Tham gia cộng đồng <br />
                            <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 via-violet-600 to-purple-600 italic">
                                Học tập Thông minh
                            </span>
                        </h1>
                        <p className="text-base-content/60 text-lg font-medium leading-relaxed">
                            Kiến tạo tương lai với hệ thống ôn thi cá nhân hóa bằng sức mạnh của trí tuệ nhân tạo.
                        </p>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        {[
                            { icon: Sparkles, title: "AI Thông minh", desc: "Tự động tạo câu hỏi từ tài liệu." },
                            { icon: HelpCircle, title: "Luyện tập đa dạng", desc: "Nhiều hình thức câu hỏi phong phú." },
                            { icon: Database, title: "Kho lưu trữ", desc: "Quản lý ngân hàng câu hỏi tập trung." },
                            { icon: Share2, title: "Cộng đồng", desc: "Học tập & chia sẻ tri thức." }
                        ].map((feat, i) => (
                            <FeatureCard key={i} index={i} icon={feat.icon} title={feat.title} description={feat.desc} />
                        ))}
                    </div>

                    {/* Footer for Left Side */}
                    <div className="flex items-center gap-4 pt-4 border-t border-base-200">
                        <div className="flex -space-x-3">
                            {[1, 2, 3, 4].map((i) => (
                                <div key={i} className="w-10 h-10 rounded-full border-2 border-base-100 overflow-hidden bg-base-200">
                                    <img src={`https://i.pravatar.cc/150?u=${i + 10}`} alt="user" />
                                </div>
                            ))}
                        </div>
                        <div className="text-sm">
                            <span className="font-bold text-base-content">10,000+</span>
                            <span className="text-base-content/50 ml-1 font-medium">người học đang tham gia</span>
                        </div>
                    </div>
                </motion.div>
            </div>

            {/* RIGHT SIDE - Auth Form */}
            <div className="w-full lg:w-1/2 flex items-center justify-center p-6 relative z-10 overflow-y-auto no-scrollbar py-12">
                <motion.div
                    variants={containerVariants}
                    initial="hidden"
                    animate="visible"
                    className="w-full max-w-md bg-base-100/70 backdrop-blur-xl rounded-[2.5rem] shadow-2xl p-10 border border-base-200 relative overflow-hidden"
                >
                    {/* Accent bar */}
                    <div className="absolute top-0 left-0 right-0 h-1.5 bg-gradient-to-r from-blue-600 via-violet-600 to-purple-600" />

                    <div className="text-center mb-10">
                        <motion.h2 variants={itemVariants} className="text-3xl font-black text-base-content mb-3 tracking-tight">
                            Tạo tài khoản mới
                        </motion.h2>
                        <motion.p variants={itemVariants} className="text-base-content/60 font-medium">
                            Bắt đầu trải nghiệm học tập AI ngay hôm nay
                        </motion.p>
                    </div>

                    <form className="space-y-5" onSubmit={handleSignUp}>
                        {/* Error message */}
                        {error && (
                            <motion.div
                                initial={{ opacity: 0, y: -10 }}
                                animate={{ opacity: 1, y: 0 }}
                                className="flex items-center gap-3 p-4 rounded-xl bg-red-500/10 border border-red-500/20 text-red-600 text-sm font-medium"
                            >
                                <AlertCircle className="w-5 h-5 shrink-0" />
                                {error}
                            </motion.div>
                        )}

                        {/* Success message */}
                        {success && (
                            <motion.div
                                initial={{ opacity: 0, y: -10 }}
                                animate={{ opacity: 1, y: 0 }}
                                className="flex items-center gap-3 p-4 rounded-xl bg-green-500/10 border border-green-500/20 text-green-600 text-sm font-medium"
                            >
                                <CheckCircle2 className="w-5 h-5 shrink-0" />
                                {success}
                            </motion.div>
                        )}

                        <motion.div variants={itemVariants}>
                            <InputField
                                label="Tên đăng nhập"
                                name="username"
                                value={formData.username}
                                onChange={handleChange}
                                placeholder="username123"
                                icon={UserPen}
                            />
                        </motion.div>

                        <motion.div variants={itemVariants}>
                            <InputField
                                label="Địa chỉ Email"
                                type="email"
                                name="email"
                                value={formData.email}
                                onChange={handleChange}
                                placeholder="name@example.com"
                                icon={Mail}
                            />
                        </motion.div>

                        <motion.div variants={itemVariants}>
                            <InputField
                                label="Mật khẩu"
                                placeholder="••••••••"
                                icon={Lock}
                                isPassword
                                name="password"
                                value={formData.password}
                                onChange={handleChange}
                            />
                        </motion.div>

                        <motion.div variants={itemVariants}>
                            <InputField
                                label="Xác nhận mật khẩu"
                                placeholder="••••••••"
                                icon={RotateCcw}
                                isPassword
                                name="confirmPassword"
                                value={formData.confirmPassword}
                                onChange={handleChange}
                            />
                        </motion.div>

                        <motion.div variants={itemVariants}>
                            <label className="flex items-center gap-3 group cursor-pointer">
                                <input type="checkbox" className="checkbox checkbox-sm checkbox-primary rounded-lg transition-all" />
                                <span className="text-xs text-base-content/60 font-medium group-hover:text-base-content transition-colors">
                                    Tôi đồng ý với <a href="#" className="text-blue-600 font-bold hover:underline">Điều khoản</a> và <a href="#" className="text-blue-600 font-bold hover:underline">Chính sách bảo mật</a>
                                </span>
                            </label>
                        </motion.div>

                        <motion.button
                            variants={itemVariants}
                            whileHover={{ scale: 1.02, y: -2 }}
                            whileTap={{ scale: 0.98 }}
                            type="submit"
                            disabled={loading}
                            className="btn w-full bg-gradient-to-r from-blue-600 to-violet-600 hover:from-blue-700 hover:to-violet-700 text-white rounded-xl shadow-xl shadow-blue-600/20 border-none text-base h-12 font-bold group transition-all duration-300 mt-2 disabled:opacity-60"
                        >
                            {loading ? (
                                <>
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                    Đang xử lý...
                                </>
                            ) : (
                                <>
                                    Đăng ký miễn phí
                                    <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                                </>
                            )}
                        </motion.button>

                        <motion.div variants={itemVariants} className="relative py-2">
                            <div className="absolute inset-0 flex items-center">
                                <div className="w-full border-t border-base-200"></div>
                            </div>
                            <div className="relative flex justify-center text-xs uppercase">
                                <span className="bg-base-100 px-4 text-base-content/40 font-bold tracking-widest">Hoặc đăng ký với</span>
                            </div>
                        </motion.div>

                        <motion.div variants={itemVariants} className="grid grid-cols-1 gap-4">
                            <motion.button
                                type="button"
                                whileHover={{ scale: 1.02, y: -1 }}
                                whileTap={{ scale: 0.98 }}
                                onClick={() => {
                                    window.location.href = `${import.meta.env.VITE_API_BASE_URL}/auth/google`;
                                }}
                                className="btn w-full btn-ghost border-base-300 hover:bg-base-200 text-base-content rounded-xl font-bold flex items-center justify-center gap-3 transition-all h-12"
                            >
                                <img src="https://www.svgrepo.com/show/475656/google-color.svg" className="w-5 h-5" alt="Google" />
                                <span className="text-sm">Tiếp tục với Google</span>
                            </motion.button>
                        </motion.div>
                    </form>

                    <motion.p variants={itemVariants} className="text-center mt-10 text-sm text-base-content/60 font-medium">
                        Đã có tài khoản?{' '}
                        <Link to="/login" className="text-blue-600 font-black hover:text-blue-700 transition-colors underline-offset-4 hover:underline">
                            Đăng nhập ngay
                        </Link>
                    </motion.p>
                </motion.div>
            </div>
        </div>
    );
}

import { useParams, useNavigate, Link } from 'react-router-dom';
import { useState } from 'react';
import * as motion from 'motion/react-client';
import { DashboardSidebar } from '../components/learner';
import Icon from '../components/icons/Icon';
import { CircularProgress } from '../components/common/ProgressBar';
import {
    MOCK_PRACTICE_TESTS,
    DIFFICULTY_CONFIG,
    SUBJECT_CONFIG,
    QUESTION_TYPE_CONFIG,
    formatDuration,
    formatRelativeTime,
    getScoreColor,
    getScoreGrade,
} from '../components/tests';

/**
 * TestDetail Page — Xem chi tiết bài thi trước khi bắt đầu
 * Route: /tests/:id
 *
 * Sections:
 * 1. Breadcrumb + Back button
 * 2. Hero section (title, subject, difficulty, description)
 * 3. Test configuration overview
 * 4. Best score & performance stats
 * 5. Past attempts history
 * 6. Start test CTA
 */
export default function TestDetail() {
    const { id } = useParams();
    const navigate = useNavigate();
    const [showConfirm, setShowConfirm] = useState(false);

    const test = MOCK_PRACTICE_TESTS.find(t => t.id === id);

    if (!test) {
        return (
            <div className="flex h-screen bg-base-200 overflow-hidden">
                <DashboardSidebar />
                <div className="flex-1 flex items-center justify-center">
                    <div className="text-center">
                        <div className="w-20 h-20 mx-auto bg-base-300/50 rounded-3xl flex items-center justify-center mb-4">
                            <Icon name="FileX" size="3xl" className="text-base-content/30" />
                        </div>
                        <h2 className="text-xl font-black text-base-content mb-2">Không tìm thấy bài thi</h2>
                        <p className="text-sm text-base-content/60 mb-6">Bài thi này không tồn tại hoặc đã bị xoá</p>
                        <Link to="/tests" className="btn bg-gradient-to-r from-blue-600 to-violet-600 text-white border-none rounded-xl font-bold">
                            <Icon name="ArrowLeft" size="sm" />
                            Quay lại danh sách
                        </Link>
                    </div>
                </div>
            </div>
        );
    }

    const subject = SUBJECT_CONFIG[test.subjectKey] || {};
    const difficulty = DIFFICULTY_CONFIG[test.difficulty] || {};
    const hasAttempts = test.attemptsCount > 0;
    const grade = getScoreGrade(test.bestScore);

    // Mock attempt history
    const mockAttempts = hasAttempts ? [
        { id: 1, date: '2026-02-18T10:30:00Z', score: test.bestScore, time: Math.floor(test.timeLimitMinutes * 0.8 * 60), correct: Math.floor(test.totalQuestions * (test.bestScore / 100)), total: test.totalQuestions },
        ...(test.attemptsCount > 1 ? [{ id: 2, date: '2026-02-16T14:00:00Z', score: test.averageScore, time: Math.floor(test.timeLimitMinutes * 0.9 * 60), correct: Math.floor(test.totalQuestions * (test.averageScore / 100)), total: test.totalQuestions }] : []),
        ...(test.attemptsCount > 2 ? [{ id: 3, date: '2026-02-14T09:15:00Z', score: Math.max(40, test.averageScore - 10), time: Math.floor(test.timeLimitMinutes * 60), correct: Math.floor(test.totalQuestions * ((test.averageScore - 10) / 100)), total: test.totalQuestions }] : []),
    ] : [];

    const handleStartTest = () => {
        navigate(`/tests/${id}/take`);
    };

    return (
        <div className="flex h-screen bg-base-200 overflow-hidden">
            <DashboardSidebar />
            <div className="flex-1 flex flex-col overflow-hidden">
                {/* Header */}
                <motion.header
                    initial={{ y: -100 }}
                    animate={{ y: 0 }}
                    transition={{ duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] }}
                    className="bg-base-100 border-b border-base-300 px-8 py-4"
                >
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
                            <Link
                                to="/tests"
                                className="btn btn-circle btn-ghost btn-sm"
                            >
                                <Icon name="ArrowLeft" size="md" />
                            </Link>
                            <div>
                                <div className="flex items-center gap-2 mb-0.5">
                                    <Link to="/tests" className="text-xs text-base-content/40 hover:text-blue-500 font-bold transition-colors">
                                        Thi Thử
                                    </Link>
                                    <Icon name="ChevronRight" size="xs" className="text-base-content/30" />
                                    <span className="text-xs text-base-content/60 font-bold">{test.title}</span>
                                </div>
                                <h2 className="text-xl font-black text-base-content">{test.title}</h2>
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            <button className="btn btn-ghost btn-sm rounded-xl gap-2 font-bold">
                                <Icon name="Share2" size="sm" />
                                Chia sẻ
                            </button>
                            <button className="btn btn-ghost btn-sm rounded-xl gap-2 font-bold">
                                <Icon name="Settings" size="sm" />
                                Chỉnh sửa
                            </button>
                        </div>
                    </div>
                </motion.header>

                {/* Main Content */}
                <main className="flex-1 overflow-y-auto">
                    <div className="max-w-5xl mx-auto p-6 lg:p-8">
                        {/* ─── Hero Section ─── */}
                        <motion.div
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ duration: 0.5 }}
                            className="bg-base-100 rounded-3xl shadow-xl border border-base-300 overflow-hidden mb-6"
                        >
                            {/* Gradient Banner */}
                            <div className={`h-32 bg-gradient-to-r ${subject.gradient || 'from-blue-500 to-violet-500'} relative overflow-hidden`}>
                                {/* Decorative Patterns */}
                                <div className="absolute inset-0 opacity-10">
                                    <div className="absolute top-4 left-8 w-20 h-20 border-4 border-white rounded-full" />
                                    <div className="absolute bottom-2 right-12 w-32 h-32 border-4 border-white rounded-full" />
                                    <div className="absolute top-8 right-40 w-12 h-12 border-4 border-white rounded-lg rotate-45" />
                                </div>
                                <div className="absolute bottom-4 left-8 text-5xl opacity-30">{subject.icon}</div>
                            </div>

                            <div className="p-6 -mt-8 relative z-10">
                                {/* Subject & Difficulty Badge Row */}
                                <div className="flex items-center gap-2 mb-3 ml-1">
                                    <span className="badge badge-lg bg-base-100 shadow-md font-bold gap-1 text-sm">
                                        {subject.icon} {subject.label}
                                    </span>
                                    <span className={`badge badge-lg font-bold ${difficulty.badge}`}>
                                        {difficulty.label}
                                    </span>
                                    {test.status === 'draft' && (
                                        <span className="badge badge-lg badge-ghost font-bold gap-1">
                                            <Icon name="FileEdit" size="xs" /> Nháp
                                        </span>
                                    )}
                                </div>

                                {/* Title & Description */}
                                <h1 className="text-2xl font-black text-base-content mb-2">{test.title}</h1>
                                <p className="text-sm text-base-content/60 leading-relaxed mb-6">{test.description}</p>

                                {/* Quick Info Chips */}
                                <div className="flex flex-wrap gap-2">
                                    {test.questionTypes.map(type => {
                                        const qt = QUESTION_TYPE_CONFIG[type];
                                        return qt ? (
                                            <span key={type} className="badge badge-lg badge-ghost gap-1 font-bold text-xs">
                                                <Icon name={qt.icon} size="xs" className={qt.color} />
                                                {qt.label}
                                            </span>
                                        ) : null;
                                    })}
                                </div>
                            </div>
                        </motion.div>

                        {/* ─── Two Column Layout ─── */}
                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                            {/* Left Column: Config + History */}
                            <div className="lg:col-span-2 space-y-6">
                                {/* Test Configuration */}
                                <motion.div
                                    initial={{ opacity: 0, y: 20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: 0.1 }}
                                    className="bg-base-100 rounded-2xl shadow-lg border border-base-300 p-6"
                                >
                                    <h3 className="font-black text-base text-base-content mb-4 flex items-center gap-2">
                                        <Icon name="Settings2" size="md" className="text-blue-500" />
                                        Cấu hình bài thi
                                    </h3>

                                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                                        <div className="bg-blue-500/5 rounded-xl p-4 text-center border border-blue-500/10">
                                            <Icon name="HelpCircle" size="lg" className="text-blue-500 mx-auto mb-2" />
                                            <p className="text-xl font-black text-base-content">{test.totalQuestions}</p>
                                            <p className="text-xs text-base-content/50 font-bold uppercase">Câu hỏi</p>
                                        </div>
                                        <div className="bg-violet-500/5 rounded-xl p-4 text-center border border-violet-500/10">
                                            <Icon name="Clock" size="lg" className="text-violet-500 mx-auto mb-2" />
                                            <p className="text-xl font-black text-base-content">{formatDuration(test.timeLimitMinutes)}</p>
                                            <p className="text-xs text-base-content/50 font-bold uppercase">Thời gian</p>
                                        </div>
                                        <div className={`${difficulty.bg} rounded-xl p-4 text-center border border-current/10`}>
                                            <Icon name="Signal" size="lg" className={`${difficulty.color} mx-auto mb-2`} />
                                            <p className={`text-xl font-black ${difficulty.color}`}>{difficulty.label}</p>
                                            <p className="text-xs text-base-content/50 font-bold uppercase">Độ khó</p>
                                        </div>
                                        <div className="bg-green-500/5 rounded-xl p-4 text-center border border-green-500/10">
                                            <Icon name="PlayCircle" size="lg" className="text-green-500 mx-auto mb-2" />
                                            <p className="text-xl font-black text-base-content">{test.attemptsCount}</p>
                                            <p className="text-xs text-base-content/50 font-bold uppercase">Lượt thi</p>
                                        </div>
                                    </div>

                                    {/* Options */}
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                                        {[
                                            { icon: 'Shuffle', label: 'Trộn câu hỏi', active: test.randomizeQuestions },
                                            { icon: 'ArrowLeftRight', label: 'Trộn đáp án', active: test.randomizeOptions },
                                            { icon: 'Eye', label: 'Hiển thị đáp án', active: test.showCorrectAnswers },
                                        ].map(opt => (
                                            <div key={opt.label} className={`flex items-center gap-3 p-3 rounded-xl ${opt.active ? 'bg-green-500/5 border border-green-500/20' : 'bg-base-200/50 border border-base-300'}`}>
                                                <Icon name={opt.icon} size="sm" className={opt.active ? 'text-green-500' : 'text-base-content/40'} />
                                                <span className="text-xs font-bold text-base-content/70">{opt.label}</span>
                                                <span className={`ml-auto text-xs font-black ${opt.active ? 'text-green-500' : 'text-base-content/30'}`}>
                                                    {opt.active ? 'BẬT' : 'TẮT'}
                                                </span>
                                            </div>
                                        ))}
                                    </div>
                                </motion.div>

                                {/* Attempt History */}
                                <motion.div
                                    initial={{ opacity: 0, y: 20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: 0.2 }}
                                    className="bg-base-100 rounded-2xl shadow-lg border border-base-300 p-6"
                                >
                                    <h3 className="font-black text-base text-base-content mb-4 flex items-center gap-2">
                                        <Icon name="History" size="md" className="text-orange-500" />
                                        Lịch sử thi
                                        {hasAttempts && (
                                            <span className="badge badge-sm badge-primary ml-2">{test.attemptsCount} lượt</span>
                                        )}
                                    </h3>

                                    {hasAttempts ? (
                                        <div className="space-y-3">
                                            {mockAttempts.map((attempt, idx) => {
                                                const attemptGrade = getScoreGrade(attempt.score);
                                                return (
                                                    <motion.div
                                                        key={attempt.id}
                                                        initial={{ opacity: 0, x: -10 }}
                                                        animate={{ opacity: 1, x: 0 }}
                                                        transition={{ delay: 0.3 + idx * 0.1 }}
                                                        className="flex items-center gap-4 p-4 bg-base-200/40 rounded-xl hover:bg-base-200/70 transition-colors group"
                                                    >
                                                        {/* Rank Icon */}
                                                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-sm ${idx === 0
                                                                ? 'bg-gradient-to-br from-yellow-400 to-amber-500 text-white shadow-lg'
                                                                : 'bg-base-300 text-base-content/50'
                                                            }`}>
                                                            {idx === 0 ? '🏆' : `#${idx + 1}`}
                                                        </div>

                                                        {/* Info */}
                                                        <div className="flex-1 min-w-0">
                                                            <p className="text-sm font-bold text-base-content">
                                                                Lần thi {test.attemptsCount - idx}
                                                                {idx === 0 && <span className="text-xs text-yellow-500 ml-2 font-black">Tốt nhất</span>}
                                                            </p>
                                                            <p className="text-xs text-base-content/50">
                                                                {formatRelativeTime(attempt.date)} · {Math.floor(attempt.time / 60)}p {attempt.time % 60}s
                                                            </p>
                                                        </div>

                                                        {/* Correct / Total */}
                                                        <div className="text-right hidden sm:block">
                                                            <p className="text-xs font-bold text-base-content/50">
                                                                {attempt.correct}/{attempt.total} câu đúng
                                                            </p>
                                                        </div>

                                                        {/* Score */}
                                                        <div className="text-right">
                                                            <p className={`text-lg font-black ${getScoreColor(attempt.score)}`}>
                                                                {attempt.score.toFixed(1)}%
                                                            </p>
                                                            <p className={`text-[10px] font-bold ${attemptGrade.color}`}>
                                                                {attemptGrade.label}
                                                            </p>
                                                        </div>
                                                    </motion.div>
                                                );
                                            })}
                                        </div>
                                    ) : (
                                        <div className="text-center py-8">
                                            <div className="w-16 h-16 mx-auto bg-blue-500/5 rounded-2xl flex items-center justify-center mb-3">
                                                <Icon name="Sparkles" size="xl" className="text-blue-500" />
                                            </div>
                                            <p className="font-bold text-base-content/60 mb-1">Chưa có lượt thi nào</p>
                                            <p className="text-xs text-base-content/40">Hãy bắt đầu lần thi đầu tiên!</p>
                                        </div>
                                    )}
                                </motion.div>
                            </div>

                            {/* Right Column: Score + CTA */}
                            <div className="space-y-6">
                                {/* Performance Card */}
                                <motion.div
                                    initial={{ opacity: 0, y: 20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: 0.15 }}
                                    className="bg-base-100 rounded-2xl shadow-lg border border-base-300 p-6"
                                >
                                    <h3 className="font-black text-base text-base-content mb-4 flex items-center gap-2">
                                        <Icon name="BarChart3" size="md" className="text-green-500" />
                                        Kết quả
                                    </h3>

                                    {hasAttempts ? (
                                        <>
                                            {/* Score Circle */}
                                            <div className="flex justify-center mb-6">
                                                <div className="relative">
                                                    <svg width={140} height={140} className="-rotate-90">
                                                        <circle cx={70} cy={70} r={60} strokeWidth={10} fill="none" className="stroke-base-300" />
                                                        <motion.circle
                                                            cx={70} cy={70} r={60}
                                                            strokeWidth={10}
                                                            fill="none"
                                                            className={test.bestScore >= 80 ? 'stroke-green-500' : test.bestScore >= 50 ? 'stroke-blue-500' : 'stroke-red-500'}
                                                            strokeLinecap="round"
                                                            initial={{ strokeDashoffset: 377 }}
                                                            animate={{ strokeDashoffset: 377 - (377 * test.bestScore) / 100 }}
                                                            style={{ strokeDasharray: 377 }}
                                                            transition={{ duration: 1.5, ease: 'easeOut', delay: 0.5 }}
                                                        />
                                                    </svg>
                                                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                                                        <motion.span
                                                            initial={{ opacity: 0, scale: 0.5 }}
                                                            animate={{ opacity: 1, scale: 1 }}
                                                            transition={{ delay: 0.8 }}
                                                            className={`text-2xl font-black ${getScoreColor(test.bestScore)}`}
                                                        >
                                                            {test.bestScore}%
                                                        </motion.span>
                                                        <span className={`text-xs font-bold ${grade.color}`}>{grade.label}</span>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Stats */}
                                            <div className="space-y-3">
                                                <div className="flex items-center justify-between p-3 bg-base-200/50 rounded-xl">
                                                    <span className="text-xs font-bold text-base-content/60 flex items-center gap-2">
                                                        <Icon name="Trophy" size="sm" className="text-yellow-500" /> Điểm cao nhất
                                                    </span>
                                                    <span className={`font-black ${getScoreColor(test.bestScore)}`}>{test.bestScore}%</span>
                                                </div>
                                                <div className="flex items-center justify-between p-3 bg-base-200/50 rounded-xl">
                                                    <span className="text-xs font-bold text-base-content/60 flex items-center gap-2">
                                                        <Icon name="TrendingUp" size="sm" className="text-blue-500" /> Điểm trung bình
                                                    </span>
                                                    <span className={`font-black ${getScoreColor(test.averageScore)}`}>{test.averageScore}%</span>
                                                </div>
                                                <div className="flex items-center justify-between p-3 bg-base-200/50 rounded-xl">
                                                    <span className="text-xs font-bold text-base-content/60 flex items-center gap-2">
                                                        <Icon name="PlayCircle" size="sm" className="text-green-500" /> Lượt thi
                                                    </span>
                                                    <span className="font-black text-base-content">{test.attemptsCount}</span>
                                                </div>
                                                <div className="flex items-center justify-between p-3 bg-base-200/50 rounded-xl">
                                                    <span className="text-xs font-bold text-base-content/60 flex items-center gap-2">
                                                        <Icon name="Calendar" size="sm" className="text-violet-500" /> Thi gần nhất
                                                    </span>
                                                    <span className="font-black text-base-content text-xs">{formatRelativeTime(test.lastAttemptAt)}</span>
                                                </div>
                                            </div>
                                        </>
                                    ) : (
                                        <div className="text-center py-6">
                                            <div className="w-16 h-16 mx-auto bg-base-200 rounded-full flex items-center justify-center mb-3">
                                                <Icon name="BarChart3" size="xl" className="text-base-content/20" />
                                            </div>
                                            <p className="text-sm font-bold text-base-content/50 mb-1">Chưa có dữ liệu</p>
                                            <p className="text-xs text-base-content/30">Hoàn thành bài thi để xem kết quả</p>
                                        </div>
                                    )}
                                </motion.div>

                                {/* CTA Card */}
                                <motion.div
                                    initial={{ opacity: 0, y: 20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: 0.25 }}
                                    className="bg-gradient-to-br from-blue-600 to-violet-600 rounded-2xl shadow-xl p-6 text-white"
                                >
                                    <div className="text-center mb-4">
                                        <div className="w-14 h-14 mx-auto bg-white/10 rounded-2xl flex items-center justify-center mb-3 backdrop-blur-sm">
                                            <Icon name="Rocket" size="xl" className="text-white" />
                                        </div>
                                        <h3 className="text-lg font-black mb-1">
                                            {hasAttempts ? 'Thi lại' : 'Bắt đầu thi'}
                                        </h3>
                                        <p className="text-xs text-white/70">
                                            {test.totalQuestions} câu · {formatDuration(test.timeLimitMinutes)}
                                        </p>
                                    </div>

                                    <motion.button
                                        whileHover={{ scale: 1.03 }}
                                        whileTap={{ scale: 0.97 }}
                                        onClick={() => setShowConfirm(true)}
                                        className="btn w-full bg-white hover:bg-white/90 text-blue-600 border-none rounded-xl font-black shadow-lg gap-2"
                                    >
                                        <Icon name="Play" size="md" />
                                        {hasAttempts ? 'Thi lại ngay' : 'Bắt đầu ngay'}
                                    </motion.button>

                                    {hasAttempts && (
                                        <p className="text-center text-[10px] text-white/50 mt-3 font-medium">
                                            Cải thiện điểm số để đạt kết quả tốt hơn! 💪
                                        </p>
                                    )}
                                </motion.div>

                                {/* Tips Card */}
                                <motion.div
                                    initial={{ opacity: 0, y: 20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: 0.3 }}
                                    className="bg-base-100 rounded-2xl shadow-lg border border-base-300 p-5"
                                >
                                    <h4 className="font-black text-sm text-base-content mb-3 flex items-center gap-2">
                                        <Icon name="Lightbulb" size="sm" className="text-yellow-500" />
                                        Lưu ý
                                    </h4>
                                    <ul className="space-y-2 text-xs text-base-content/60">
                                        <li className="flex items-start gap-2">
                                            <span className="w-1.5 h-1.5 rounded-full bg-blue-500 mt-1.5 shrink-0" />
                                            Bài thi sẽ tự động nộp khi hết thời gian
                                        </li>
                                        <li className="flex items-start gap-2">
                                            <span className="w-1.5 h-1.5 rounded-full bg-blue-500 mt-1.5 shrink-0" />
                                            Dùng phím ← → để di chuyển giữa các câu
                                        </li>
                                        <li className="flex items-start gap-2">
                                            <span className="w-1.5 h-1.5 rounded-full bg-blue-500 mt-1.5 shrink-0" />
                                            Đánh dấu câu chưa chắc để xem lại
                                        </li>
                                        <li className="flex items-start gap-2">
                                            <span className="w-1.5 h-1.5 rounded-full bg-blue-500 mt-1.5 shrink-0" />
                                            Kiểm tra kỹ trước khi nộp bài
                                        </li>
                                    </ul>
                                </motion.div>
                            </div>
                        </div>
                    </div>
                </main>
            </div>

            {/* Start Confirm Modal */}
            {showConfirm && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="fixed inset-0 z-50 flex items-center justify-center p-4"
                >
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={() => setShowConfirm(false)} />
                    <motion.div
                        initial={{ scale: 0.9, opacity: 0 }}
                        animate={{ scale: 1, opacity: 1 }}
                        transition={{ duration: 0.3 }}
                        className="bg-base-100 rounded-3xl shadow-2xl w-full max-w-md relative z-10 p-6"
                    >
                        <div className="text-center mb-6">
                            <div className="w-16 h-16 mx-auto bg-gradient-to-br from-blue-600 to-violet-600 rounded-2xl flex items-center justify-center mb-4">
                                <Icon name="Rocket" size="xl" className="text-white" />
                            </div>
                            <h3 className="text-xl font-black text-base-content mb-2">Sẵn sàng bắt đầu?</h3>
                            <p className="text-sm text-base-content/60">
                                Bạn sẽ có <strong>{formatDuration(test.timeLimitMinutes)}</strong> để hoàn thành <strong>{test.totalQuestions} câu hỏi</strong>.
