                            >
                                <Icon name="Play" size="sm" />
                                Bắt đầu
                            </motion.button>
                        </div>
                    </motion.div>
                </motion.div>
            )}
        </div>
    );
}

import { useState, useEffect } from 'react';
import * as motion from 'motion/react-client';
import { DashboardSidebar } from '../components/learner';
import { StatCard, ViewToggle, SectionHeader } from '../components/common';
import {
    TestCard,
    TestListItem,
    TestsHeader,
    CreateTestModal,
    MOCK_PRACTICE_TESTS,
    SUBJECT_CONFIG,
    DIFFICULTY_CONFIG,
} from '../components/tests';

/**
 * Tests Page — Danh sách bài thi thử
