import { useState, useEffect, useRef, useCallback } from 'react';
import * as motion from 'motion/react-client';
import { useNavigate, useSearchParams, Link } from 'react-router-dom';
import {
    Mail,
    ShieldCheck,
    ArrowRight,
    AlertCircle,
    CheckCircle2,
    Loader2,
    RefreshCw,
    GraduationCap,
    ArrowLeft,
} from 'lucide-react';
import { authApi } from '../api';

/* ================== Constants ================== */

const OTP_LENGTH = 6;
const RESEND_COOLDOWN = 60; // giay

/* ================== Sub-components ================== */

/**
 * Single OTP digit input box.
 * Handles focus management, paste, and backspace navigation.
 */
const OtpDigitInput = ({ index, value, onChange, onKeyDown, onPaste, inputRef, disabled }) => {
    const [isFocused, setIsFocused] = useState(false);
    const hasValue = value !== '';

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4, delay: 0.05 * index }}
            className="relative"
        >
            {/* Gradient glow khi focus */}
            <motion.div
                animate={isFocused ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0.9 }}
                transition={{ duration: 0.2 }}
                className="absolute -inset-1 bg-gradient-to-r from-blue-600 to-violet-600 rounded-2xl blur opacity-40"
            />

            <input
                ref={inputRef}
                type="text"
                inputMode="numeric"
                maxLength={1}
                value={value}
                disabled={disabled}
                onChange={(e) => onChange(index, e.target.value)}
                onKeyDown={(e) => onKeyDown(index, e)}
                onPaste={onPaste}
                onFocus={() => setIsFocused(true)}
                onBlur={() => setIsFocused(false)}
                aria-label={`Digit ${index + 1}`}
                className={`
                    relative w-14 h-16 sm:w-16 sm:h-[4.5rem] text-center text-2xl font-black
                    rounded-2xl border-2 outline-none transition-all duration-300
                    bg-base-100 caret-transparent select-none
                    disabled:opacity-50 disabled:cursor-not-allowed
                    ${isFocused
                        ? 'border-blue-500 shadow-lg shadow-blue-500/20'
                        : hasValue
                            ? 'border-blue-400/60 shadow-md shadow-blue-400/10'
                            : 'border-base-300 hover:border-base-content/20'
                    }
                    ${hasValue ? 'text-blue-600' : 'text-base-content'}
                `}
            />

            {/* Bottom dot indicator */}
            <motion.div
                animate={hasValue ? { scale: 1, opacity: 1 } : { scale: 0, opacity: 0 }}
                className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-1.5 h-1.5 rounded-full bg-gradient-to-r from-blue-600 to-violet-600"
            />
        </motion.div>
    );
};

/**
 * Countdown timer for OTP resend cooldown.
 */
const ResendTimer = ({ seconds }) => {
    const mins = String(Math.floor(seconds / 60)).padStart(2, '0');
    const secs = String(seconds % 60).padStart(2, '0');

    return (
        <span className="font-mono font-bold text-blue-600 tabular-nums">
            {mins}:{secs}
        </span>
    );
};

/* ================== Main Component ================== */

export default function VerifyEmail() {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const email = searchParams.get('email') || '';

    // OTP state
    const [digits, setDigits] = useState(Array(OTP_LENGTH).fill(''));
    const inputRefs = useRef([]);

    // UI state
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [resendCooldown, setResendCooldown] = useState(RESEND_COOLDOWN);
    const [resendLoading, setResendLoading] = useState(false);

    /* ---------- Redirect if no email ---------- */
    useEffect(() => {
        if (!email) {
            navigate('/signup', { replace: true });
        }
    }, [email, navigate]);

    /* ---------- Resend cooldown timer ---------- */
    useEffect(() => {
        if (resendCooldown <= 0) return;

        const timer = setInterval(() => {
            setResendCooldown((prev) => prev - 1);
        }, 1000);

        return () => clearInterval(timer);
    }, [resendCooldown]);

    /* ---------- OTP input handlers ---------- */

    const focusInput = useCallback((index) => {
        inputRefs.current[index]?.focus();
    }, []);

    const handleChange = useCallback((index, value) => {
        // Chi chap nhan so
        const digit = value.replace(/\D/g, '').slice(-1);
        setDigits((prev) => {
            const next = [...prev];
            next[index] = digit;
            return next;
        });
        setError('');

        // Auto-focus next input
        if (digit && index < OTP_LENGTH - 1) {
            focusInput(index + 1);
        }
    }, [focusInput]);

    const handleKeyDown = useCallback((index, e) => {
        if (e.key === 'Backspace') {
            if (!digits[index] && index > 0) {
                // Xoa va quay ve o truoc
                setDigits((prev) => {
                    const next = [...prev];
                    next[index - 1] = '';
                    return next;
                });
                focusInput(index - 1);
            } else {
                setDigits((prev) => {
                    const next = [...prev];
                    next[index] = '';
                    return next;
                });
            }
            e.preventDefault();
        } else if (e.key === 'ArrowLeft' && index > 0) {
            focusInput(index - 1);
        } else if (e.key === 'ArrowRight' && index < OTP_LENGTH - 1) {
            focusInput(index + 1);
        }
    }, [digits, focusInput]);

    const handlePaste = useCallback((e) => {
        e.preventDefault();
        const pasted = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, OTP_LENGTH);
        if (!pasted) return;

        const newDigits = Array(OTP_LENGTH).fill('');
        for (let i = 0; i < pasted.length; i++) {
            newDigits[i] = pasted[i];
        }
        setDigits(newDigits);
        setError('');

        // Focus last filled input hoac input ke tiep
        const focusIdx = Math.min(pasted.length, OTP_LENGTH - 1);
        focusInput(focusIdx);
    }, [focusInput]);

    /* ---------- Submit OTP ---------- */
    const otpString = digits.join('');
    const isComplete = otpString.length === OTP_LENGTH;

    const handleSubmit = async (e) => {
        e?.preventDefault();

        if (!isComplete) {
            setError('Vui lòng nhập đầy đủ mã OTP 6 chữ số.');
            return;
        }

        setLoading(true);
        setError('');
        setSuccess('');

        try {
            const data = await authApi.verifyEmail({ email, otp: otpString });
            setSuccess(data.message || 'Xác minh email thành công!');

            // Chuyen ve login sau 2 giay
            setTimeout(() => {
                navigate('/login', { replace: true });
            }, 2000);
        } catch (err) {
            const msg = err.response?.data?.message || 'Mã OTP không hợp lệ. Vui lòng thử lại!';
            setError(msg);
            // Reset digits khi sai
            setDigits(Array(OTP_LENGTH).fill(''));
            focusInput(0);
        } finally {
            setLoading(false);
        }
    };

    // Auto-submit khi nhap du 6 so
    useEffect(() => {
        if (isComplete && !loading && !success) {
            handleSubmit();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isComplete]);

    /* ---------- Resend OTP ---------- */
    const handleResend = async () => {
        if (resendCooldown > 0 || resendLoading) return;

        setResendLoading(true);
        setError('');
        setSuccess('');

        try {
            const data = await authApi.resendOtp({ email });
            setSuccess(data.message || 'Đã gửi lại mã OTP!');
            setResendCooldown(RESEND_COOLDOWN);
            setDigits(Array(OTP_LENGTH).fill(''));
            focusInput(0);
        } catch (err) {
            const msg = err.response?.data?.message || 'Không thể gửi lại OTP. Vui lòng thử lại!';
            setError(msg);
        } finally {
            setResendLoading(false);
        }
    };

    /* ---------- Masked email ---------- */
    const maskedEmail = email
        ? email.replace(/(.{2})(.*)(@.*)/, (_, a, b, c) => a + '•'.repeat(Math.min(b.length, 6)) + c)
        : '';

    /* ---------- Animation variants ---------- */
    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: { staggerChildren: 0.08, delayChildren: 0.15 },
        },
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: { duration: 0.6, ease: [0.22, 1, 0.36, 1] },
        },
    };

    /* ---------- Render ---------- */
    return (
        <div className="min-h-screen w-full flex items-center justify-center bg-base-100 font-sans selection:bg-blue-500/30 overflow-hidden relative px-4">

            {/* ---- Animated Background Orbs ---- */}
            <motion.div
                animate={{
                    scale: [1, 1.2, 1],
                    x: [0, 30, 0],
                    y: [0, -20, 0],
                }}
                transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
                className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-blue-500/10 rounded-full blur-[120px] pointer-events-none"
            />
            <motion.div
                animate={{
                    scale: [1.2, 1, 1.2],
                    x: [0, -30, 0],
                    y: [0, 20, 0],
                }}
                transition={{ duration: 12, repeat: Infinity, ease: "easeInOut", delay: 1 }}
                className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-violet-500/10 rounded-full blur-[120px] pointer-events-none"
            />
            <motion.div
                animate={{
                    scale: [1, 1.15, 1],
                    x: [0, -15, 0],
                    y: [0, 15, 0],
                }}
                transition={{ duration: 14, repeat: Infinity, ease: "easeInOut", delay: 2 }}
                className="absolute top-[30%] left-[20%] w-[300px] h-[300px] bg-purple-500/8 rounded-full blur-[100px] pointer-events-none"
            />

            {/* ---- Main Card ---- */}
            <motion.div
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                className="w-full max-w-lg bg-base-100/70 backdrop-blur-xl rounded-[2.5rem] shadow-2xl p-10 sm:p-12 border border-base-200 relative overflow-hidden z-10"
            >
                {/* Accent bar */}
                <div className="absolute top-0 left-0 right-0 h-1.5 bg-gradient-to-r from-blue-600 via-violet-600 to-purple-600" />

                {/* Back link */}
                <motion.div variants={itemVariants}>
                    <Link
                        to="/signup"
                        className="inline-flex items-center gap-2 text-sm font-bold text-base-content/50 hover:text-blue-600 transition-colors mb-8 group"
                    >
                        <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                        Quay lại đăng ký
                    </Link>
                </motion.div>

                {/* Header */}
                <motion.div variants={itemVariants} className="text-center mb-8">
                    {/* Icon */}
                    <motion.div
                        initial={{ scale: 0 }}
                        animate={{ scale: 1 }}
                        transition={{ type: 'spring', stiffness: 200, damping: 15, delay: 0.2 }}
                        className="mx-auto w-20 h-20 bg-gradient-to-br from-blue-500/10 to-violet-500/10 rounded-3xl flex items-center justify-center mb-6 border border-blue-500/20"
                    >
                        <motion.div
                            animate={{ rotate: [0, 5, -5, 0] }}
                            transition={{ duration: 4, repeat: Infinity, ease: 'easeInOut' }}
                        >
                            <Mail className="w-10 h-10 text-blue-600" strokeWidth={1.5} />
                        </motion.div>
                    </motion.div>

                    <h1 className="text-3xl font-black text-base-content mb-3 tracking-tight">
                        Xác minh Email
                    </h1>
                    <p className="text-base-content/60 font-medium text-sm leading-relaxed max-w-sm mx-auto">
                        Chúng tôi đã gửi mã xác minh 6 chữ số đến{' '}
                        <span className="text-blue-600 font-bold">{maskedEmail}</span>
                    </p>
                </motion.div>

                {/* Status messages */}
                {error && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="flex items-center gap-3 p-4 rounded-xl bg-red-500/10 border border-red-500/20 text-red-600 text-sm font-medium mb-6"
                    >
                        <AlertCircle className="w-5 h-5 shrink-0" />
                        {error}
                    </motion.div>
                )}

                {success && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="flex items-center gap-3 p-4 rounded-xl bg-green-500/10 border border-green-500/20 text-green-600 text-sm font-medium mb-6"
                    >
                        <CheckCircle2 className="w-5 h-5 shrink-0" />
                        {success}
                    </motion.div>
                )}

                {/* OTP Input */}
                <form onSubmit={handleSubmit}>
                    <motion.div variants={itemVariants} className="mb-8">
                        <div className="flex items-center justify-center gap-2 sm:gap-3">
                            {digits.map((digit, i) => (
                                <OtpDigitInput
                                    key={i}
                                    index={i}
                                    value={digit}
                                    onChange={handleChange}
                                    onKeyDown={handleKeyDown}
                                    onPaste={handlePaste}
                                    inputRef={(el) => (inputRefs.current[i] = el)}
                                    disabled={loading || !!success}
                                />
                            ))}
                        </div>
                    </motion.div>

                    {/* Submit button */}
                    <motion.div variants={itemVariants}>
                        <motion.button
                            type="submit"
                            disabled={!isComplete || loading || !!success}
                            whileHover={isComplete && !loading ? { scale: 1.02, y: -2 } : {}}
                            whileTap={isComplete && !loading ? { scale: 0.98 } : {}}
                            className={`
                                btn w-full rounded-xl shadow-xl border-none text-base h-12 font-bold
                                group transition-all duration-300
                                ${isComplete && !success
                                    ? 'bg-gradient-to-r from-blue-600 to-violet-600 hover:from-blue-700 hover:to-violet-700 text-white shadow-blue-600/20'
                                    : success
                                        ? 'bg-green-500 text-white'
                                        : 'bg-base-300 text-base-content/40 cursor-not-allowed'
                                }
                            `}
                        >
                            {loading ? (
                                <>
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                    Đang xác minh...
                                </>
                            ) : success ? (
                                <>
                                    <CheckCircle2 className="w-5 h-5" />
                                    Đã xác minh thành công!
                                </>
                            ) : (
                                <>
                                    <ShieldCheck className="w-5 h-5" />
                                    Xác minh
                                    <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                                </>
                            )}
                        </motion.button>
                    </motion.div>
                </form>

                {/* Resend section */}
                <motion.div variants={itemVariants} className="mt-8 text-center">
                    <div className="flex items-center justify-center gap-2 text-sm text-base-content/60 font-medium">
                        {resendCooldown > 0 ? (
                            <p>
                                Gửi lại mã sau <ResendTimer seconds={resendCooldown} />
                            </p>
                        ) : (
                            <p>Chưa nhận được mã?</p>
                        )}
                    </div>

                    {resendCooldown <= 0 && (
                        <motion.button
                            initial={{ opacity: 0, y: 5 }}
                            animate={{ opacity: 1, y: 0 }}
                            onClick={handleResend}
                            disabled={resendLoading || !!success}
                            className="mt-3 inline-flex items-center gap-2 text-sm font-bold text-blue-600 hover:text-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            {resendLoading ? (
                                <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                                <RefreshCw className="w-4 h-4" />
                            )}
                            Gửi lại mã OTP
                        </motion.button>
                    )}
                </motion.div>

                {/* Footer */}
                <motion.div variants={itemVariants} className="mt-10 pt-6 border-t border-base-200">
                    <div className="flex items-center justify-center gap-3 text-base-content/40">
                        <div className="w-8 h-8 bg-gradient-to-br from-blue-600 to-violet-600 rounded-lg flex items-center justify-center">
                            <GraduationCap className="w-4 h-4 text-white" strokeWidth={2.5} />
                        </div>
                        <span className="text-sm font-bold tracking-tight">
                            SKR<span className="text-blue-600">.</span>
                        </span>
                    </div>
                </motion.div>
            </motion.div>
        </div>
    );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import * as motion from 'motion/react-client';
import { AdminLayout } from '../../components/admin';
import {
    Search,
    Plus,
    MoreHorizontal,
    Eye,
    Edit3,
    Trash2,
    Star,
    Users,
    ChevronLeft,
    ChevronRight,
    BookOpen,
    Download,
    Filter,
} from 'lucide-react';

// Animation variants
const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
        opacity: 1,
        transition: { staggerChildren: 0.06, delayChildren: 0.1 }
    }
};

const cardVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
        opacity: 1, y: 0,
        transition: { duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] }
    }
};

// Mock data
const mockCourses = [
    { id: 1, name: 'Toán Cao Cấp Pro', category: 'Toán học', price: '₫299,000', students: 567, rating: 4.8, status: 'published', lessons: 48, image: '📐' },
    { id: 2, name: 'IELTS Speaking Pack', category: 'Tiếng Anh', price: '₫499,000', students: 432, rating: 4.9, status: 'published', lessons: 36, image: '🇬🇧' },
    { id: 3, name: 'Lập Trình Python', category: 'IT', price: '₫199,000', students: 389, rating: 4.7, status: 'published', lessons: 52, image: '🐍' },
    { id: 4, name: 'Data Science Bundle', category: 'IT', price: '₫799,000', students: 245, rating: 4.6, status: 'published', lessons: 80, image: '📊' },
    { id: 5, name: 'Vật Lý Đại Cương', category: 'Vật lý', price: '₫249,000', students: 178, rating: 4.5, status: 'draft', lessons: 30, image: '⚛️' },
    { id: 6, name: 'Hóa Học Hữu Cơ', category: 'Hóa học', price: '₫199,000', students: 0, rating: 0, status: 'draft', lessons: 12, image: '🧪' },
];

const statusConfig = {
    published: { label: 'Đã xuất bản', color: 'text-emerald-600 bg-emerald-500/10' },
    draft: { label: 'Bản nháp', color: 'text-amber-600 bg-amber-500/10' },
    archived: { label: 'Đã lưu trữ', color: 'text-base-content/50 bg-base-200' },
};

export default function AdminCourses() {
    const [searchQuery, setSearchQuery] = useState('');
    const [filterStatus, setFilterStatus] = useState('all');
    const [viewMode, setViewMode] = useState('grid'); // 'grid' | 'table'
    const navigate = useNavigate();

    const filteredCourses = mockCourses.filter(course => {
        const matchSearch = course.name.toLowerCase().includes(searchQuery.toLowerCase());
        const matchStatus = filterStatus === 'all' || course.status === filterStatus;
        return matchSearch && matchStatus;
    });

    return (
        <AdminLayout>
            <motion.div
                variants={containerVariants}
                initial="hidden"
                animate="visible"
            >
                {/* Page Header */}
                <motion.div variants={cardVariants} className="flex flex-wrap items-center justify-between gap-4 mb-6">
                    <div>
                        <h1 className="text-2xl lg:text-3xl font-black text-base-content">Quản lý Khóa học</h1>
                        <p className="text-sm text-base-content/60 mt-1">Tổng cộng {mockCourses.length} khóa học</p>
                    </div>
                    <div className="flex gap-2">
                        <button className="btn btn-sm btn-ghost font-bold rounded-xl gap-1">
                            <Download className="w-4 h-4" />
                            Xuất file
                        </button>
                        <button className="btn btn-sm bg-gradient-to-r from-emerald-600 to-cyan-600 text-white border-none shadow-lg font-bold rounded-xl gap-1">
                            <Plus className="w-4 h-4" />
                            Tạo khóa học
                        </button>
                    </div>
                </motion.div>

                {/* Filters */}
                <motion.div variants={cardVariants} className="bg-base-100 rounded-2xl p-4 shadow-lg border border-base-300 mb-6">
                    <div className="flex flex-wrap items-center gap-3">
                        <div className="relative flex-1 min-w-[200px]">
                            <input
                                type="text"
                                placeholder="Tìm kiếm khóa học..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="input input-bordered w-full pl-10 rounded-xl bg-base-200 border-base-300 focus:border-emerald-500 text-sm"
                            />
                            <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-base-content/40" />
                        </div>
                        <select
                            value={filterStatus}
                            onChange={(e) => setFilterStatus(e.target.value)}
                            className="select select-bordered select-sm rounded-xl bg-base-200 border-base-300 font-bold text-sm"
                        >
                            <option value="all">Tất cả trạng thái</option>
                            <option value="published">Đã xuất bản</option>
                            <option value="draft">Bản nháp</option>
                            <option value="archived">Đã lưu trữ</option>
                        </select>

                        {/* View Mode Toggle */}
                        <div className="flex bg-base-200 rounded-xl p-1">
                            <button
                                onClick={() => setViewMode('grid')}
                                className={`btn btn-xs rounded-lg ${viewMode === 'grid' ? 'bg-base-100 shadow' : 'btn-ghost'}`}
                            >
                                Grid
                            </button>
                            <button
                                onClick={() => setViewMode('table')}
                                className={`btn btn-xs rounded-lg ${viewMode === 'table' ? 'bg-base-100 shadow' : 'btn-ghost'}`}
                            >
                                Table
                            </button>
                        </div>
                    </div>
                </motion.div>

                {/* Courses Grid View */}
                {viewMode === 'grid' ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                        {filteredCourses.map((course, i) => (
                            <CourseCard key={course.id} course={course} index={i} onView={() => navigate(`/admin/courses/${course.id}`)} />
                        ))}
                    </div>
                ) : (
                    /* Table View */
                    <motion.div variants={cardVariants} className="bg-base-100 rounded-3xl shadow-lg border border-base-300 overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="table">
                                <thead>
                                    <tr className="bg-base-200/50">
                                        <th className="font-bold text-xs uppercase text-base-content/60">Khóa học</th>
                                        <th className="font-bold text-xs uppercase text-base-content/60">Danh mục</th>
                                        <th className="font-bold text-xs uppercase text-base-content/60">Giá</th>
                                        <th className="font-bold text-xs uppercase text-base-content/60">Học viên</th>
                                        <th className="font-bold text-xs uppercase text-base-content/60">Đánh giá</th>
                                        <th className="font-bold text-xs uppercase text-base-content/60">Trạng thái</th>
                                        <th className="font-bold text-xs uppercase text-base-content/60">Hành động</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredCourses.map((course, i) => {
                                        const status = statusConfig[course.status];
                                        return (
                                            <motion.tr
                                                key={course.id}
                                                initial={{ opacity: 0, y: 10 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                transition={{ delay: 0.3 + i * 0.05 }}
                                                className="hover:bg-base-200/50 cursor-pointer group"
                                            >
                                                <td>
                                                    <div className="flex items-center gap-3">
                                                        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500/10 to-violet-500/10 flex items-center justify-center text-xl">
                                                            {course.image}
                                                        </div>
                                                        <div>
                                                            <p className="font-bold text-sm text-base-content">{course.name}</p>
                                                            <p className="text-xs text-base-content/50">{course.lessons} bài học</p>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td><span className="badge badge-sm badge-ghost font-bold">{course.category}</span></td>
                                                <td><span className="font-bold text-sm">{course.price}</span></td>
                                                <td>
                                                    <span className="flex items-center gap-1 text-sm">
                                                        <Users className="w-3 h-3 text-base-content/40" />
                                                        <span className="font-bold">{course.students}</span>
                                                    </span>
                                                </td>
                                                <td>
                                                    {course.rating > 0 ? (
                                                        <span className="flex items-center gap-1 text-sm">
                                                            <Star className="w-3 h-3 fill-amber-400 text-amber-400" />
                                                            <span className="font-bold">{course.rating}</span>
                                                        </span>
                                                    ) : (
                                                        <span className="text-xs text-base-content/40">N/A</span>
                                                    )}
                                                </td>
                                                <td>
                                                    <span className={`text-xs font-bold px-2 py-1 rounded-lg ${status.color}`}>
                                                        {status.label}
                                                    </span>
                                                </td>
                                                <td>
                                                    <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                        <button onClick={() => navigate(`/admin/courses/${course.id}`)} className="btn btn-ghost btn-xs btn-circle" title="Xem"><Eye className="w-3.5 h-3.5" /></button>
                                                        <button className="btn btn-ghost btn-xs btn-circle" title="Sửa"><Edit3 className="w-3.5 h-3.5" /></button>
                                                        <button className="btn btn-ghost btn-xs btn-circle text-red-500" title="Xóa"><Trash2 className="w-3.5 h-3.5" /></button>
                                                    </div>
                                                </td>
                                            </motion.tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </motion.div>
                )}
            </motion.div>
        </AdminLayout>
    );
}

// ===== Course Card Component =====
function CourseCard({ course, index, onView }) {
    const status = statusConfig[course.status];

    return (
        <motion.div
            variants={cardVariants}
            whileHover={{ y: -4 }}
            className="bg-base-100 rounded-2xl shadow-lg border border-base-300 overflow-hidden group hover:shadow-xl transition-shadow"
        >
            {/* Header with emoji icon */}
            <div className="bg-gradient-to-br from-blue-500/5 to-violet-500/5 p-6 flex items-center justify-between">
                <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-blue-600/10 to-violet-600/10 flex items-center justify-center text-4xl border border-blue-500/10">
                    {course.image}
                </div>
                <div className="flex flex-col items-end gap-2">
                    <span className={`text-xs font-bold px-2.5 py-1 rounded-lg ${status.color}`}>
                        {status.label}
                    </span>
                    <button className="btn btn-ghost btn-xs btn-circle opacity-0 group-hover:opacity-100 transition-opacity">
                        <MoreHorizontal className="w-4 h-4" />
                    </button>
                </div>
            </div>

            {/* Body */}
            <div className="p-5">
                <h3 className="font-black text-base text-base-content mb-1 truncate">{course.name}</h3>
                <p className="text-xs text-base-content/60 mb-4">
                    {course.category} • {course.lessons} bài học
                </p>

                {/* Stats */}
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                        <span className="flex items-center gap-1 text-xs text-base-content/70">
                            <Users className="w-3 h-3" />
                            <span className="font-bold">{course.students}</span>
                        </span>
                        {course.rating > 0 && (
                            <span className="flex items-center gap-1 text-xs text-base-content/70">
                                <Star className="w-3 h-3 fill-amber-400 text-amber-400" />
                                <span className="font-bold">{course.rating}</span>
                            </span>
                        )}
                    </div>
                    <span className="font-black text-base-content">{course.price}</span>
                </div>

                {/* Actions */}
                <div className="flex gap-2">
                    <button className="btn btn-sm flex-1 btn-ghost rounded-xl font-bold gap-1">
                        <Edit3 className="w-3.5 h-3.5" />
                        Sửa
                    </button>
                    <button onClick={onView} className="btn btn-sm flex-1 bg-gradient-to-r from-emerald-600 to-cyan-600 text-white border-none rounded-xl font-bold gap-1">
                        <Eye className="w-3.5 h-3.5" />
                        Xem
                    </button>
                </div>
            </div>
        </motion.div>
    );
}

