                            />
                            <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-base-content/40" />
                        </div>
                        <select
                            value={filterStatus}
                            onChange={(e) => setFilterStatus(e.target.value)}
                            className="select select-bordered select-sm rounded-xl bg-base-200 border-base-300 font-bold text-sm"
                        >
                            <option value="all">Tất cả trạng thái</option>
                            <option value="completed">Hoàn thành</option>
                            <option value="pending">Đang xử lý</option>
                            <option value="cancelled">Đã hủy</option>
                        </select>
                    </div>
                </motion.div>

                {/* Orders Table */}
                <motion.div variants={cardVariants} className="bg-base-100 rounded-3xl shadow-lg border border-base-300 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="table">
                            <thead>
                                <tr className="bg-base-200/50">
                                    <th className="font-bold text-xs uppercase text-base-content/60">Mã đơn</th>
                                    <th className="font-bold text-xs uppercase text-base-content/60">Khách hàng</th>
                                    <th className="font-bold text-xs uppercase text-base-content/60">Khóa học</th>
                                    <th className="font-bold text-xs uppercase text-base-content/60">Số tiền</th>
                                    <th className="font-bold text-xs uppercase text-base-content/60">Thanh toán</th>
                                    <th className="font-bold text-xs uppercase text-base-content/60">Trạng thái</th>
                                    <th className="font-bold text-xs uppercase text-base-content/60">Ngày tạo</th>
                                    <th className="font-bold text-xs uppercase text-base-content/60">Chi tiết</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredOrders.map((order, i) => {
                                    const status = statusConfig[order.status];
                                    const StatusIcon = status.icon;
                                    return (
                                        <motion.tr
                                            key={order.id}
                                            initial={{ opacity: 0, y: 10 }}
                                            animate={{ opacity: 1, y: 0 }}
                                            transition={{ delay: 0.3 + i * 0.05 }}
                                            className="hover:bg-base-200/50 cursor-pointer group"
                                        >
                                            <td>
                                                <span className="font-mono font-bold text-sm text-base-content">{order.id}</span>
                                            </td>
                                            <td>
                                                <div className="flex items-center gap-3">
                                                    <div className="avatar">
                                                        <div className="w-8 h-8 rounded-full">
                                                            <img src={order.avatar} alt={order.user} />
                                                        </div>
                                                    </div>
                                                    <div>
                                                        <p className="font-bold text-sm">{order.user}</p>
                                                        <p className="text-xs text-base-content/50">{order.email}</p>
                                                    </div>
                                                </div>
                                            </td>
                                            <td>
                                                <p className="font-bold text-sm truncate max-w-[160px]">{order.course}</p>
                                            </td>
                                            <td>
                                                <span className="font-black text-sm text-base-content">{order.amount}</span>
                                            </td>
                                            <td>
                                                <span className="badge badge-sm badge-ghost font-bold">{order.payment}</span>
                                            </td>
                                            <td>
                                                <span className={`flex items-center gap-1 text-xs font-bold px-2 py-1 rounded-lg w-fit ${status.color}`}>
                                                    <StatusIcon className="w-3 h-3" />
                                                    {status.label}
                                                </span>
                                            </td>
                                            <td>
                                                <span className="text-xs text-base-content/60">{order.date}</span>
                                            </td>
                                            <td>
                                                <button className="btn btn-ghost btn-xs btn-circle opacity-0 group-hover:opacity-100 transition-opacity" title="Xem chi tiết">
                                                    <Eye className="w-3.5 h-3.5" />
                                                </button>
                                            </td>
                                        </motion.tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    {/* Pagination */}
                    <div className="flex items-center justify-between px-6 py-4 border-t border-base-300">
                        <p className="text-sm text-base-content/60">
                            Hiển thị <span className="font-bold">1-{filteredOrders.length}</span> trong tổng <span className="font-bold">{mockOrders.length}</span> đơn hàng
                        </p>
                        <div className="flex items-center gap-1">
                            <button className="btn btn-sm btn-ghost btn-circle">
                                <ChevronLeft className="w-4 h-4" />
                            </button>
                            <button className="btn btn-sm bg-gradient-to-r from-emerald-600 to-cyan-600 text-white border-none font-bold min-w-[2rem]">1</button>
                            <button className="btn btn-sm btn-ghost font-bold min-w-[2rem]">2</button>
                            <button className="btn btn-sm btn-ghost font-bold min-w-[2rem]">3</button>
                            <button className="btn btn-sm btn-ghost btn-circle">
                                <ChevronRight className="w-4 h-4" />
                            </button>
                        </div>
                    </div>
                </motion.div>
            </motion.div>
        </AdminLayout>
    );
}

import { useState } from 'react';
import * as motion from 'motion/react-client';
import { Settings as SettingsIcon, Layout, Mail, Server, ShieldCheck } from 'lucide-react';
import { AdminLayout } from '../../components/admin';
import { GeneralSettings, HomepageSettings, containerVariants } from '../../components/admin/adminSettings';

export default function AdminSettings() {
    const [activeTab, setActiveTab] = useState('homepage');
    const [isDirty, setDirty] = useState(false); // check if unsaved changes exist

    const tabs = [
        { id: 'general', label: 'Cài đặt chung', icon: SettingsIcon },
        { id: 'homepage', label: 'Trang chủ', icon: Layout },
        { id: 'emails', label: 'Email system', icon: Mail },
        { id: 'security', label: 'Bảo mật', icon: ShieldCheck },
        { id: 'system', label: 'Hệ thống', icon: Server },
    ];

    const handleTabChange = (tabId) => {
        if (isDirty) {
            if (window.confirm("Bạn có thay đổi chưa lưu, vẫn muốn chuyển tab?")) {
                setDirty(false);
                setActiveTab(tabId);
            }
        } else {
            setActiveTab(tabId);
        }
    };

    return (
        <AdminLayout>
            <motion.div
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                className="w-full max-w-[1600px] mx-auto space-y-6"
            >
                {/* ===== HEADER ===== */}
                <motion.div className="mb-6">
                    <h1 className="text-2xl lg:text-3xl font-black text-base-content flex items-center gap-3">
                        <SettingsIcon className="w-8 h-8 text-blue-500" />
                        Cài đặt Hệ thống
                    </h1>
                    <p className="text-sm text-base-content/60 mt-2 max-w-2xl leading-relaxed">
                        Quản lý toàn bộ cấu hình lõi của ứng dụng. Vui lòng cẩn trọng khi sửa đổi nội dung ở đây vì nó ảnh hưởng trực tiếp tới toàn bộ người dùng public và luồng hoạt động chính.
                    </p>
                </motion.div>

                <div className="flex flex-col lg:flex-row gap-8">
                    {/* Left: TABS (Sidebar) */}
                    <div className="lg:w-64 flex-shrink-0">
                        <ul className="menu bg-base-100/50 rounded-2xl p-3 border border-base-200/50 gap-1.5 shadow-sm sticky top-6">
                            {tabs.map(tab => (
                                <li key={tab.id}>
                                    <button
                                        onClick={() => handleTabChange(tab.id)}
                                        className={`gap-3 font-bold rounded-xl py-3 px-4 transition-all ${activeTab === tab.id
                                            ? 'bg-gradient-to-r from-blue-600 to-violet-600 text-white shadow-md shadow-blue-500/20 active:bg-blue-600 focus:bg-blue-600'
                                            : 'text-base-content/60 hover:bg-base-200 hover:text-base-content'
                                            }`}
                                    >
                                        <tab.icon className={`w-4 h-4 ${activeTab === tab.id ? 'text-white' : ''}`} />
                                        {tab.label}
                                    </button>
                                </li>
                            ))}
                        </ul>
                    </div>

                    {/* Right: CONTENT CONFIG */}
                    <div className="flex-1 min-w-0">
                        <div className={activeTab === 'general' ? 'block' : 'hidden'}>
                            <GeneralSettings />
                        </div>
                        <div className={activeTab === 'homepage' ? 'block' : 'hidden'}>
                            <HomepageSettings isDirty={isDirty} setDirty={setDirty} />
                        </div>

                        {/* Placeholder for other tabs */}
                        {['emails', 'security', 'system'].includes(activeTab) && (
                            <div className="bg-base-100 rounded-2xl shadow-sm border border-base-300 p-12 text-center text-base-content/40 font-bold border-dashed h-[400px] flex items-center justify-center flex-col gap-4">
                                <Server className="w-12 h-12 opacity-20" />
                                Modul đang được xây dựng ({tabTitleFromId(tabs, activeTab)})
                            </div>
                        )}
                    </div>
                </div>
            </motion.div>
        </AdminLayout>
    );
}

function tabTitleFromId(tabs, id) {
    const r = tabs.find(t => t.id === id);
    return r ? r.label : id;
}

import { useState } from 'react';
import * as motion from 'motion/react-client';
import { AnimatePresence } from 'motion/react';
import { AdminLayout } from '../../components/admin';
import { Search, UserPlus, UsersRound } from 'lucide-react';
import {
    containerVariants,
    cardVariants,
    statusConfig,
    mockUsers,
    UserRow,
    AddUserModal,
    UserDetailModal,
} from '../../components/admin/adminUsers';

/**
 * AdminUsers - Trang quản lý người dùng.
 * Components được tách riêng trong components/admin/adminUsers/.
 */
export default function AdminUsers() {
    const [searchTerm, setSearchTerm] = useState('');
    const [roleFilter, setRoleFilter] = useState('all');
    const [statusFilter, setStatusFilter] = useState('all');
    const [showAddModal, setShowAddModal] = useState(false);
    const [selectedUser, setSelectedUser] = useState(null);

    const filteredUsers = mockUsers.filter((user) => {
        const matchesSearch =
            user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            user.email.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesRole = roleFilter === 'all' || user.role === roleFilter;
        const matchesStatus = statusFilter === 'all' || user.status === statusFilter;
        return matchesSearch && matchesRole && matchesStatus;
    });

    return (
        <AdminLayout>
            <motion.div variants={containerVariants} initial="hidden" animate="visible" className="space-y-6">
                {/* Page Header */}
                <motion.div variants={cardVariants} className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h1 className="text-2xl font-black text-base-content">Quản lý Người dùng</h1>
                        <p className="text-sm text-base-content/60 mt-1">
                            Tổng cộng <span className="font-bold text-emerald-600">{mockUsers.length}</span> người dùng
                        </p>
                    </div>
                    <button
                        onClick={() => setShowAddModal(true)}
                        className="btn bg-gradient-to-r from-emerald-600 to-cyan-600 text-white border-none shadow-lg font-bold rounded-xl hover:shadow-emerald-500/25 hover:shadow-xl transition-all"
                    >
                        <UserPlus className="w-4 h-4" /> Thêm người dùng
                    </button>
                </motion.div>

                {/* Filters */}
                <motion.div variants={cardVariants} className="flex flex-col md:flex-row gap-3">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-base-content/40" />
                        <input type="text" placeholder="Tìm kiếm theo tên hoặc email..."
                            value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
                            className="input input-bordered w-full pl-10 rounded-xl bg-base-200 border-base-300 focus:border-emerald-500 text-sm"
                        />
                    </div>
                    <select value={roleFilter} onChange={(e) => setRoleFilter(e.target.value)}
                        className="select select-bordered rounded-xl bg-base-200 border-base-300 text-sm font-bold"
                    >
                        <option value="all">Tất cả vai trò</option>
                        <option value="Learner">Learner</option>
                        <option value="Expert">Expert</option>
                        <option value="Staff">Staff</option>
                        <option value="Admin">Admin</option>
                    </select>
                    <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}
                        className="select select-bordered rounded-xl bg-base-200 border-base-300 text-sm font-bold"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        {Object.entries(statusConfig).map(([key, cfg]) => (
                            <option key={key} value={key}>{cfg.label}</option>
                        ))}
                    </select>
                </motion.div>

                {/* Users Table */}
                <motion.div variants={cardVariants} className="bg-base-100 rounded-2xl shadow-xl border border-base-300 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="table">
                            <thead>
                                <tr className="bg-base-200/50">
                                    <th className="font-bold text-xs uppercase tracking-wider text-base-content/60">Người dùng</th>
                                    <th className="font-bold text-xs uppercase tracking-wider text-base-content/60">Vai trò</th>
                                    <th className="font-bold text-xs uppercase tracking-wider text-base-content/60">Trạng thái</th>
                                    <th className="font-bold text-xs uppercase tracking-wider text-base-content/60">Khóa học</th>
                                    <th className="font-bold text-xs uppercase tracking-wider text-base-content/60">Ngày tham gia</th>
                                    <th className="font-bold text-xs uppercase tracking-wider text-base-content/60">Hoạt động</th>
                                    <th className="font-bold text-xs uppercase tracking-wider text-base-content/60">Hành động</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredUsers.length > 0 ? (
                                    filteredUsers.map((user, i) => (
                                        <UserRow key={user.id} user={user} index={i} onViewDetail={() => setSelectedUser(user)} />
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan="7" className="text-center py-10">
                                            <UsersRound className="w-10 h-10 text-base-content/20 mx-auto mb-3" />
                                            <p className="text-sm text-base-content/50 font-bold">Không tìm thấy người dùng nào</p>
                                            <p className="text-xs text-base-content/30 mt-1">Thử thay đổi bộ lọc hoặc từ khóa tìm kiếm</p>
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </motion.div>
            </motion.div>

            {/* Modals */}
            <AnimatePresence>
                {showAddModal && <AddUserModal key="add-modal" onClose={() => setShowAddModal(false)} />}
            </AnimatePresence>
            <AnimatePresence>
                {selectedUser && <UserDetailModal key="detail-modal" user={selectedUser} onClose={() => setSelectedUser(null)} />}
            </AnimatePresence>
        </AdminLayout>
    );
}
